-- UT-L2 Module 2 — Advanced Wave Physics (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Tipe gelombang ultrasonik & kecepatan', '{"slides":[{"heading":"Empat mode gelombang utama","body":"Di Level II, kita harus paham bahwa material mendukung beberapa mode gelombang: longitudinal (compression), shear (transverse), surface (Rayleigh), dan plate/guided wave (Lamb). Longitudinal merambat dengan osilasi partikel sejajar arah propagasi; shear dengan osilasi tegak lurus arah propagasi. Pilihan mode menentukan teknik inspeksi: straight-beam pakai longitudinal, angle-beam weld pakai shear."},{"heading":"Kecepatan tiap mode (baja)","body":"Pada baja karbon: longitudinal Vl kira-kira 5900 m/s, shear Vs kira-kira 3230 m/s, dan Rayleigh kira-kira 2900-3000 m/s (sekitar 0.9 Vs). Rasio Vs/Vl kira-kira 0.55 untuk baja (3230/5900 = 0.55). Angka ini bukan hafalan kosong: rasio kecepatan inilah yang menentukan sudut refraksi dan critical angle saat gelombang menembus interface wedge ke material uji."},{"heading":"Kenapa wavelength shear lebih pendek","body":"Pada frekuensi sama, wavelength shear lebih pendek dari longitudinal karena kecepatannya lebih rendah (lambda = V/f). Contoh pada 2.25 MHz di baja: lambda longitudinal kira-kira 2.6 mm (5900/2.25e6), lambda shear kira-kira 1.4 mm (3230/2.25e6). Wavelength lebih pendek berarti resolusi & sensitivitas terhadap cacat kecil lebih baik — salah satu alasan angle-beam shear disukai untuk weld inspection."},{"heading":"Shear wave tidak merambat di cairan/gas","body":"Gelombang shear butuh medium yang mendukung gaya geser (shear modulus > 0), sehingga hanya merambat di solid — bukan di cairan atau gas. Inilah dasar immersion testing: di air hanya longitudinal yang merambat, lalu dikonversi menjadi shear pada interface ketika masuk benda uji dengan sudut datang tertentu (di atas first critical angle). Konsep ini wajib dipahami sebelum masuk mode conversion."}]}', 460, NULL),
  (2, 'reading', 'Mode conversion & Snell''s Law', '{"slides":[{"heading":"Snell''s Law sebagai dasar","body":"Saat gelombang melewati interface dua material, sudut refraksi mengikuti Snell''s Law: sin(theta1)/V1 = sin(theta2)/V2. Karena setiap mode punya kecepatan berbeda, satu gelombang datang bisa menghasilkan refracted longitudinal DAN refracted shear sekaligus pada sudut yang berbeda. Inilah akar fenomena mode conversion."},{"heading":"First & second critical angle","body":"First critical angle = sudut datang di mana refracted longitudinal mencapai 90 derajat (merambat sepanjang permukaan lalu hilang); di atas sudut ini hanya tinggal shear di benda uji. Untuk wedge acrylic/Perspex (V kira-kira 2730 m/s) ke baja: first critical kira-kira 27.5 derajat (sin = 2730/5900), second critical kira-kira 57-58 derajat (sin = 2730/3230). Probe angle-beam standar (45/60/70 derajat shear) sengaja dirancang di antara kedua critical angle ini supaya hanya shear murni yang masuk."},{"heading":"Second critical & surface wave","body":"Pada second critical angle, refracted shear mencapai 90 derajat dan berubah menjadi surface (Rayleigh) wave yang menjalar di permukaan benda uji. Inilah cara praktis membangkitkan surface wave: pilih wedge angle tepat di atas second critical angle. Memahami batas ini mencegah kesalahan setup — misalnya angle-beam yang tidak sengaja menghasilkan dua beam (shear + spurious longitudinal) bila sudut di bawah first critical angle."},{"heading":"Implikasi praktis mode conversion","body":"Mode conversion bukan hanya teori — di lapangan ia menciptakan sinyal palsu. Contoh klasik: shear wave yang mengenai dinding belakang atau cacat planar bisa convert sebagian menjadi longitudinal, menghasilkan indikasi pada screen position / sound path yang tidak terduga. Level II harus bisa mengenali corner-trap & mode-converted echo (misalnya pada inspeksi lack-of-fusion atau crack) agar tidak salah evaluasi sizing atau salah panggil cacat."}]}', 500, NULL),
  (3, 'reading', 'Surface (Rayleigh) waves', '{"slides":[{"heading":"Karakteristik Rayleigh wave","body":"Surface wave merambat di lapisan permukaan dengan kedalaman penetrasi efektif kira-kira satu wavelength. Osilasi partikelnya elips/retrograde (kombinasi komponen longitudinal & vertikal). Kecepatannya kira-kira 0.9 Vs (sekitar 2900-3000 m/s di baja). Karena energi terkonsentrasi di permukaan, Rayleigh sangat sensitif terhadap surface & near-surface crack, namun cepat melemah bila ada couplant, cat, atau kontaminasi di jalur permukaan."},{"heading":"Aplikasi & keunggulan","body":"Rayleigh wave dipakai untuk deteksi surface-breaking crack pada komponen yang permukaannya bergeometri kompleks — misalnya turbine blade, shaft fillet, gear teeth. Keunggulannya: dapat mengikuti kontur permukaan yang melengkung (selama radius tidak terlalu tajam relatif terhadap wavelength) dan menjangkau area yang sulit diakses straight/angle beam konvensional."},{"heading":"Keterbatasan & sumber sinyal palsu","body":"Rayleigh wave akan dipantulkan oleh setiap diskontinuitas geometri di permukaan: ujung benda (edge), alur, tetesan couplant berlebih, bahkan jari operator yang menyentuh permukaan di depan probe. Karena itu interpretasi butuh kehati-hatian. Teknik konfirmasi: sentuh permukaan dengan jari beroli di depan probe — indikasi dari geometri/permukaan akan teredam, bergeser, atau hilang; sedangkan indikasi dari crack yang lebih dalam relatif tetap. Ini trik standar Level II untuk membedakan crack dari geometry."}]}', 440, NULL),
  (4, 'reading', 'Lamb (guided) waves untuk material tipis', '{"slides":[{"heading":"Apa itu Lamb wave","body":"Lamb wave adalah guided wave yang terbentuk pada pelat tipis (ketebalan sebanding dengan orde wavelength), di mana gelombang dipandu oleh dua permukaan paralel pelat. Berbeda dengan bulk wave, energi menjalar sepanjang pelat, memungkinkan inspeksi area luas dari satu posisi probe — berguna untuk sheet, tube tipis, dan composite skin."},{"heading":"Mode symmetric & asymmetric","body":"Lamb wave punya dua famili mode: symmetric (S0, S1, ...) di mana gerak simetris terhadap midplane pelat, dan asymmetric/anti-symmetric (A0, A1, ...) yang bersifat flexural. Setiap mode bersifat dispersif: kecepatannya bergantung pada produk frekuensi x ketebalan (f-d product). Karena itu setup butuh dispersion curve untuk memilih titik kerja yang stabil dan mode yang diinginkan."},{"heading":"Dispersi & pemilihan titik kerja","body":"Sifat dispersif berarti pulse bisa melebar (pulse spreading) saat menjalar, menurunkan resolusi. Level II memilih kombinasi frekuensi & sudut excitation (sering pakai variable-angle wedge atau probe array) yang menghasilkan mode tunggal pada region f-d yang relatif flat di dispersion curve. Memilih mode A0 di f-d rendah, misalnya, sering dipakai untuk deteksi corrosion thinning & delaminasi karena A0 sensitif terhadap perubahan kondisi pelat."},{"heading":"Aplikasi composite & thin material","body":"Pada composite (CFRP/GFRP) dan honeycomb, Lamb wave dipakai untuk deteksi delaminasi, disbond, dan impact damage — defect yang sulit dideteksi bulk wave karena anisotropi & atenuasi tinggi material composite. Pada thin plate/tube, Lamb (dan torsional/longitudinal guided wave untuk pipa panjang) memberi screening cepat: satu set probe bisa cover beberapa meter, lalu temuan ditindaklanjuti dengan UT konvensional/PAUT untuk sizing presisi."}]}', 510, NULL),
  (5, 'quiz', 'Mini-quiz — Advanced Wave Physics', '{"description":"Konfirmasi pemahaman mode gelombang & kecepatan, mode conversion & critical angle, surface (Rayleigh) wave, dan Lamb wave untuk material tipis & composite.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 2
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 2 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada baja karbon, perkiraan kecepatan gelombang shear (transverse) adalah sekitar...',
   '["3230 m/s","5900 m/s","1480 m/s","330 m/s"]', 0,
   'Kecepatan shear di baja kira-kira 3230 m/s, sekitar 0.55x kecepatan longitudinal (kira-kira 5900 m/s). Nilai 1480 m/s adalah kecepatan suara di air dan 330 m/s di udara.', 'Wave Velocity', 'easy'),
  ('Mengapa gelombang shear tidak dapat merambat di dalam cairan?',
   '["Karena frekuensinya terlalu tinggi untuk cairan","Karena cairan tidak mendukung gaya geser (shear modulus = 0)","Karena wavelength shear terlalu panjang","Karena cairan menyerap seluruh energi longitudinal"]', 1,
   'Gelombang shear membutuhkan medium yang mampu menahan deformasi geser. Cairan dan gas tidak punya shear modulus, sehingga hanya mendukung gelombang longitudinal. Inilah dasar konversi mode pada immersion testing.', 'Wave Modes', 'medium'),
  ('First critical angle didefinisikan sebagai sudut datang di mana...',
   '["Refracted shear wave mencapai 90 derajat","Seluruh energi dipantulkan kembali (total reflection)","Refracted longitudinal wave mencapai 90 derajat dan hilang","Surface wave berubah menjadi bulk wave"]', 2,
   'Pada first critical angle, refracted longitudinal mencapai 90 derajat sehingga hanya tersisa refracted shear di benda uji. Refracted shear mencapai 90 derajat pada second critical angle, yang membangkitkan surface wave.', 'Mode Conversion', 'medium'),
  ('Probe angle-beam shear standar (mis. 45/60/70 derajat) dirancang bekerja pada rentang sudut...',
   '["Di bawah first critical angle","Jauh di atas second critical angle","Di antara first dan second critical angle","Tepat pada first critical angle"]', 2,
   'Di antara first dan second critical angle hanya gelombang shear yang merambat di benda uji (longitudinal sudah hilang, shear belum berubah menjadi surface wave). Ini memastikan beam tunggal shear murni tanpa spurious longitudinal.', 'Mode Conversion', 'hard'),
  ('Kedalaman penetrasi efektif gelombang Rayleigh (surface) wave kira-kira sebesar...',
   '["Tidak terbatas selama couplant cukup","Sepuluh wavelength","Setengah ketebalan benda uji","Satu wavelength"]', 3,
   'Energi Rayleigh wave terkonsentrasi pada lapisan permukaan dengan kedalaman efektif kira-kira satu wavelength. Karena itu sangat sensitif terhadap surface & near-surface crack, tetapi mudah teredam oleh couplant atau kontaminasi permukaan.', 'Surface Waves', 'medium'),
  ('Teknik standar Level II untuk membedakan indikasi crack dari indikasi geometri saat memakai surface wave adalah...',
   '["Menaikkan gain hingga indikasi geometri hilang","Menyentuh permukaan dengan jari beroli di depan probe — indikasi geometri/permukaan teredam atau hilang, indikasi crack relatif tetap","Mengganti probe ke frekuensi lebih tinggi","Membalik polaritas pulser"]', 1,
   'Couplant/jari beroli yang menyentuh permukaan di depan probe meredam (damping) energi surface wave; indikasi dari permukaan/geometri akan terpengaruh, sedangkan indikasi dari crack yang lebih dalam relatif tetap. Ini cara cepat dan andal untuk konfirmasi.', 'Surface Waves', 'hard'),
  ('Karakteristik utama Lamb (guided) wave yang membuat setup-nya kompleks adalah...',
   '["Hanya bisa dibangkitkan pada material tebal","Tidak dapat mendeteksi cacat planar","Bersifat dispersif — kecepatan bergantung pada produk frekuensi x ketebalan (f-d)","Selalu menjalar tegak lurus permukaan pelat"]', 2,
   'Lamb wave bersifat dispersif: kecepatan tiap mode (S0, A0, dst) bergantung pada f-d product, sehingga butuh dispersion curve untuk memilih titik kerja stabil dan mode tunggal yang diinginkan.', 'Lamb Waves', 'medium'),
  ('Lamb wave paling tepat diaplikasikan untuk mendeteksi...',
   '["Delaminasi dan disbond pada composite skin serta thinning pada pelat tipis","Inklusi volumetrik dalam coran tebal 200 mm","Cacat sub-surface pada forging diameter besar","Porositas dalam weld root pipa schedule 80"]', 0,
   'Lamb wave dipandu oleh dua permukaan pelat tipis dan menjalar sepanjang material, ideal untuk screening area luas pada thin plate/tube dan deteksi delaminasi/disbond pada composite di mana bulk wave terhambat anisotropi & atenuasi tinggi. Material tebal & komponen masif justru ranah bulk wave.', 'Lamb Waves', 'easy')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 4 — Time-of-Flight Diffraction (TOFD) (6 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Prinsip TOFD — sinyal diffraction', '{"slides":[{"heading":"Konsep dasar","body":"Time-of-Flight Diffraction (TOFD) tidak mengandalkan amplitudo pantulan (seperti pulse-echo konvensional), melainkan energi yang ter-diffraksi dari TIP (ujung) cacat. Saat gelombang ultrasonic mengenai ujung tajam crack, ujung itu bertindak sebagai titik sumber (Huygens point source) yang me-radiasikan gelombang ke segala arah. Energi diffraksi inilah yang ditangkap, bukan reflection besar dari permukaan cacat. Karena tidak bergantung pada amplitudo pantulan spekular, TOFD relatif tidak sensitif terhadap orientasi cacat — keunggulan utama dibanding pulse-echo yang amat bergantung pada sudut hadap (angle of incidence)."},{"heading":"Konfigurasi transmitter-receiver","body":"TOFD memakai dua probe terpisah: satu transmitter dan satu receiver, dipasang berseberangan (pitch-catch) mengapit weld pada Probe Centre Spacing (PCS) tetap. Kedua probe adalah angle-beam dan memakai gelombang longitudinal (compression), umumnya 45-70°, sering 60-70° untuk ketebalan tipis-sedang. Gelombang longitudinal dipilih karena kecepatannya lebih tinggi (~5900 m/s di baja, vs ~3230 m/s untuk shear) sehingga sinyalnya tiba lebih dulu dan terpisah jelas dari mode shear yang mengikuti di belakang."},{"heading":"Empat sinyal kunci","body":"A-scan TOFD menampilkan urutan tipikal: (1) Lateral wave — gelombang yang merambat tepat di bawah permukaan scan dari Tx ke Rx, sinyal pertama yang tiba; (2) sinyal diffraksi dari upper tip cacat; (3) sinyal diffraksi dari lower tip cacat; (4) Backwall echo — pantulan dari dinding belakang, sinyal terakhir (sebelum mode-converted signals). Posisi sinyal cacat di antara lateral wave dan backwall menunjukkan kedalaman, dan selisih waktu antara upper tip dan lower tip memberi tinggi (through-wall height) cacat."},{"heading":"Mengapa sizing akurat","body":"Akurasi tinggi TOFD berasal dari pengukuran WAKTU (time-of-flight), bukan amplitudo. Pengukuran waktu jauh lebih stabil terhadap variasi coupling, surface condition, dan gain. Akurasi height sizing TOFD tipikal sekitar +/-1 mm bila setup benar, jauh lebih baik daripada teknik amplitude-based seperti 6 dB drop untuk through-wall height. Inilah alasan TOFD menjadi tool pilihan untuk monitoring pertumbuhan crack (crack growth trending) pada program fitness-for-service (FFS)."}]}', 480, NULL),
  (2, 'reading', 'Geometri setup & PCS', '{"slides":[{"heading":"Probe Centre Spacing (PCS)","body":"PCS adalah jarak antara kedua titik exit probe (atau, pada beberapa standar, antara index point), parameter geometri paling kritis di TOFD. Untuk single-zone, PCS diatur agar perpotongan (intersection) sumbu kedua beam berada sekitar 2/3 ketebalan (two-thirds depth) dari permukaan scan. Di sekitar titik perpotongan inilah coverage dan sensitivitas paling merata. PCS terlalu kecil memperbesar dead zone dekat permukaan; PCS terlalu lebar melemahkan sinyal di bagian dalam dan dekat backwall."},{"heading":"Pemilihan sudut & frekuensi","body":"Sudut probe dipilih sesuai depth of interest dan ketebalan: sudut tinggi (~70°) cocok untuk wall tipis (mis. <15 mm), ~60° untuk ketebalan sedang, dan sudut lebih rendah (45-60°) untuk wall tebal yang umumnya butuh beberapa zona. Frekuensi tipikal 5-15 MHz; frekuensi tinggi memberi resolusi waktu/spatial lebih baik (penting untuk memisahkan upper & lower tip cacat kecil) tetapi attenuasi lebih besar pada material tebal atau attenuatif (mis. coarse-grained / austenitic)."},{"heading":"Multi-zone untuk wall tebal","body":"Untuk ketebalan besar (mis. >50-100 mm), satu pasang probe tidak dapat meng-cover seluruh kedalaman dengan sensitivitas merata. Solusinya membagi ketebalan menjadi beberapa zona depth, masing-masing dengan PCS dan sudut sendiri (multi-zone / multi-probe TOFD). Tiap zona di-optimasi agar intersection beam-nya berada di sekitar 2/3 depth zona tersebut, sehingga gabungan zona menjamin coverage menyeluruh dari near-surface sampai backwall."},{"heading":"Encoder & coupling","body":"TOFD adalah teknik encoded scanning: encoder mekanis mencatat posisi probe sepanjang weld sehingga setiap A-scan ter-link ke posisi (mm) yang presisi — syarat untuk D-scan dan repeatability saat re-inspeksi. Coupling harus konsisten; biasanya pakai water feed atau gel terus-menerus pada scanner. PCS, sudut, frekuensi, encoder resolution, kecepatan scan, dan setup gain semuanya didokumentasikan dalam scan plan sebelum produksi."}]}', 460, NULL),
  (3, 'reading', 'Display D-scan & interpretasi', '{"slides":[{"heading":"Dari A-scan ke D-scan","body":"TOFD menampilkan data sebagai citra grayscale (D-scan / nonparallel B-scan): sumbu horizontal = posisi probe sepanjang weld (dari encoder), sumbu vertikal = time-of-flight (proporsional ke depth), dan tingkat keabuan = amplitudo sinyal. Tampilan ini mengubah ribuan A-scan menjadi satu citra yang mudah dibaca, di mana cacat tampak sebagai pola gelap khas di antara lateral wave (di atas) dan backwall echo (di bawah)."},{"heading":"Pembalikan fase (phase)","body":"Sinyal diffraksi dari upper tip dan lower tip suatu crack memiliki FASE berlawanan (phase inversion) satu sama lain — ciri yang membantu membedakan tip crack asli dari geometri atau noise. Sebagai acuan, lateral wave dan backwall echo mempunyai polaritas tertentu; upper tip biasanya berlawanan fase terhadap lateral wave sedangkan lower tip sefase. Analyst Level II membaca polaritas RF (unrectified) untuk konfirmasi tip sebelum melakukan height sizing."},{"heading":"Pola cacat khas","body":"Embedded crack: dua busur (arc) hiperbolik terpisah (upper & lower tip) di tengah ketebalan. Surface-breaking dari ID (far surface): tampak gangguan/break pada backwall echo disertai satu tip signal. Surface-breaking dari OD (scan surface): tampak gangguan pada lateral wave. Porosity/inklusi: pola titik-titik scattered (hash). Lack of fusion / lack of penetration: sinyal linear mengikuti fusion line atau root. Mengenali pola-pola ini adalah inti interpretasi TOFD Level II."},{"heading":"Software straightening & parabolic cursor","body":"Software TOFD melakukan koreksi geometris: lateral wave straightening dan parabolic (hyperbolic) cursor untuk konversi time-of-flight ke depth nyata, sebab hubungan waktu-kedalaman tidak linear (mengikuti lintasan diagonal Tx-cacat-Rx). Analyst memposisikan kursor pada puncak tip signal; software menghitung depth dan height. Kalibrasi kecepatan longitudinal material dan PCS aktual harus benar agar konversi akurat — kesalahan PCS atau velocity langsung menggeser hasil sizing."}]}', 470, NULL),
  (4, 'reading', 'Sizing & keterbatasan', '{"slides":[{"heading":"Depth & height sizing","body":"Depth tiap tip dihitung dari time-of-flight relatif terhadap lateral wave (atau backwall) dan kecepatan longitudinal. Height (through-wall extent) = depth lower tip dikurangi depth upper tip. Karena berbasis waktu, akurasi height tipikal sekitar +/-1 mm dan depth +/-0.5-1 mm bila setup benar — superior untuk pemantauan tren crack growth. Length sizing dilakukan dari D-scan dengan mengukur extent sinyal sepanjang sumbu encoder (sering dipadu teknik amplitude-drop)."},{"heading":"Dead zone lateral wave","body":"Keterbatasan utama TOFD: zona mati (dead zone) tepat di bawah permukaan scan yang tertutup lebar pulse lateral wave. Cacat near-surface (mis. dalam beberapa mm pertama, besarnya tergantung frekuensi, panjang pulse, & PCS) dapat tersembunyi di balik lateral wave. Mitigasi: padukan dengan pulse-echo atau PAUT untuk near-surface coverage, gunakan frekuensi lebih tinggi / pulse lebih pendek untuk mempersempit dead zone, atau scan TOFD dari kedua sisi weld."},{"heading":"Dead zone backwall & limitasi lain","body":"Ada juga dead zone tipis dekat backwall (sinyal cacat dapat tertutup backwall echo). Limitasi lain: point-like reflector (mis. porosity tunggal) sulit di-size dibanding planar crack, hasil sensitif terhadap akurasi setup geometry (PCS/velocity), dan interpretasi menuntut skill tinggi. Cacat yang berorientasi sehingga diffraksinya lemah atau mid-wall lack of fusion tertentu bisa under-respond. Karena itu acceptance kritis sering memakai TOFD + pulse-echo / PAUT secara komplementer."},{"heading":"Komplemen dengan PAUT","body":"Praktik modern menggabungkan TOFD dan PAUT dalam satu scan ter-encode. PAUT unggul untuk detection, lokasi lateral, dan near-surface coverage; TOFD unggul untuk height sizing yang akurat dan deteksi cacat berorientasi acak. Kombinasi keduanya memberi probability of detection (POD) tinggi sekaligus sizing presisi — dasar Automated Ultrasonic Testing (AUT) pada pipeline girth weld dan inspeksi vessel kritis."}]}', 480, NULL),
  (5, 'reading', 'Code & kualifikasi TOFD', '{"slides":[{"heading":"ASME V — TOFD","body":"ASME BPVC Section V, Article 4 mengatur TOFD melalui Mandatory Appendix III (Time of Flight Diffraction Technique), didukung Nonmandatory Appendix terkait untuk computerized imaging. TOFD harus memakai written procedure yang ter-demonstrasi (performance demonstration) pada blok dengan reflector terkalibrasi. Essential variables — antara lain PCS, sudut, frekuensi, kecepatan scan, dan encoder resolution — bila diubah di luar rentang yang di-qualify, mengharuskan re-qualification prosedur."},{"heading":"ASME VIII & alternatif ke RT","body":"Untuk welds bejana tekan, ASME Section VIII Div. 1 (lewat appendix/Code Case tertentu) dan Div. 2 mengizinkan UT/TOFD sebagai alternatif terhadap radiography pada kondisi tertentu, dengan acceptance berbasis flaw sizing (fracture-mechanics) bukan sekadar amplitudo. Ini menggeser kriteria dari ''reject by indication'' menjadi ''evaluate by size vs allowable flaw'' — peran kunci Level II yang men-sign report."},{"heading":"Pipeline & API","body":"Pada pipeline girth weld, AUT (kombinasi TOFD + PAUT zonal) banyak dipakai dengan acceptance berbasis Engineering Critical Assessment (ECA) sesuai API 1104 Annex A / DNV-ST-F101, di mana flaw diterima/ditolak berdasar height & length terhadap allowable flaw size hasil ECA, bukan kriteria workmanship. Sizing TOFD yang akurat menjadi sangat menentukan keputusan accept/reject."},{"heading":"Tanggung jawab Level II","body":"Level II ber-endorsement TOFD bertanggung jawab atas: verifikasi setup terhadap qualified procedure, kalibrasi kecepatan & PCS, interpretasi D-scan (membedakan cacat dari geometri/noise), sizing depth-height-length, dan sign-off report. Banyak employer menuntut endorsement / training spesifik TOFD di luar UT-L2 umum, plus demonstrasi kompetensi pada blok kalibrasi referensi."}]}', 420, NULL),
  (6, 'quiz', 'Mini-quiz — TOFD', '{"description":"Konfirmasi pemahaman prinsip diffraction, setup PCS & sudut, interpretasi D-scan, sizing, dan code TOFD.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 4
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 4 mini-quiz (8 questions, step 6)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 6 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Apa yang menjadi dasar deteksi cacat pada teknik TOFD?',
   '["Amplitudo pantulan (reflection) spekular dari permukaan cacat","Atenuasi total gelombang melewati material","Sinyal yang ter-diffraksi dari ujung (tip) cacat","Perubahan medan magnet di sekitar cacat"]', 2,
   'TOFD mengandalkan energi diffraksi dari TIP cacat (Huygens point source), bukan amplitudo pantulan permukaan. Inilah yang membuatnya relatif tidak sensitif terhadap orientasi cacat dan akurat untuk sizing.', 'Prinsip TOFD', 'easy'),
  ('Mengapa TOFD memakai gelombang longitudinal (compression), bukan shear, sebagai sinyal utama?',
   '["Karena shear wave tidak bisa di-diffraksikan oleh tip cacat","Karena longitudinal lebih cepat (~5900 m/s di baja) sehingga tiba lebih dulu dan terpisah jelas dari mode shear","Karena longitudinal selalu beramplitudo lebih besar","Karena longitudinal tidak mengalami mode conversion sama sekali"]', 1,
   'Gelombang longitudinal merambat ~5900 m/s di baja (vs ~3230 m/s shear), sehingga sinyalnya tiba lebih dulu dan terpisah jelas dari mode shear yang mengikuti, menghasilkan interpretasi A-scan yang lebih bersih.', 'Prinsip TOFD', 'medium'),
  ('Pada A-scan TOFD, urutan kedatangan sinyal yang benar dari paling awal ke paling akhir adalah:',
   '["Backwall echo, lalu tip cacat, lalu lateral wave","Tip cacat, lalu lateral wave, lalu backwall echo","Lateral wave, lalu backwall echo, lalu sinyal tip cacat","Lateral wave, lalu sinyal tip cacat, lalu backwall echo"]', 3,
   'Lateral wave tiba pertama (merambat tepat di bawah permukaan scan), lalu sinyal diffraksi dari tip cacat di antaranya, dan backwall echo terakhir. Posisi sinyal cacat di antara lateral wave dan backwall menunjukkan kedalamannya.', 'Interpretasi', 'medium'),
  ('Untuk single-zone TOFD, PCS (Probe Centre Spacing) biasanya diatur sehingga perpotongan sumbu kedua beam berada pada kedalaman sekitar:',
   '["Tepat di permukaan scan (0% ketebalan)","1/3 ketebalan dari permukaan","2/3 ketebalan dari permukaan","Tepat di backwall (100% ketebalan)"]', 2,
   'PCS diset agar intersection beam berada di sekitar 2/3 ketebalan (two-thirds depth), titik di mana coverage dan sensitivitas paling merata. PCS terlalu kecil memperbesar dead zone permukaan; terlalu lebar melemahkan sinyal bagian dalam.', 'Setup', 'medium'),
  ('Mengapa TOFD memberikan akurasi height sizing yang lebih baik (tipikal +/-1 mm) dibanding teknik amplitude-based?',
   '["Karena memakai amplitudo yang sudah dikalibrasi terhadap DAC","Karena pengukuran berbasis WAKTU (time-of-flight) yang stabil terhadap variasi coupling dan gain","Karena memakai frekuensi yang jauh lebih rendah","Karena hanya satu probe yang dipakai sehingga error berkurang"]', 1,
   'Height TOFD dihitung dari selisih time-of-flight antara upper tip dan lower tip. Pengukuran waktu jauh lebih stabil terhadap variasi coupling, surface condition, dan gain dibanding amplitudo, sehingga akurasi height tipikal +/-1 mm.', 'Sizing', 'medium'),
  ('Pada D-scan / A-scan RF TOFD, ciri yang membantu mengonfirmasi bahwa dua sinyal berasal dari upper tip dan lower tip satu crack yang sama adalah:',
   '["Keduanya menunjukkan pembalikan fase (phase inversion) satu sama lain","Keduanya memiliki amplitudo yang persis sama","Keduanya muncul tepat berimpit dengan lateral wave","Keduanya tampak putih terang penuh pada grayscale"]', 0,
   'Sinyal diffraksi dari upper tip dan lower tip suatu crack memiliki fase berlawanan (phase inversion) satu sama lain. Analyst membaca polaritas RF (unrectified) untuk memvalidasi tip asli versus noise/geometri sebelum height sizing.', 'Interpretasi', 'hard'),
  ('Keterbatasan utama TOFD yang membuatnya sering dipadu dengan pulse-echo atau PAUT adalah:',
   '["Tidak bisa mengukur length cacat sama sekali","Hanya bekerja pada cacat yang berorientasi sejajar beam","Tidak bisa dipakai pada material baja karbon","Dead zone dekat permukaan scan akibat lebar pulse lateral wave"]', 3,
   'Lateral wave yang lebar menciptakan dead zone near-surface yang dapat menyembunyikan cacat dangkal. Karena itu TOFD dipadukan pulse-echo/PAUT untuk coverage near-surface, atau dipakai frekuensi lebih tinggi/pulse lebih pendek untuk mempersempit dead zone.', 'Keterbatasan', 'medium'),
  ('Untuk inspeksi pipeline girth weld dengan AUT (TOFD+PAUT), keputusan accept/reject cacat umumnya didasarkan pada:',
   '["Allowable flaw size hasil Engineering Critical Assessment (ECA) sesuai API 1104 Annex A","Kriteria workmanship sederhana (ada indikasi = reject)","Warna grayscale indikasi pada D-scan","Jumlah total indikasi tanpa memandang ukuran"]', 0,
   'AUT pipeline mengikuti acceptance berbasis ECA (API 1104 Annex A / DNV-ST-F101): flaw diterima/ditolak berdasar height & length terhadap allowable flaw size, bukan kriteria workmanship. Sizing TOFD yang akurat menjadi penentu keputusan.', 'Code', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 6 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 5 — Complex Defect Analysis (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Karakterisasi Cacat: Klasifikasi & Diskriminasi', '{"slides":[{"heading":"Tujuan karakterisasi Level II","body":"Level I cukup mendeteksi indikasi yang melebihi reference level dan merekamnya. Level II harus melakukan karakterisasi: menentukan apakah indikasi adalah cacat (flaw) atau hanya geometri/false call, lalu mengklasifikasikan jenisnya (crack, lack of fusion, slag, porosity, incomplete penetration) sebelum dievaluasi terhadap acceptance criteria. Karakterisasi yang benar menentukan apakah weld di-accept, di-repair, atau dikenakan engineering evaluation (fitness-for-service)."},{"heading":"Diskriminasi planar vs volumetric","body":"Cacat planar (crack, lack of fusion, incomplete penetration) berorientasi 2D, memantulkan beam secara specular dan sangat sensitif terhadap sudut beam — amplitudo turun drastis bila beam tidak tegak lurus terhadap bidang cacat. Cacat volumetric (porosity, slag, blowhole) menyebarkan beam ke segala arah sehingga amplitudo relatif stabil saat probe digeser atau sudut diubah. Cacat planar jauh lebih kritis karena bersifat crack-like dan menjadi titik inisiasi fatigue/fracture."},{"heading":"Petunjuk diagnostik dari sinyal A-scan","body":"Beberapa indikator membantu klasifikasi: respons amplitudo tinggi dan tajam yang sensitif terhadap sudut menandakan planar (crack/LOF); banyak puncak kecil yang naik-turun saat probe digerakkan menandakan cluster porosity/slag; sinyal yang menggantung pada satu kedalaman konstan sepanjang las menandakan incomplete penetration atau LOF di root. Pengamatan echo dynamics — bagaimana envelope sinyal berubah saat probe digeser maju-mundur dan menyamping — adalah alat utama Level II untuk membedakan jenis cacat, bukan sekadar membaca amplitudo puncak."},{"heading":"Geometri vs cacat asli (false calls)","body":"Root bead, weld cap, counterbore, mismatch (hi-lo), dan back-wall geometry sering menghasilkan indikasi geometris yang dapat disalahartikan sebagai cacat. Level II memverifikasi dengan: mencocokkan lokasi terhadap weld map dan sketsa joint, menggunakan probe sudut berbeda atau leg yang berbeda, dan membandingkan posisi indikasi (sound path & surface distance) dengan fitur geometri yang diketahui. Bila indikasi mengikuti kontur root secara konsisten dan posisinya cocok dengan root bead, kemungkinan besar itu geometri, bukan cacat."}]}', 480, NULL),
  (2, 'reading', 'Length Sizing dengan 6 dB Drop', '{"slides":[{"heading":"Prinsip 6 dB drop","body":"Teknik 6 dB drop (half-amplitude) digunakan untuk mengukur panjang (extent) reflektor yang lebih besar dari lebar beam. Penurunan 6 dB setara dengan amplitudo turun menjadi setengah (50%) dari nilai maksimum, karena 20·log10(0,5) ≈ -6 dB. Logikanya: ketika sumbu utama beam berada tepat di ujung reflektor, energi yang dikembalikan turun separuh sehingga -6 dB beam edge menandai batas reflektor. Metode ini paling akurat untuk reflektor besar yang memantul secara specular."},{"heading":"Prosedur langkah demi langkah","body":"1) Maksimalkan sinyal dari reflektor dan catat amplitudo puncak (mis. set ke 80% FSH). 2) Geser probe sepanjang cacat sampai amplitudo turun tepat 6 dB (separuh dari puncak), lalu tandai posisi probe relatif terhadap beam index point (BIP). 3) Geser ke arah berlawanan sampai turun 6 dB lagi dan tandai posisi kedua. 4) Jarak antara dua titik penanda = panjang cacat. Jaga couplant dan tekanan konsisten, gunakan BIP yang sama, dan catat panjang relatif terhadap datum las (mis. dari weld station 0)."},{"heading":"Kapan 6 dB drop valid (dan batasannya)","body":"6 dB drop akurat bila reflektor LEBIH BESAR dari beam width dan permukaannya rata/specular (mis. lack of fusion memanjang atau crack besar). Untuk reflektor yang LEBIH KECIL dari beam width, 6 dB drop justru overestimate karena yang terukur sebenarnya adalah lebar beam, bukan panjang cacat — dalam kasus ini gunakan teknik 20 dB drop atau maximum amplitude. Untuk porosity/slag yang tersebar, 6 dB drop tidak sesuai; gunakan maximum amplitude technique untuk mendefinisikan extent cluster."},{"heading":"Sumber error & koreksi","body":"Error length sizing berasal dari: beam spread (semakin dalam, beam makin lebar sehingga cenderung overestimate), surface roughness, variasi couplant, dan kesalahan pembacaan posisi probe. Praktik koreksi yang baik: pakai probe frekuensi lebih tinggi atau diameter lebih kecil bila memungkinkan untuk mempersempit beam, lakukan beam width characterization pada calibration block ber-SDH, dan untuk reflektor kecil terapkan koreksi panjang efektif (effective length ≈ measured length dikurangi beam width pada kedalaman tersebut). Selalu dokumentasikan metode sizing yang dipakai di dalam laporan."}]}', 500, NULL),
  (3, 'reading', 'Multi-Defect & Cacat Kompleks', '{"slides":[{"heading":"Indikasi berdekatan & aturan kombinasi","body":"Bila beberapa indikasi berdekatan, code sering memperlakukannya sebagai satu cacat tunggal yang lebih besar. Ambang penggabungan bersifat code-specific: misalnya banyak code menggabungkan indikasi sejajar/segaris bila jarak antar indikasi lebih kecil dari panjang indikasi terbesar (atau nilai tetap yang dinyatakan code). Level II wajib menerapkan aturan kombinasi dari code yang berlaku agar tidak keliru meng-accept dua indikasi kecil yang, bila digabung, sebenarnya melebihi batas penerimaan."},{"heading":"Cacat bercabang & multi-faceted","body":"Crack nyata sering bercabang (branching) dan multi-faceted, menghasilkan banyak tip diffraction dan respons kompleks pada beberapa sudut. Pendekatan Level II: scan dengan multiple angle (mis. 45/60/70°), petakan tiap facet, lalu rekonstruksi profil cacat. Echo dynamics yang panjang dan tidak teratur dengan banyak puncak saat probe digeser adalah ciri crack bercabang, berbeda dari satu reflektor planar bersih yang memberikan satu envelope tajam."},{"heading":"Strategi scan multi-angle & skip","body":"Untuk karakterisasi lengkap, gunakan teknik 1st leg (direct) dan 2nd leg (skip/full-V) agar menjangkau cacat di berbagai kedalaman dan orientasi. Cacat yang ter-miss pada satu sudut bisa terdeteksi pada sudut lain karena perbedaan orientasi bidang cacat terhadap beam. Catat sound path, surface distance, dan depth untuk tiap respons, lalu plot pada weld cross-section untuk membangun gambaran 3D dari kumpulan cacat (defect map)."}]}', 460, NULL),
  (4, 'reading', 'Plotting, Defect Map & Pelaporan', '{"slides":[{"heading":"Trigonometri plotting","body":"Sudut beam (θ) pada probe sudut diukur dari garis normal (tegak lurus permukaan). Maka, dari sound path (S): surface distance dari beam index point = S·sin θ, dan depth = S·cos θ untuk 1st leg. Pada 2nd leg, depth = (2·t) − S·cos θ dengan t = ketebalan benda kerja. Level II harus mampu memverifikasi posisi cacat secara manual agar plotting di equipment (atau di kertas) konsisten dengan geometri sambungan dan tidak tertukar antara zona root, fill, dan cap."},{"heading":"Membangun defect map","body":"Defect map menggabungkan semua data: lokasi keliling/linear (circumferential/linear station), panjang (dari 6 dB drop), kedalaman (depth dari trigonometri), tinggi/through-wall (height sizing bila diperlukan untuk FFS), klasifikasi jenis cacat, dan amplitudo relatif terhadap reference (mis. +4 dB di atas DAC). Peta ini menjadi dasar keputusan accept/reject sekaligus input untuk repair plan atau engineering critical assessment."},{"heading":"Isi laporan yang wajib","body":"Laporan Level II yang valid mencantumkan: identitas part/weld dan datum, prosedur dan code acuan, equipment dan probe (frekuensi, sudut, S/N), calibration block dan reference level (mis. SDH 1,5 mm, DAC), metode sizing yang dipakai (6 dB drop / maximum amplitude), data tiap indikasi (lokasi, panjang, kedalaman, amplitudo, klasifikasi), keputusan accept/reject terhadap criteria, serta tanda tangan inspector bersertifikat. Tanpa metode sizing yang dinyatakan dan reference level, hasil tidak dapat direproduksi maupun diaudit."},{"heading":"Keputusan accept/reject","body":"Bandingkan tiap karakteristik cacat dengan acceptance criteria code yang relevan (mis. ASME V Art. 4 + ASME VIII Div. 1 untuk pressure equipment, atau AWS D1.1 untuk struktur baja). Untuk cacat planar yang melebihi batas, opsinya: repair lalu re-inspect, atau fitness-for-service (FFS) per API 579-1/ASME FFS-1 bila repair tidak praktis. Ingat: indikasi yang teridentifikasi sebagai crack umumnya rejectable tanpa memandang panjang pada banyak code kritis (mis. AWS D1.1 dan ASME VIII)."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Complex Defect Analysis', '{"description":"Konfirmasi pemahaman karakterisasi multi-defect, length sizing 6 dB drop, plotting trigonometri, aturan kombinasi code, dan keputusan accept/reject.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 5
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 5 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada teknik 6 dB drop, panjang cacat ditentukan dari jarak antar posisi probe ketika amplitudo turun menjadi berapa dari nilai maksimum?',
   '["50% (separuh) dari amplitudo maksimum","25% (seperempat) dari amplitudo maksimum","70% dari amplitudo maksimum","10% (sepersepuluh) dari amplitudo maksimum"]', 0,
   'Penurunan 6 dB setara dengan 20·log10(0,5) ≈ -6 dB, yaitu amplitudo turun menjadi setengah (50%) dari puncak. Probe digeser ke kedua arah sampai sinyal turun 6 dB; jarak antar penanda = panjang cacat. Catatan: 10% berhubungan dengan 20 dB drop, bukan 6 dB.', 'Defect Sizing', 'easy'),
  ('Teknik 6 dB drop memberikan hasil paling akurat untuk kondisi reflektor seperti apa?',
   '["Reflektor lebih kecil dari beam width","Cluster porosity yang tersebar acak","Reflektor besar dan specular yang lebih besar dari beam width","Reflektor titik (point reflector) seperti SDH kecil"]', 2,
   '6 dB drop akurat bila reflektor lebih besar dari beam width dan memantul secara specular (mis. LOF memanjang atau crack besar). Untuk reflektor yang lebih kecil dari beam width, 6 dB drop overestimate karena yang terukur adalah lebar beam; gunakan 20 dB drop atau maximum amplitude.', 'Defect Sizing', 'medium'),
  ('Ciri A-scan/echo dynamics yang paling mengindikasikan cacat PLANAR seperti crack atau lack of fusion adalah:',
   '["Banyak puncak kecil yang stabil dari segala sudut probe","Sinyal lemah merata tanpa puncak dominan","Amplitudo tinggi dan tajam yang sangat sensitif terhadap sudut beam","Amplitudo konstan tanpa perubahan saat probe digeser"]', 2,
   'Cacat planar memantul secara specular sehingga menghasilkan amplitudo tinggi dan tajam yang sangat bergantung pada sudut — amplitudo turun drastis bila beam tidak tegak lurus terhadap bidang cacat. Respons banyak puncak stabil dari segala arah lebih mencirikan porosity/slag (volumetric).', 'Defect Characterization', 'medium'),
  ('Untuk mengukur extent dari sebuah CLUSTER porosity yang tersebar, teknik sizing yang paling tepat adalah:',
   '["6 dB drop technique","20 dB drop technique","Mengukur satu pori terbesar saja","Maximum amplitude technique"]', 3,
   'Porosity/slag yang tersebar tidak memantul secara specular sehingga 6 dB drop maupun 20 dB drop tidak sesuai. Maximum amplitude technique digunakan untuk mendefinisikan extent dari kumpulan reflektor kecil yang banyak (cluster).', 'Defect Sizing', 'medium'),
  ('Sebuah indikasi ditemukan pada sound path 30 mm dengan probe sudut 60°. Berapa kira-kira depth (kedalaman) cacat pada 1st leg?',
   '["26 mm","15 mm","30 mm","52 mm"]', 1,
   'Sudut diukur dari garis normal, maka depth pada 1st leg = S·cos θ = 30·cos 60° = 30·0,5 = 15 mm. Nilai 26 mm adalah surface distance (S·sin 60° ≈ 25,98 mm), bukan kedalaman.', 'Plotting', 'hard'),
  ('Mengapa Level II menggunakan scan multi-angle (mis. 45/60/70°) dan teknik skip (2nd leg) saat menganalisis cacat kompleks?',
   '["Untuk mempercepat scanning meskipun kurang akurat","Karena code melarang penggunaan satu sudut saja","Karena cacat planar bisa ter-miss pada satu sudut akibat orientasi bidangnya, sedangkan sudut/leg lain menjangkau orientasi dan kedalaman berbeda","Untuk menghindari kebutuhan kalibrasi DAC"]', 2,
   'Sensitivitas cacat planar sangat bergantung pada sudut beam terhadap bidang cacat. Cacat bisa tak terdeteksi pada satu sudut tetapi muncul pada sudut/leg lain. Multi-angle dan skip menjangkau berbagai orientasi dan kedalaman untuk karakterisasi lengkap dan defect map yang benar.', 'Inspection Technique', 'medium'),
  ('Dua indikasi kecil yang berdekatan ditemukan dalam satu las. Tindakan Level II yang benar terkait aturan code adalah:',
   '["Menerapkan aturan kombinasi/penjumlahan code; bila jarak antar indikasi di bawah ambang code, perlakukan sebagai satu cacat gabungan","Selalu menilai keduanya terpisah karena masing-masing di bawah batas","Mengabaikan keduanya karena ukurannya kecil","Hanya melaporkan indikasi dengan amplitudo lebih tinggi"]', 0,
   'Banyak code (mis. ASME, AWS) mensyaratkan indikasi berdekatan yang jaraknya di bawah ambang tertentu digabung dan dievaluasi sebagai satu cacat. Dua indikasi kecil yang digabung dapat melebihi batas penerimaan, sehingga tidak boleh otomatis dinilai terpisah.', 'Code Interpretation', 'hard'),
  ('Informasi mana yang WAJIB dinyatakan dalam laporan UT Level II agar hasil sizing dapat diaudit?',
   '["Hanya keputusan accept/reject akhir","Nama pelanggan dan tanggal saja","Merek couplant yang dipakai","Metode sizing yang digunakan (mis. 6 dB drop atau maximum amplitude) beserta reference level"]', 3,
   'Tanpa metode sizing yang dinyatakan dan reference level (mis. DAC/SDH), angka panjang/tinggi cacat tidak dapat direproduksi atau diaudit. Laporan valid mencantumkan prosedur, equipment, reference, metode sizing, data tiap indikasi, keputusan vs criteria, dan tanda tangan inspector.', 'Reporting', 'easy')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 6 — Advanced Calibration & TCG (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Mengapa Amplitude Berubah dengan Jarak', '{"slides":[{"heading":"Masalah dasar: atenuasi & beam spread","body":"Reflektor identik pada kedalaman berbeda menghasilkan amplitude echo yang berbeda. Penyebabnya dua: atenuasi material (absorption + scattering, naik dengan jarak dan dengan frekuensi) dan beam divergence di far field. Laju penurunannya bergantung pada bentuk reflektor: pemantul planar besar seperti back-wall turun ~1/jarak, reflektor disc kecil (FBH) turun ~1/jarak^2, sedangkan Side-Drilled Hole (silindris) turun ~1/jarak^1.5. Tanpa koreksi, cacat dalam akan tampak ''lebih kecil'' dari cacat dangkal yang ukuran fisiknya sama. Level II wajib mengoreksi efek ini sebelum evaluasi berbasis amplitude."},{"heading":"Near field vs far field","body":"Near field (zona Fresnel) memiliki panjang N = D^2/(4*lambda) = D^2*f/(4*c), dengan D = diameter efektif transducer. Di dalam near field medan intensitas fluktuatif (maxima/minima) sehingga sizing berbasis amplitude tidak reliable. Di far field (zona Fraunhofer) intensitas turun secara monoton dan dapat diprediksi. Kalibrasi DAC/TCG/DGS dirancang untuk mengkompensasi penurunan teratur di far field; reflektor di dalam near field harus diperlakukan hati-hati dan idealnya titik kalibrasi diambil di far field."},{"heading":"Reference reflector standar","body":"Koreksi amplitude dibangun dari reflektor referensi yang reproducible: Side-Drilled Hole (SDH, paling umum untuk weld karena respons hampir omni-directional terhadap angle beam), Flat-Bottom Hole (FBH, untuk immersion/straight beam, mensimulasikan reflektor disc planar), dan notch (untuk corner/ID-OD defect). ASME V Art. 4 umumnya memakai basic calibration block dengan SDH untuk menyusun DAC. AWS D1.1 memakai blok kalibrasi standar dengan SDH diameter 1.59 mm (1/16 in) untuk menyetel reference level."},{"heading":"Konsep koreksi: tiga pendekatan","body":"Ada tiga filosofi mengoreksi penurunan amplitude. Pertama, koreksi visual pada layar: gambar kurva mengikuti puncak echo referensi (DAC) lalu evaluasi indikasi relatif terhadap kurva. Kedua, koreksi gain elektronik: tambah gain otomatis sesuai waktu/jarak sehingga semua reflektor referensi tampil pada amplitude layar yang sama tinggi (TCG), membuat kurva DAC menjadi garis datar. Ketiga, DGS/AVG, memakai kurva teoritis ternormalisasi berbasis diameter probe untuk menyetel sensitivitas dari satu reflektor — dibahas di langkah berikut."}]}', 460, NULL),
  (2, 'reading', 'Distance Amplitude Correction (DAC)', '{"slides":[{"heading":"Apa itu kurva DAC","body":"DAC (Distance Amplitude Correction) adalah kurva yang menghubungkan amplitude puncak dari reflektor referensi berukuran SAMA pada berbagai jarak metal-path. Setelah kurva dibuat, gain instrumen tidak diubah selama scanning; evaluasi dilakukan dengan membandingkan amplitude indikasi terhadap kurva pada metal-path yang sama. Indikasi yang puncaknya tepat menyentuh kurva = 100% DAC (= reference level), yang bukan otomatis kriteria reject."},{"heading":"Cara membangun kurva DAC","body":"Pakai blok dengan SDH identik pada beberapa kedalaman (mis. 1/4T, 1/2T, 3/4T untuk weld, atau serangkaian SDH bertingkat). Maksimalkan echo dari SDH terdangkal, set ke ~80% FSH (full screen height) dengan gain referensi, lalu tandai puncaknya. Tanpa mengubah gain, maksimalkan echo dari SDH berikutnya yang lebih dalam dan tandai puncaknya — biasanya makin rendah. Hubungkan minimal 3 titik menjadi kurva halus. Itulah primary/100% DAC."},{"heading":"Reference, recording & evaluation levels","body":"Banyak code menambahkan kurva sekunder relatif terhadap DAC primer. ASME V Art. 4 (amplitude technique lama): indikasi yang melebihi 20% DAC harus dievaluasi; penolakan mengikuti kriteria di referencing code (mis. ASME VIII). AWS D1.1 memakai reference level lalu menghitung Indication Rating d = a - b - c (dalam dB, dengan a = indication level, b = reference level, c = attenuation factor). Sering dipakai kurva -6 dB dan -14 dB sebagai recording/evaluation lines. Yang penting: 100% DAC = reference, bukan otomatis reject."},{"heading":"Transfer correction (transfer loss)","body":"Calibration block dan komponen uji bisa berbeda kekasaran permukaan, kelengkungan, dan atenuasi. Transfer correction mengukur selisih ini (mis. metode dua-probe pitch-catch atau perbandingan back-wall echo di blok vs di part) dan menambahkan dB ke evaluasi agar adil. Jika transfer loss > 2 dB, koreksi umumnya harus diterapkan; banyak code mensyaratkan dokumentasi nilai transfer correction dalam laporan. Mengabaikannya membuat cacat real tampak under-amplitude dan berisiko lolos."}]}', 500, NULL),
  (3, 'reading', 'Time-Corrected Gain (TCG) & DGS/AVG', '{"slides":[{"heading":"TCG: meratakan layar, bukan menggambar kurva","body":"TCG (Time-Corrected Gain, juga disebut DAC elektronik atau swept gain) menerapkan gain yang bertambah terhadap waktu (time = jarak). Hasilnya: reflektor referensi identik pada SEMUA jarak tampil pada amplitude layar yang SAMA (mis. 80% FSH) — kurva DAC menjadi garis datar horizontal. Keunggulan: sizing berbasis amplitude lebih mudah dibaca, threshold/gating konsisten lintas jarak, dan ideal untuk recording digital/automated serta PAUT (di mana tiap focal law butuh kompensasi berbeda)."},{"heading":"Membangun TCG","body":"Prosedurnya mirip DAC: maksimalkan echo dari setiap SDH referensi pada kedalaman berurutan. Pada tiap titik, instrumen mencatat gain tambahan yang dibutuhkan agar echo mencapai amplitude target. Instrumen lalu menginterpolasi dan menerapkan ramp gain di antara titik. Batas penting: TCG dibatasi oleh dynamic range instrumen — penambahan gain juga menaikkan noise floor, jadi koreksi untuk jarak jauh bisa membuat grain/material noise ikut naik mendekati recording level."},{"heading":"TCG vs DAC — kapan pilih mana","body":"DAC: gain tetap, mata membandingkan indikasi ke kurva — bagus untuk UT manual konvensional, murah, dan record analog. TCG: gain dinamis, layar datar — praktis wajib untuk PAUT/automated, lebih mudah bagi operator, tetapi menaikkan noise pada jarak jauh dan butuh instrumen yang mendukung. Keduanya secara prinsip ekuivalen dalam mengoreksi penurunan amplitude; perbedaannya pada cara presentasi dan implikasi noise/dynamic range."},{"heading":"DGS/AVG — alternatif berbasis diagram","body":"DGS (Distance-Gain-Size) atau AVG (Abstand-Verstaerkung-Groesse) memakai kurva teoritis ternormalisasi yang menghubungkan jarak, gain, dan ekuivalen ukuran reflektor disc (ERS/equivalent flat-bottom hole) untuk probe tertentu. Kalibrasi hanya butuh SATU reflektor referensi (sering back-wall echo atau satu SDH) untuk menyetel kurva, lalu ukuran cacat dibaca sebagai equivalent reflector size. DGS sangat efisien tetapi sensitif terhadap akurasi parameter probe (frekuensi, diameter efektif) dan atenuasi material — error parameter langsung menggeser estimasi ukuran."}]}', 510, NULL),
  (4, 'reading', 'ACG/ECA, Verifikasi & Pitfalls Kalibrasi', '{"slides":[{"heading":"ACG dan TCG untuk PAUT","body":"Pada sectorial (S-)scan, tiap angle/focal law menempuh metal-path dan memiliki sensitivitas berbeda, sehingga butuh ACG (Angle-Corrected Gain): kalibrasi sensitivitas pada beberapa angle terhadap SDH referensi agar respons rata di seluruh rentang sweep. ACG biasa dikombinasikan dengan TCG per angle. Tanpa ACG, indikasi pada angle ekstrem (mis. 70 derajat) akan under-/over-amplified relatif terhadap 45 derajat, menyebabkan sizing dan acceptance keliru."},{"heading":"ECA — dua makna, jangan tertukar","body":"Dalam konteks akuisisi PAUT, ''encoded'' acquisition berarti probe dipasang encoder posisi sehingga tiap A-scan punya koordinat, memungkinkan C-scan dan koreksi per focal law. Dalam konteks acceptance, ECA = Engineering Critical Assessment: penilaian fitness-for-service berbasis fracture mechanics (BS 7910 / API 579) yang menentukan toleransi cacat berdasarkan tegangan dan ketangguhan, bukan sekadar amplitude. Akurasi height/length sizing dari kalibrasi yang benar menjadi input kritis bagi ECA."},{"heading":"Verifikasi & rekualifikasi kalibrasi","body":"Code mensyaratkan calibration check berkala. ASME V Art. 4 tipikal: cek pada awal & akhir tiap pemeriksaan, setiap pergantian operator, setiap 4 jam, dan saat ada perubahan parameter. Jika sensitivitas turun > 20% atau 2 dB, semua area sejak kalibrasi terakhir yang valid harus di-scan ulang. Jika titik DAC/sweep bergeser > 10% sweep distance, recalibrate dan re-record indikasi yang terdampak. Suhu, kondisi kabel, dan keausan wedge adalah penyebab umum drift."},{"heading":"Pitfalls umum yang menggagalkan evaluasi","body":"Lupa transfer correction membuat cacat real tampak under-amplitude dan lolos. Membangun DAC di dalam near field menghasilkan titik tidak monoton sehingga kurva tidak valid. TCG agresif untuk jarak jauh menaikkan grain noise melewati recording level (false calls). Salah parameter probe pada DGS membuat ERS meleset signifikan. Tidak memaksimalkan echo (probe tidak tepat di puncak SDH) membuat semua titik kalibrasi terlalu rendah. Mengabaikan kelengkungan permukaan pada pipa kecil mengubah kontak & beam path sehingga kalibrasi pada blok flat tidak representatif."}]}', 480, NULL),
  (5, 'quiz', 'Mini-quiz — Advanced Calibration & TCG', '{"description":"Konfirmasi pemahaman DAC, TCG, DGS/AVG, transfer correction, ACG/ECA, dan aturan verifikasi kalibrasi.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 6
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 6 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Dua reflektor SDH identik berada pada kedalaman 10 mm dan 60 mm. Tanpa koreksi jarak, mengapa echo dari yang 60 mm lebih rendah?',
   '["Karena SDH yang lebih dalam fisiknya lebih kecil","Karena atenuasi material dan beam divergence menurunkan intensitas dengan bertambahnya metal-path","Karena frekuensi probe naik dengan kedalaman","Karena kecepatan suara berkurang di material yang lebih dalam"]', 1,
   'Reflektornya identik; penurunan amplitude murni dari efek jarak — atenuasi (absorption + scattering) dan beam spread di far field. Inilah yang dikompensasi DAC/TCG/DGS. Frekuensi dan velocity tidak berubah dengan kedalaman.', 'Prinsip Koreksi Amplitude', 'easy'),
  ('Di far field, bagaimana laju penurunan amplitude terhadap jarak untuk Side-Drilled Hole (SDH) dibanding back-wall planar besar dan Flat-Bottom Hole kecil?',
   '["Ketiganya turun dengan laju yang sama, ~1/jarak","Back-wall ~1/jarak, FBH (disc) ~1/jarak^2, dan SDH (silindris) ~1/jarak^1.5","SDH ~1/jarak^2 karena berperilaku seperti reflektor titik","Semua turun ~1/jarak^2 karena beam spread tiga dimensi"]', 1,
   'Bentuk reflektor menentukan laju penurunan di far field: pemantul planar besar (back-wall) ~1/jarak, reflektor disc kecil (FBH) ~1/jarak^2, dan SDH silindris berada di antaranya ~1/jarak^1.5. Karena itu DAC/DGS dibangun spesifik untuk tipe reflektor referensi yang dipakai.', 'Prinsip Koreksi Amplitude', 'hard'),
  ('Apa perbedaan presentasi utama antara kurva DAC dan TCG saat reflektor referensi identik dimaksimalkan pada berbagai jarak?',
   '["DAC menaikkan frekuensi sedangkan TCG menaikkan voltase pulser","DAC mengubah velocity layar; TCG mengubah range","DAC hanya untuk straight beam; TCG hanya untuk angle beam","Pada DAC puncak echo menurun mengikuti kurva (gain tetap); pada TCG semua echo tampil pada amplitude layar sama tinggi (gain dinamis) sehingga kurva menjadi garis datar"]', 3,
   'DAC memakai gain tetap dengan kurva menurun sebagai acuan; TCG menerapkan swept gain sehingga reflektor identik tampil sama tinggi di seluruh jarak (kurva menjadi datar). Secara prinsip ekuivalen, perbedaannya pada presentasi.', 'DAC vs TCG', 'medium'),
  ('Mengapa TCG (atau ACG pada PAUT) hampir selalu lebih disukai daripada DAC visual untuk automated/encoded UT dan PAUT?',
   '["TCG tidak terpengaruh noise sama sekali","TCG menghilangkan kebutuhan reflektor referensi","TCG menormalkan amplitude ke level layar yang sama sehingga gating/threshold dan sizing konsisten lintas jarak dan tiap focal law","TCG bekerja tanpa transfer correction"]', 2,
   'Pada akuisisi digital/PAUT, threshold dan C-scan color coding bergantung pada amplitude yang konsisten; TCG/ACG meratakan respons referensi sehingga evaluasi otomatis valid lintas jarak dan tiap angle/focal law. TCG tetap menaikkan noise di jarak jauh dan tetap butuh reflektor referensi serta transfer correction.', 'DAC vs TCG', 'medium'),
  ('Apa fungsi transfer correction (transfer loss) dalam kalibrasi?',
   '["Mengoreksi perbedaan atenuasi/kekasaran/kelengkungan antara calibration block dan komponen uji aktual","Mentransfer kurva DAC ke instrumen lain","Mengubah satuan dari dB ke persen FSH","Mengompensasi keausan crystal probe seiring waktu"]', 0,
   'Block referensi dan part nyata sering berbeda permukaan dan atenuasi. Transfer correction mengukur selisih (mis. metode dua probe atau perbandingan back-wall) dan menambahkan dB agar evaluasi adil; selisih > 2 dB umumnya wajib dikoreksi dan didokumentasikan.', 'Transfer Correction', 'medium'),
  ('Sebuah laboratorium membangun kurva DAC, tetapi titik-titiknya tidak menurun secara monoton — beberapa titik dekat naik-turun tidak teratur. Penyebab paling mungkin adalah:',
   '["Gain instrumen terlalu rendah","Reflektor referensi terlalu besar","Titik-titik diambil di dalam near field di mana intensitas berfluktuasi (maxima/minima) sehingga amplitude tidak teratur","Frekuensi probe terlalu rendah untuk material"]', 2,
   'Di dalam near field (panjang N = D^2/(4*lambda)) medan berfluktuasi dengan maxima/minima sehingga amplitude tidak monoton dan kurva tidak valid. Titik DAC sebaiknya berada di far field.', 'Near Field / Far Field', 'hard'),
  ('Keuntungan utama metode DGS/AVG dibanding membangun DAC dengan banyak SDH adalah:',
   '["DGS tidak terpengaruh parameter probe sama sekali","DGS hanya butuh satu reflektor referensi (mis. back-wall) untuk menyetel kurva teoritis dan langsung memberi equivalent reflector size","DGS tidak memerlukan koreksi atenuasi material","DGS otomatis menaikkan voltase pulser sesuai jarak"]', 1,
   'DGS/AVG memakai kurva ternormalisasi untuk probe tertentu sehingga cukup satu reflektor referensi untuk kalibrasi, lalu cacat dibaca sebagai ERS. Kelemahannya: sangat sensitif terhadap akurasi parameter probe dan atenuasi material.', 'DGS / AVG', 'medium'),
  ('Saat calibration check periodik (tipikal ASME V Art. 4), sensitivitas ditemukan turun lebih dari 20% (kira-kira 2 dB) dari kalibrasi awal. Tindakan yang benar adalah:',
   '["Lanjutkan scanning karena penurunan kecil dapat diabaikan","Naikkan gain 2 dB dan teruskan tanpa tindakan lain","Catat sebagai temuan dan lapor di akhir shift saja","Recalibrate, lalu scan ulang seluruh area yang diperiksa sejak kalibrasi terakhir yang masih valid"]', 3,
   'Jika sensitivitas turun > 20% / 2 dB, kalibrasi dianggap tidak valid; instrumen harus dikalibrasi ulang dan semua area sejak kalibrasi valid terakhir di-scan ulang agar indikasi yang ter-under-amplified tidak terlewat.', 'Verifikasi & Rekualifikasi', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 7 — Immersion Testing (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Prinsip Immersion Testing', '{"slides":[{"heading":"Apa itu immersion testing","body":"Pada immersion testing, probe dan benda uji direndam dalam tangki air (atau air dialirkan lewat squirter/bubbler column). Air menjadi couplant kontinu sehingga TIDAK ada kontak fisik probe-ke-part. Ini menghilangkan keausan (wear) pada probe dan variasi tekanan kontak yang menjadi sumber error pada contact testing, serta memungkinkan beam masuk pada sudut yang stabil dan terkontrol. Sangat cocok untuk part presisi kecil, billet, plate/tube tipis, dan komponen aerospace/turbine yang menuntut sensitivitas dan repeatability tinggi."},{"heading":"Water path & water delay","body":"Jarak antara probe face dan permukaan part disebut water path. Karena kecepatan suara di air (~1480 m/s) jauh lebih lambat daripada baja (~5900 m/s longitudinal), water path muncul sebagai delay panjang di awal A-scan SEBELUM front surface echo (FSE). Aturan praktis (Krautkramer): atur water path agar interface-echo MULTIPLE (gema-ulang dari water path) tidak jatuh di dalam jendela waktu material. Rule-of-thumb minimum: water path > (tebal part × 1/4) × (Vsteel/Vwater) ditambah margin kecil; ini menjaga gema water-path kedua jatuh SETELAH first back wall echo, bukan tumpang-tindih dengannya."},{"heading":"Mode transmisi: longitudinal vs angle (shear)","body":"Pada normal incidence (0°), hanya gelombang longitudinal yang masuk ke part — ideal untuk deteksi laminasi dan pengukuran tebal. Dengan memiringkan probe terhadap permukaan di ATAS first critical angle antarmuka air-baja (~14.5°), gelombang longitudinal mengalami refleksi total dan hanya gelombang shear ter-mode-convert yang masuk ke part — dipakai untuk inspeksi weld dan flaw berorientasi. Sudut refraksi dihitung dengan hukum Snell: sin(theta_i)/Vwater = sin(theta_r)/Vmaterial. Antara first (~14.5°) dan second critical angle (~27°) untuk air-baja, di dalam part praktis hanya ada gelombang shear."},{"heading":"Focused vs flat (unfocused) transducer","body":"Immersion sering memakai focused transducer (lensa akustik spherical atau cylindrical) untuk memusatkan energi pada zona kedalaman tertentu, meningkatkan resolusi lateral dan sensitivitas terhadap flaw kecil. Focal length efektif berubah saat beam masuk material: bagian focal length yang tersisa setelah water path ''dipendekkan'' oleh perbedaan kecepatan, kira-kira jarak fokus di metal = (focal length di air − water path) × (Vwater/Vmetal). Cylindrically focused probe dipakai untuk tube/pipa agar garis fokus mengikuti kurvatur; flat (unfocused) probe dipakai untuk through-transmission dan coverage area lebar."}]}', 470, NULL),
  (2, 'reading', 'Setup Tank & Kondisi Air', '{"slides":[{"heading":"Komponen sistem immersion","body":"Sistem tangki terdiri dari: tank berisi air; manipulator/bridge dengan gimbal untuk angulasi probe pada dua sumbu; search tube (manipulator vertikal pengatur water path); turntable untuk part silindris; serta sistem filtrasi dan degassing air. Bridge bergerak pada sumbu X-Y di atas tangki sementara search tube mengatur Z (water path) dan sudut gimbal. Untuk part besar atau tidak praktis direndam penuh, digunakan squirter/bubbler column yang membentuk kolom air sebagai jembatan akustik (water-coupled, bukan rendam)."},{"heading":"Kualitas & degassing air","body":"Air harus bebas gelembung udara karena gelembung yang menempel di permukaan probe atau part menyebabkan dropout sinyal dan indikasi palsu (false indication). Air didegass (dibiarkan settle, dipanaskan ringan, atau pakai vacuum degasser) dan difilter dari partikel. Aditif yang umum: wetting agent (surfactant) untuk membasahi permukaan dan melepas gelembung, corrosion/rust inhibitor untuk melindungi part dan tangki, serta algaecide untuk kebersihan. Suhu air harus stabil karena Vwater berubah ~2.4 m/s per °C di sekitar suhu kamar — perubahan suhu menggeser water-path delay dan dapat menggeser kalibrasi."},{"heading":"Mengatur water path & normalisasi","body":"Sebelum scan, probe dinormalkan tegak lurus permukaan dengan MEMAKSIMALKAN amplitudo front surface echo (FSE) — saat FSE maksimum, beam benar-benar normal terhadap permukaan. Untuk part flat ini dilakukan dengan penyetelan gimbal; untuk part curved, normal incidence harus dijaga di sepanjang scan path. Water path lalu di-set ke jarak yang dipilih (sering 25 mm sebagai minimum praktis, atau cukup agar second multiple FSE jatuh setelah first back wall echo part), dan dijaga konsisten oleh search tube atau contour following."},{"heading":"Setup gate & sinyal pada A-scan","body":"A-scan immersion menampilkan berurutan: initial pulse, interval water path, FSE (front surface echo), zona material, back surface echo (BSE), lalu multiple. Gate flaw diset SETELAH FSE agar tidak salah trigger oleh interface. Interface gate dapat dipakai untuk ''menempel'' pada FSE dan men-trigger awal gate flaw (interface triggering / gate synchronization), sehingga depth gating tetap akurat meski water path sedikit bervariasi akibat kurvatur atau runout part. DAC/TCG dikalibrasi DALAM zona material (referensi metal-path), bukan dalam water path."}]}', 470, NULL),
  (3, 'reading', 'Scanner Mechanics & Encoding', '{"slides":[{"heading":"Manipulator & sumbu gerak","body":"Scanner immersion bersifat multi-axis. Bridge memberi gerak X-Y horizontal; search tube memberi gerak Z (vertikal/water path) plus dua sudut gimbal (untuk angle beam dan normalisasi). Untuk part silindris (tube, bar, billet) turntable memutar part (sumbu rotasi) sementara probe bergerak aksial — menghasilkan helical (spiral) scan. Resolusi scan ditentukan oleh index resolution (jarak antar scan line) dan scan speed; index harus cukup rapat sehingga flaw terkecil yang dievaluasi tidak terlewat di antara dua lintasan beam."},{"heading":"Encoder & position synchronization","body":"Encoder (linear atau rotary) mencatat posisi probe dan menyinkronkan data sinyal dengan koordinat part. Tanpa encoding, data tidak dapat dipetakan ke posisi sehingga imaging berbasis posisi mustahil. Encoder resolution (mis. 0.1 mm/count) menentukan akurasi pemetaan. Data ter-encode memungkinkan rekonstruksi C-scan (top-view, peta amplitudo atau time-of-flight di seluruh permukaan), B-scan (penampang sepanjang sumbu scan), dan D-scan. C-scan adalah keluaran khas immersion automated UT."},{"heading":"Scan plan & coverage","body":"Scan plan menentukan: area coverage, index resolution, scan speed, water path, sudut, gate setting, dan overlap antar pass. Overlap minimum (mis. ~10% beam width) menjamin tidak ada gap coverage. Untuk weld atau geometri kompleks, scan plan harus membuktikan beam mencakup seluruh volume yang diperiksa. Scan speed dibatasi oleh PRF (pulse repetition frequency) dan index resolution: jika scan terlalu cepat untuk PRF tertentu, ada area yang tidak ter-interogasi (under-sampling). Aturan umum: minimal beberapa pulse per beam-width sepanjang arah scan."},{"heading":"Gimbal alignment & curved parts","body":"Untuk mempertahankan normal incidence pada part lengkung, gimbal harus terus disesuaikan mengikuti normal permukaan lokal — pada sistem otomatis ini diprogram (contour following) atau dijaga dengan profile-tracking. Misalignment sekecil 1-2° dapat menurunkan amplitudo FSE secara drastis (terutama untuk focused probe) dan menggeser sudut refraksi pada angle beam, sehingga lokasi flaw yang dihitung jadi salah. Karena itu verifikasi normalisasi di beberapa titik sepanjang scan path adalah bagian wajib setup Level II."}]}', 480, NULL),
  (4, 'reading', 'Automated UT, Data Imaging & Kalibrasi', '{"slides":[{"heading":"Automated UT (AUT) workflow","body":"Automated UT menggabungkan scanner ter-encode, akuisisi data digital, dan software analisis. Operator Level II bertanggung jawab atas setup, kalibrasi, dan interpretasi — bukan sekadar menjalankan scan. AUT memberi repeatability tinggi, rekaman permanen yang auditable, dan kemampuan re-evaluasi data tanpa perlu re-scan. Banyak diterapkan pada produksi billet/plate, tube mill (in-line), dan aerospace forging sesuai spesifikasi seperti AMS-STD-2154 dan ASTM E2375."},{"heading":"C-scan, B-scan, dan interpretasi imaging","body":"C-scan menampilkan plan-view: tiap pixel mewakili amplitudo maksimum atau depth (time-of-flight) pada posisi X-Y, sehingga flaw tampak sebagai cluster warna. B-scan menampilkan penampang kedalaman vs posisi — berguna untuk melihat sebaran depth flaw dan laminasi. Interpretasi menuntut korelasi: setiap indikasi pada C-scan WAJIB diverifikasi dengan A-scan pada titik tersebut untuk memastikan itu flaw nyata, bukan artefak (mis. surface roughness, edge effect, atau gelembung)."},{"heading":"Kalibrasi & reference standard","body":"Sensitivitas dikalibrasi pada reference block dengan flat-bottom hole (FBH) — standar Area-Amplitude dan Distance-Amplitude (mis. ASTM E127 untuk aluminium, ASTM E428 untuk baja). FBH mensimulasikan reflektor dengan ukuran terkalibrasi (mis. #3 FBH = 3/64 inci diameter). DAC/TCG dibangun dari serangkaian FBH pada kedalaman berbeda untuk mengoreksi atenuasi dan beam spread, sehingga reflektor berukuran sama memberi amplitudo sama tanpa peduli kedalaman. SDH (side-drilled hole) dan notch lebih lazim dipakai untuk teknik angle-beam (terutama pada inspeksi weld/contact)."},{"heading":"Acceptance & tanggung jawab Level II","body":"Acceptance criteria immersion umumnya berbasis amplitudo relatif terhadap FBH reference (mis. reject bila indikasi >= amplitudo #3 FBH, atau bila loss-of-back-reflection melebihi batas yang menandakan laminasi/atenuasi tinggi). Spesifikasi aerospace seperti AMS-STD-2154 (kelas A/AA/B/C) menetapkan FBH size dan batas noise/grass. Level II menyusun/meninjau scan plan, memvalidasi kalibrasi sebelum dan sesudah scan (verifikasi drift dalam batas, mis. <= 2 dB), menginterpretasi imaging, mengevaluasi indikasi terhadap kriteria, dan menandatangani report. Bila drift kalibrasi melebihi batas, data sejak verifikasi terakhir yang valid harus di-scan ulang."}]}', 480, NULL),
  (5, 'quiz', 'Mini-quiz — Immersion Testing', '{"description":"Konfirmasi pemahaman setup tank, water path, mode transmisi, scanner mechanics, encoding, automated UT, dan kalibrasi immersion (FBH/DAC).","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 7
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 7 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada immersion testing, apa fungsi utama ''water path'' (jarak probe ke permukaan part)?',
   '["Mempercepat gelombang suara agar mencapai back wall lebih cepat","Menjadi couplant kontinu sekaligus delay yang memisahkan front surface echo dari gema-ulang water path sehingga gating tetap akurat","Menggantikan kebutuhan kalibrasi DAC pada zona material","Mendinginkan transducer agar tidak overheat saat scan lama"]', 1,
   'Air pada water path adalah couplant kontinu tanpa kontak fisik. Water path harus cukup panjang agar gema-ulang (multiple) dari interface tidak tumpang tindih dengan echo material, sehingga gate dan pengukuran kedalaman tetap akurat. Air justru LEBIH LAMBAT (~1480 m/s) daripada baja (~5900 m/s), jadi tidak mempercepat sinyal.', 'Immersion Setup', 'easy'),
  ('Untuk memasukkan HANYA gelombang shear ke dalam part baja pada immersion testing, probe harus dimiringkan sehingga sudut datang berada di atas...',
   '["Sudut 0° (normal incidence)","Sudut 45° tepat, sebagai syarat mutlak semua angle beam","First critical angle antarmuka air-baja (~14.5°), sehingga komponen longitudinal ter-refleksi total dan hanya shear yang masuk","Second critical angle antarmuka air-baja (~27°)"]', 2,
   'Di atas first critical angle (~14.5° untuk antarmuka air-baja) gelombang longitudinal mengalami refleksi total internal sehingga hanya gelombang shear yang ter-refraksi masuk ke material. Di atas SECOND critical angle (~27°) bahkan shear pun tidak lagi menembus (muncul surface wave). Pada 0° hanya longitudinal yang masuk. Sudut dihitung dengan hukum Snell.', 'Wave Physics', 'medium'),
  ('Mengapa degassing air sangat penting dalam immersion tank?',
   '["Untuk menaikkan kecepatan suara air agar mendekati kecepatan baja","Agar suhu air tidak pernah berubah sama sekali","Untuk menghilangkan kebutuhan wetting agent dan corrosion inhibitor","Gelembung udara pada permukaan probe atau part menyebabkan dropout sinyal dan indikasi palsu"]', 3,
   'Gelembung udara menghamburkan/menghalangi gelombang ultrasonik, menyebabkan kehilangan sinyal (dropout) dan indikasi palsu. Degassing (settling, pemanasan ringan, atau vacuum degasser) menghilangkan gas terlarut. Degassing tidak mengubah kecepatan suara air secara berarti dan tidak menggantikan aditif seperti wetting agent.', 'Immersion Setup', 'easy'),
  ('Saat menormalkan probe agar benar-benar tegak lurus permukaan part flat, operator harus...',
   '["Memaksimalkan amplitudo front surface echo (FSE) dengan menyetel gimbal","Meminimalkan amplitudo back surface echo","Memanjangkan water path hingga FSE hilang dari layar","Mengatur sudut gimbal tepat pada 14.5°"]', 0,
   'Saat beam benar-benar normal terhadap permukaan, energi yang dipantulkan kembali ke probe maksimum, sehingga FSE mencapai amplitudo tertinggi. Operator menyetel gimbal sampai FSE maksimum untuk memastikan normal incidence. 14.5° justru sudut untuk angle-beam (shear), bukan normalisasi.', 'Immersion Setup', 'medium'),
  ('Apa peran encoder pada scanner immersion automated UT?',
   '["Mengubah frekuensi probe secara otomatis selama scan","Mencatat posisi probe dan menyinkronkan data sinyal dengan koordinat sehingga dapat direkonstruksi menjadi C-scan/B-scan","Menghilangkan kebutuhan kalibrasi DAC","Memutar part agar selalu menghadap probe"]', 1,
   'Encoder (linear/rotary) memetakan setiap titik data ke posisi part. Tanpa data ter-encode, imaging berbasis posisi seperti C-scan dan B-scan tidak dapat dibangun dan re-evaluasi data tidak mungkin. Resolusi encoder menentukan akurasi pemetaan. Memutar part adalah tugas turntable, bukan encoder.', 'Scanner Mechanics', 'easy'),
  ('Sebuah C-scan menunjukkan cluster amplitudo tinggi di satu area. Langkah Level II yang benar SEBELUM menyatakannya sebagai flaw adalah...',
   '["Langsung reject part berdasarkan warna C-scan saja","Menaikkan gain 6 dB lalu re-scan seluruh part","Memverifikasi dengan A-scan pada titik tersebut untuk memastikan bukan artefak (edge effect, gelembung, surface roughness)","Mengganti probe focused dengan flat probe"]', 2,
   'Indikasi pada C-scan harus dikorelasikan dengan A-scan di titik tersebut untuk membedakan flaw nyata dari artefak seperti edge effect, gelembung, atau kekasaran permukaan. Interpretasi imaging tanpa verifikasi A-scan dapat menyebabkan reject palsu.', 'Data Imaging', 'medium'),
  ('Pada kalibrasi sensitivitas immersion sesuai standar seperti ASTM E127, reflektor reference yang dipakai untuk membangun kurva Distance-Amplitude (DAC) adalah...',
   '["Lubang ulir berdiameter besar di tengah blok","Notch persegi di tepi blok","Side-drilled hole (SDH) tunggal di permukaan","Serangkaian flat-bottom hole (FBH) pada berbagai kedalaman, mis. #3 FBH (3/64 inci)"]', 3,
   'DAC/TCG immersion dibangun dari serangkaian FBH pada kedalaman berbeda. FBH mensimulasikan reflektor planar dengan ukuran terkalibrasi (mis. #3 FBH = 3/64 inci). Standar Area-Amplitude/Distance-Amplitude seperti ASTM E127 (aluminium) dan E428 (baja) menstandarkan blok ini. SDH/notch lebih lazim untuk teknik angle-beam.', 'Calibration', 'hard'),
  ('Mengapa suhu air harus dijaga stabil selama scan immersion?',
   '["Karena suhu mengubah frekuensi resonansi piezo crystal","Karena Vwater berubah ~2.4 m/s per °C, sehingga perubahan suhu menggeser water-path delay dan dapat menggeser kalibrasi","Karena air panas melarutkan reference block","Karena suhu tinggi menonaktifkan encoder"]', 1,
   'Kecepatan suara di air berubah sekitar 2.4 m/s per °C di sekitar suhu kamar. Perubahan suhu menggeser delay water path dan posisi gate, yang dapat mempengaruhi pengukuran kedalaman dan validitas kalibrasi. Karena itu suhu air dijaga stabil dan kalibrasi diverifikasi sebelum/sesudah scan.', 'Immersion Setup', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 8 — Inspection Procedures Development (6 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Mengapa Written Procedure Wajib', '{"slides":[{"heading":"Definisi written procedure","body":"Written procedure adalah dokumen tertulis yang mendefinisikan SEMUA variabel inspeksi UT secara presisi: equipment, transducer, couplant, calibration block, scanning technique, scan plan, dan acceptance criteria. Tanpa written procedure yang qualified, hasil UT tidak dapat dipertanggungjawabkan secara code. ASME V Article 4 mensyaratkan UT examination dilakukan sesuai written procedure yang memenuhi requirement T-421 (termasuk demonstrasi bila ada essential variable yang mensyaratkannya)."},{"heading":"Procedure vs technique sheet","body":"Procedure adalah dokumen umbrella yang menetapkan range parameter yang diizinkan (misalnya frekuensi 2-5 MHz, sudut refraksi 45-70 derajat). Technique sheet (atau scan plan) adalah aplikasi spesifik procedure untuk satu komponen tertentu — memilih nilai aktual dalam range procedure. Satu procedure bisa menurunkan banyak technique sheet, dan technique sheet TIDAK boleh keluar dari batas yang ditetapkan procedure induknya."},{"heading":"Tanggung jawab Level II","body":"Level II umumnya authorized untuk MENYUSUN dan me-review procedure, namun penandatanganan/approval procedure adalah tanggung jawab Level III sesuai written practice employer (per SNT-TC-1A) atau ISO 9712. Level II bertanggung jawab memastikan setiap inspeksi yang dilakukan tetap di dalam essential variable range yang ditetapkan procedure. Menyimpang dari range = procedure invalid untuk kondisi itu sampai di-requalify."},{"heading":"Konsekuensi prosedur tidak qualified","body":"Inspeksi yang dilakukan di luar procedure yang qualified dapat menyebabkan report ditolak oleh AI (Authorized Inspector), rework mahal, dan dalam kasus pressure equipment dapat menjadi temuan audit yang serius. Code seperti ASME VIII Div.1 mensyaratkan NDE dilakukan per Section V dengan acceptance per Section VIII, dan dokumentasinya disahkan dalam Manufacturer''s Data Report."}]}', 460, NULL),
  (2, 'reading', 'Essential vs Nonessential Variables', '{"slides":[{"heading":"Konsep essential variable","body":"ASME V Article 4 (Table T-421) membagi variabel UT menjadi essential dan nonessential. Essential variable adalah parameter yang, jika diubah di luar range yang di-demonstrate/ditetapkan procedure, MEWAJIBKAN requalification procedure. Nonessential variable boleh diubah dalam batas yang ditetapkan tanpa requalification, tetapi setiap perubahan tetap harus dicatat dalam revisi/record."},{"heading":"Contoh essential variables","body":"Yang termasuk essential menurut T-421 antara lain: weld/material configuration termasuk thickness range yang dicakup, transducer type/frequency/size element, sudut wedge atau refracted angle, search unit cable type/length jika berubah signifikan, surface preparation, scanning technique (manual vs automated), metode kalibrasi sensitivity, serta calibration/reference block (material, geometri, surface, reflektor). Perubahan frekuensi nominal atau penambahan range thickness di luar yang qualified adalah perubahan essential."},{"heading":"Contoh nonessential variables","body":"Yang biasanya nonessential: identitas operator, merek dagang couplant tertentu selama jenisnya sama, dan urutan langkah scanning. Catatan penting: berganti dari satu brand ke brand sejenis umumnya nonessential, tetapi mengganti JENIS couplant (mis. dari oil/glycerin ke gel berbeda) dapat menjadi essential bila mempengaruhi coupling/transfer — Level II harus mengevaluasi dampaknya, bukan mengasumsikannya."},{"heading":"Implikasi praktis","body":"Sebelum mengubah setting di lapangan, Level II harus mengecek apakah perubahan menyentuh essential variable. Contoh: procedure qualified untuk thickness 6-50 mm; datang komponen 75 mm. Itu di luar range thickness — essential variable terlampaui — procedure HARUS di-requalify untuk thickness baru sebelum inspeksi sah. Tidak boleh sekadar di-extrapolate atau dikompensasi dengan menaikkan gain."}]}', 500, NULL),
  (3, 'reading', 'Anatomi Written Procedure UT', '{"slides":[{"heading":"Header & scope","body":"Procedure dimulai dengan nomor & revisi, tanggal, referensi code beserta EDISI (misalnya ASME V Ed. 2023 untuk teknik + ASME VIII Div.1 untuk acceptance), scope (jenis weld, material/produk form, thickness range), dan personnel qualification yang disyaratkan (mis. Level II tersertifikasi sesuai written practice employer per SNT-TC-1A atau ISO 9712)."},{"heading":"Equipment & material section","body":"Wajib mencantumkan: model flaw detector (screen height & amplitude control linearity diverifikasi per T-461/T-462), transducer (frekuensi 2-5 MHz, ukuran element, tipe straight/angle), wedge & sudut, couplant (jenis, dengan ketentuan couplant SAMA dipakai saat kalibrasi dan inspeksi), serta kabel (tipe/panjang). Calibration block dispesifikasi: material yang acoustically similar dengan benda uji, surface finish, dan reflektor (SDH, FBH, atau notch sesuai code)."},{"heading":"Calibration & technique section","body":"Detailkan metode kalibrasi: sweep/screen range calibration, sensitivity (DAC, TCG, atau DGS), reference level, dan transfer correction untuk perbedaan surface/attenuation antara block dan part. Cantumkan scanning: arah scan (paralel & transversal terhadap weld), overlap minimum (umumnya >=10 persen lebar transducer), scanning speed maksimum (umumnya <=150 mm/s untuk manual), dan scanning gain (umumnya reference + 6 dB atau lebih untuk scanning, lalu kembali ke reference untuk evaluasi)."},{"heading":"Evaluation, recording & acceptance","body":"Tetapkan recording level (mis. >=20 persen DAC atau >=50 persen DAC sesuai code yang berlaku), metode sizing (6 dB drop untuk length, atau amplitude/endpoint sesuai code), dan acceptance criteria dengan referensi pasal eksplisit dan edisi (mis. ASME VIII Div.1 Mandatory Appendix 12, atau tabel acceptance UT pada AWS D1.1 — nomor tabel berbeda antar edisi). Procedure ditutup dengan format report dan ketentuan dokumentasi/retensi."}]}', 510, NULL),
  (4, 'reading', 'Procedure Qualification & Demonstration', '{"slides":[{"heading":"Kapan demonstrasi diperlukan","body":"ASME V T-421 mensyaratkan: jika kolom ''Requirement'' Table T-421 menandai sebuah essential variable memerlukan demonstrasi, maka procedure harus di-demonstrate pada satu atau lebih qualification block. Demonstrasi membuktikan bahwa procedure mampu mendeteksi reflektor reference (mis. SDH) di seluruh volume yang dipersyaratkan, termasuk pada kedalaman ekstrem dan zona dekat permukaan."},{"heading":"Range qualification — prinsip","body":"Range qualification menetapkan rentang yang dicakup satu kali kualifikasi sehingga tidak perlu meng-kualifikasi setiap nilai individual. Contoh thickness: demonstrasi pada satu thickness mengkualifikasi range tertentu di sekitarnya SESUAI BATAS YANG DITETAPKAN CODE EDISI BERSANGKUTAN (jangan diasumsikan). Untuk PAUT/TOFD, ASME V Article 4 menambah essential variable spesifik melalui Mandatory Appendix-nya, seperti focal law/angular range, element pitch, dan probe center separation (PCS) untuk TOFD."},{"heading":"Qualification block design","body":"Block kualifikasi harus mewakili: material/produk form yang sama atau acoustically equivalent, thickness range, weld joint geometry, dan surface condition. Reflektor (mis. SDH diameter 1.5-3 mm, atau notch dengan tinggi sesuai code) ditempatkan untuk membuktikan coverage di seluruh ketebalan. Untuk demonstrasi berbasis flaw (mis. PAUT sebagai alternatif ke RT), block sering berisi cacat real atau EDM notch terkalibrasi sebagai target deteksi."},{"heading":"Dokumentasi qualification record","body":"Setiap qualification menghasilkan record: identitas procedure & revisi, block yang dipakai, hasil deteksi tiap reflektor, parameter aktual yang digunakan, tanggal, dan tanda tangan personil (Level II/III yang melakukan demonstrasi + Level III yang menyetujui procedure). Record ini menjadi bukti audit bahwa procedure valid. Tanpa record demonstrasi, procedure yang mensyaratkannya dianggap belum qualified meskipun dokumen sudah lengkap."}]}', 500, NULL),
  (5, 'reading', 'Revisi, Kontrol Dokumen & Studi Kasus', '{"slides":[{"heading":"Revision control","body":"Setiap perubahan procedure memerlukan revisi bernomor dengan catatan perubahan (change record). Bila perubahan menyentuh essential variable yang mensyaratkan demonstrasi, procedure harus di-requalify sebelum revisi berlaku. Versi lama harus ditarik (superseded) agar tidak ada operator yang memakai revisi usang. Sistem document control (mis. per ISO 9001) wajib menjamin hanya revisi terkini yang beredar di titik penggunaan."},{"heading":"Studi kasus 1 — thickness di luar range","body":"Procedure UT-001 Rev.2 qualified untuk butt weld carbon steel 8-40 mm, sudut 45/60/70, DAC dari block 25 mm dengan SDH 3 mm. Datang vessel shell 64 mm. Karena 64 mm di luar range thickness (essential variable), Level II tidak boleh langsung inspeksi. Tindakan benar: siapkan qualification block yang mewakili 64 mm, demonstrasi coverage, terbitkan Rev.3 dengan range diperluas (disetujui Level III), lalu inspeksi."},{"heading":"Studi kasus 2 — ganti transducer","body":"Di lapangan transducer 4 MHz rusak; hanya tersedia 2.25 MHz. Frekuensi adalah essential variable. Mengganti ke 2.25 MHz mengubah beam spread, near-field length, dan resolusi — procedure menjadi invalid untuk frekuensi itu KECUALI range frekuensi (mis. 2-5 MHz) sudah dicakup dan, bila disyaratkan, di-demonstrate. Pelajaran: tulis range frekuensi yang realistis dan, bila perlu demonstrasi, buktikan deteksi pada ujung-ujung range saat qualification."},{"heading":"Checklist akhir Level II","body":"Sebelum procedure dipakai: (1) semua essential variable tercantum dengan range; (2) referensi code & pasal acceptance eksplisit dan EDISI benar; (3) calibration & sizing method jelas; (4) qualification/demonstration record terlampir bila disyaratkan; (5) approval Level III ada; (6) revision control aktif. Procedure yang baik membuat dua inspektor berbeda menghasilkan hasil yang konsisten — itulah ukuran kualitas sebenarnya."}]}', 440, NULL),
  (6, 'quiz', 'Mini-quiz — Inspection Procedures Development', '{"description":"Konfirmasi pemahaman penyusunan written procedure, essential vs nonessential variables, range qualification, dan revision control.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 8
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 8 mini-quiz (7 questions, step 6)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 6 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Apa perbedaan mendasar antara essential variable dan nonessential variable dalam written procedure UT per ASME V Article 4 (T-421)?',
   '["Essential variable harus dicatat di report; nonessential variable boleh diabaikan","Perubahan essential variable di luar range mewajibkan requalification procedure; perubahan nonessential variable tidak (namun tetap dicatat)","Essential variable hanya berlaku untuk PAUT; nonessential variable untuk UT konvensional","Essential variable ditetapkan operator; nonessential variable ditetapkan Level III"]', 1,
   'Essential variable adalah parameter yang, jika diubah di luar range yang ditetapkan/di-demonstrate (mis. frekuensi, sudut, thickness range), mewajibkan requalification procedure. Nonessential variable boleh diubah dalam batas yang ditetapkan tanpa requalify, tetapi setiap perubahan tetap harus dicatat.', 'Procedure Development', 'easy'),
  ('Procedure qualified untuk butt weld carbon steel range thickness 8-40 mm. Datang komponen 64 mm. Tindakan yang benar bagi Level II adalah:',
   '["Langsung inspeksi karena 64 mm hanya sedikit di atas 40 mm","Naikkan gain +6 dB untuk mengompensasi thickness lalu inspeksi","Requalify procedure (block mewakili thickness baru, demonstrasi coverage) dan terbitkan revisi yang disetujui sebelum inspeksi","Buat technique sheet baru dengan thickness 64 mm tanpa mengubah/requalify procedure"]', 2,
   'Thickness range adalah essential variable. 64 mm di luar range 8-40 mm berarti procedure invalid untuk thickness itu. Harus disiapkan qualification block yang mewakili, di-demonstrate coverage-nya, dan diterbitkan revisi (approval Level III) sebelum inspeksi sah. Tidak boleh diekstrapolasi atau dikompensasi gain, dan technique sheet tidak boleh keluar dari batas procedure.', 'Range Qualification', 'medium'),
  ('Manakah pernyataan yang benar tentang hubungan written procedure dengan technique sheet (scan plan)?',
   '["Technique sheet menggantikan procedure untuk komponen kompleks","Procedure menetapkan range parameter yang diizinkan; technique sheet memilih nilai spesifik dalam range itu untuk satu komponen","Keduanya identik dan hanya berbeda nama","Technique sheet harus di-requalify setiap kali procedure mengalami revisi minor"]', 1,
   'Procedure adalah dokumen umbrella yang menetapkan range parameter yang diizinkan (mis. 2-5 MHz, 45-70 derajat). Technique sheet mengaplikasikan procedure ke satu komponen spesifik dengan memilih nilai aktual dalam range tersebut, dan tidak boleh keluar dari batas itu. Satu procedure dapat menurunkan banyak technique sheet.', 'Procedure Development', 'medium'),
  ('Mengapa demonstrasi (procedure qualification) pada qualification block diperlukan ketika Table T-421 menandainya untuk sebuah essential variable?',
   '["Untuk melatih operator Level I sebelum sertifikasi","Untuk membuktikan procedure mampu mendeteksi reflektor reference di seluruh volume yang dipersyaratkan, termasuk zona ekstrem","Hanya untuk memenuhi formalitas administratif tanpa dampak teknis","Untuk mengkalibrasi flaw detector sebelum dijual"]', 1,
   'Demonstrasi membuktikan procedure (dengan essential variable yang ditetapkan) benar-benar dapat mendeteksi reflektor reference seperti SDH di seluruh volume yang dipersyaratkan, termasuk kedalaman ekstrem dan zona dekat permukaan. Ini bukti kemampuan deteksi, bukan sekadar formalitas administratif.', 'Procedure Qualification', 'medium'),
  ('Transducer 4 MHz rusak di lapangan dan hanya tersedia 2.25 MHz. Procedure tidak mencantumkan range frekuensi yang mencakup 2.25 MHz. Apa konsekuensinya?',
   '["Tidak masalah, frekuensi bukan essential variable","Boleh dipakai asalkan ukuran element sama","Procedure menjadi invalid untuk frekuensi itu karena frekuensi adalah essential variable yang mengubah beam spread dan near-field","Boleh dipakai dengan menaikkan reference level sebesar selisih dB"]', 2,
   'Frekuensi transducer adalah essential variable. Mengubahnya mengubah beam spread, near-field length, dan resolusi. Jika range frekuensi yang mencakup 2.25 MHz belum ditetapkan/di-demonstrate, procedure menjadi invalid untuk frekuensi tersebut sampai di-requalify.', 'Essential Variables', 'hard'),
  ('Manakah yang HARUS dispesifikasi pada section equipment & material dari written procedure UT?',
   '["Flaw detector (linearity terverifikasi), transducer (frekuensi/ukuran/tipe), wedge/sudut, couplant, kabel, dan calibration block (material, surface, reflektor)","Hanya merek flaw detector","Nama operator dan jam kerjanya","Hanya acceptance criteria dan format report"]', 0,
   'Section equipment & material wajib mencakup flaw detector dengan linearity terverifikasi (T-461/T-462), transducer lengkap (frekuensi, ukuran element, tipe), wedge & sudut, couplant, kabel, serta calibration block (material acoustically similar, surface finish, dan reflektor seperti SDH/FBH/notch). Nama operator dan acceptance criteria saja tidak mencakup section ini.', 'Procedure Anatomy', 'easy'),
  ('Apa yang membuat sebuah procedure (yang mensyaratkan demonstrasi) dianggap belum qualified meskipun dokumennya sudah ditulis lengkap?',
   '["Tidak adanya logo perusahaan pada header","Tidak adanya nomor halaman","Tidak mencantumkan nama supplier transducer","Tidak adanya qualification/demonstration record (bukti deteksi pada block dengan parameter aktual dan tanda tangan personil)"]', 3,
   'Procedure yang mengandung essential variable yang ditandai memerlukan demonstrasi harus memiliki qualification record: identitas procedure/revisi, block yang dipakai, hasil deteksi tiap reflektor, parameter aktual, tanggal, dan tanda tangan (pelaksana + Level III approval). Tanpa record demonstrasi tersebut, procedure belum qualified walau dokumen lengkap. Logo, nomor halaman, dan nama supplier tidak menentukan status qualified.', 'Procedure Qualification', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 6 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


-- ============================================================
-- SNS NDT — UT-L2 content (AUTO-GENERATED from authoring workflow)
-- Run AFTER seed_elearning_level2_all_methods.sql (modules must exist).
