-- UT-L2 Module 9 — Code Interpretation — ASME, AWS, API (6 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Peta Kode: Technique, Construction & In-Service', '{"slides":[{"heading":"Tiga lapis dokumen normatif","body":"Level II wajib paham bahwa satu inspeksi UT diatur oleh beberapa dokumen sekaligus, bukan satu code tunggal. Lapisan pertama adalah TECHNIQUE/METHOD standard yang mengatur CARA melakukan UT (mis. ASME BPVC Section V Article 4, ASTM E164, ISO 16810/16811). Lapisan kedua adalah CONSTRUCTION/REFERENCING code yang menetapkan KRITERIA PENERIMAAN dan kapan UT wajib (mis. ASME VIII Div.1, ASME B31.3, AWS D1.1, API 1104). Lapisan ketiga adalah IN-SERVICE/inspection code untuk equipment yang sudah beroperasi (API 510 untuk vessel, API 570 untuk piping, API 653 untuk tank). Kesalahan klasik pemula: memakai acceptance dari Section V — padahal Section V hanya mengatur teknik, BUKAN accept/reject."},{"heading":"Section V hanya teknik, bukan acceptance","body":"ASME Section V (Article 4 untuk UT) mendefinisikan kalibrasi, scanning, recording, dan sizing, tetapi secara eksplisit menyatakan acceptance criteria ditetapkan oleh referencing code section. Jadi: ASME VIII Div.1 memerintahkan ''lakukan UT per Section V, terima/tolak per Mandatory Appendix di Section VIII''. Demikian pula B31.3 dan B31.1 menunjuk Section V untuk metode, lalu menetapkan tabel acceptance-nya sendiri. Inspektor harus selalu memeriksa pasangan ini: technique code + construction code, lengkap dengan EDISI/ADDENDA yang berlaku pada kontrak."},{"heading":"Code mana menetapkan apa","body":"Untuk pressure equipment baru: ASME VIII Div.1/Div.2 + Section V. Untuk power/process piping: ASME B31.1 / B31.3 + Section V. Untuk struktur baja las: AWS D1.1 (yang berdiri sendiri — memuat baik teknik UT maupun acceptance-nya di satu dokumen). Untuk pipeline transmisi: API 1104 (kriteria workmanship di badan code + alternatif ECA di Annex A). Untuk in-service: API 510/570/653 yang merujuk balik ke construction code untuk repair tetapi menetapkan interval & scope inspeksinya sendiri. Memetakan dengan benar ''siapa menetapkan apa'' adalah kompetensi inti Level II yang men-sign report."},{"heading":"Hierarki dokumen kontrak","body":"Di proyek nyata urutan otoritas biasanya: regulasi/jurisdiksi (mis. ASME stamp requirement, peraturan boiler & pressure vessel negara bagian) di atas construction code, lalu spesifikasi proyek/klien, lalu project procedure. Spesifikasi klien sering LEBIH KETAT dari code minimum (mis. mensyaratkan 100% UT padahal code hanya minta spot/partial). Bila terjadi konflik, dokumen yang lebih ketat umumnya menang kecuali kontrak menyatakan lain. Level II tidak boleh meng-accept indikasi hanya karena ''lolos code'' bila spesifikasi proyek mensyaratkan kriteria lebih ketat — selalu baca governing document chain sebelum mengevaluasi."}]}', 480, NULL),
  (2, 'reading', 'ASME — Amplitude-Based vs Flaw-Based Acceptance', '{"slides":[{"heading":"Dua filosofi acceptance ASME","body":"ASME memakai dua pendekatan acceptance yang harus dibedakan tegas oleh Level II. (1) AMPLITUDE-BASED (workmanship): indikasi dievaluasi terhadap reference level (mis. DAC) dan length; reflektor yang menghasilkan respons melebihi batas amplitudo+length ditolak. (2) FLAW-BASED (fracture-mechanics): cacat di-size (height & length) lalu dibandingkan dengan tabel allowable flaw size yang diturunkan dari engineering critical assessment. Pendekatan flaw-based mengizinkan cacat tertentu tetap tinggal selama lebih kecil dari allowable size — sangat berbeda dari logika ''ada indikasi besar = reject''."},{"heading":"ASME VIII Div.1 — Appendix 12 & arah modern","body":"Secara historis ASME Section VIII Div.1 Mandatory Appendix 12 mengatur UT amplitude-based: indikasi yang melebihi reference (DAC) dievaluasi terhadap batas length sebagai fungsi ketebalan, dan crack, lack of fusion, serta incomplete penetration bersifat rejectable apa pun panjangnya. Edisi modern Div.1 menambahkan opsi UT terkomputerisasi dengan acceptance flaw-based (mengacu metodologi seperti Section VIII Div.2/Code Case) untuk weld tebal, di mana UT dapat menggantikan RT. Karena pasal & nomor appendix dapat bergeser antar edisi, prosedur WAJIB menyebut edisi & addenda yang dipakai — jangan mengutip nomor appendix dari ingatan."},{"heading":"Code Case 2235 — UT sebagai pengganti RT","body":"ASME Code Case 2235 mengizinkan UT (umumnya PAUT/AUT terenkode) menggantikan radiography untuk welds di atas ketebalan tertentu pada vessel & piping, dengan syarat procedure demonstration dan acceptance berbasis flaw size. Ini menggeser peran Level II dari sekadar ''membaca amplitude'' menjadi melakukan sizing presisi yang menentukan accept/reject secara kuantitatif. Penggunaan Code Case harus diizinkan oleh jurisdiksi & dicantumkan dalam dokumentasi karena Code Case bersifat opsional sampai diadopsi kontrak/jurisdiksi."},{"heading":"Recording vs evaluation vs rejection level","body":"Tiga ambang berbeda sering tertukar. RECORDING LEVEL: amplitudo minimum yang wajib dicatat (mis. 20% DAC untuk teknik tertentu). EVALUATION LEVEL: ambang di mana indikasi harus diselidiki lebih lanjut (mis. 50% DAC). REJECTION/ACCEPTANCE: keputusan akhir terhadap kriteria code. Scanning umumnya dilakukan pada gain reference + tambahan dB (mis. reference + 6 dB atau lebih) lalu dikembalikan ke reference untuk evaluasi amplitudo. Level II harus menyatakan ketiga level ini eksplisit dalam laporan agar hasil dapat diaudit dan direproduksi."}]}', 500, NULL),
  (3, 'reading', 'AWS D1.1 — Sistem Indication Rating', '{"slides":[{"heading":"AWS D1.1 berdiri sendiri","body":"Berbeda dari ASME, AWS D1.1 (Structural Welding Code — Steel) memuat baik prosedur UT maupun acceptance criteria dalam satu dokumen (klausa UT dan tabel penerimaannya). Acceptance UT pada D1.1 memakai sistem INDICATION RATING berbasis dB, bukan sekadar perbandingan langsung ke DAC seperti ASME. Inspektor mengukur indication level, mengoreksi terhadap reference dan atenuasi, lalu membandingkan rating akhir dengan tabel acceptance yang berbeda untuk sambungan statically loaded vs cyclically loaded."},{"heading":"Rumus rating d = a − b − c","body":"Indication rating dihitung: d = a − b − c (dalam dB). a = indication level (gain dB instrumen saat sinyal indikasi diset ke reference height pada layar, mis. 50% FSH). b = reference level (gain dB saat sinyal dari reference reflector — side-drilled hole 1,5 mm pada IIW block — diset ke reference height yang sama). c = attenuation factor. PERHATIKAN KONVENSI TANDA YANG BENAR: reflektor yang LEBIH BESAR/kuat butuh gain a yang LEBIH RENDAH untuk mencapai reference height, sehingga menghasilkan d yang LEBIH KECIL/lebih NEGATIF — d negatif menandakan reflektor relatif BESAR dan cenderung rejectable. Sebaliknya, reflektor lemah butuh gain a tinggi sehingga d POSITIF besar — menandakan reflektor relatif KECIL dan cenderung acceptable. (Contoh tipikal: d = −1 menandakan reflektor besar, d = +5 menandakan reflektor kecil.)"},{"heading":"Attenuation factor & static vs cyclic","body":"Attenuation factor c = (sound path − 25,4 mm) × ~0,08 dB/mm, ekuivalen 2 dB per inch untuk sound path melebihi 25,4 mm (1 inch). c mengoreksi rugi atenuasi sepanjang jalur suara agar indikasi pada kedalaman berbeda dapat dibandingkan secara adil terhadap reference — bukan untuk ''menguntungkan'' indikasi dalam, melainkan menormalkan pengaruh jarak tempuh. AWS D1.1 juga memberi tabel acceptance terpisah: struktur statically loaded (mis. bangunan) dan cyclically loaded (mis. jembatan, beban fatigue). Tabel cyclic lebih ketat karena cacat menjadi titik inisiasi fatigue."},{"heading":"Severity class & perbedaan praktis vs ASME","body":"Acceptance AWS bergantung pada tipe beban, weld thickness, dan posisi indikasi dalam ketebalan: zona dekat permukaan diberi kriteria lebih ketat daripada zona tengah/dalam, sebab cacat near-surface lebih kritis terhadap inisiasi retak. Implikasi penting: pada AWS dua indikasi dengan gain a sama bisa menghasilkan rating berbeda karena sound path (jadi c) berbeda. Pada ASME, evaluasi lebih bertumpu pada DAC/length atau flaw size. Level II yang berpindah antar industri (pressure ke struktur) harus mereset ''mental model'' acceptance: jangan menerapkan logika DAC-length ASME pada sambungan AWS, dan sebaliknya. Selalu pakai sistem code yang governing untuk pekerjaan itu."}]}', 480, NULL),
  (4, 'reading', 'API — Workmanship vs ECA & In-Service', '{"slides":[{"heading":"API 1104 — dua jalur acceptance","body":"API 1104 (Welding of Pipelines and Related Facilities) menyediakan DUA jalur. Jalur pertama: kriteria WORKMANSHIP di badan code — berbasis jenis & dimensi cacat (mis. batas panjang untuk incomplete penetration, lack of fusion, internal concavity, burn-through), relatif konservatif dan tidak butuh analisis tegangan. Jalur kedua: Annex A ALTERNATIVE ACCEPTANCE STANDARDS berbasis fracture mechanics / Engineering Critical Assessment (ECA), di mana cacat diterima/ditolak terhadap allowable flaw size yang diturunkan dari toughness material, tegangan, dan beban operasi. ECA mengizinkan cacat lebih besar tetap tinggal selama terbukti aman."},{"heading":"Kapan ECA dipakai & syaratnya","body":"ECA (API 1104 Annex A) lazim pada pipeline yang di-las dengan AUT (TOFD + PAUT zonal) karena memungkinkan sizing height & length akurat — input wajib bagi penilaian fracture mechanics. Syarat penggunaan Annex A ketat: harus ada data CTOD/fracture toughness, prosedur UT yang qualified untuk sizing dengan akurasi terbukti, dan persetujuan engineering. Karena keputusan accept/reject langsung bergantung pada sizing UT, error sizing TOFD/PAUT berdampak langsung pada integritas — inilah mengapa Level II AUT menuntut endorsement & demonstrasi kompetensi sizing."},{"heading":"API 510 / 570 / 653 — in-service","body":"Untuk equipment beroperasi: API 510 (pressure vessel), API 570 (process piping), API 653 (aboveground storage tank). Code ini menetapkan INTERVAL & SCOPE inspeksi (mis. thickness monitoring UT untuk corrosion), menghitung remaining life dari corrosion rate, dan menentukan kapan repair/rerate diperlukan. UT di sini sering bersifat thickness gauging dan deteksi/sizing crack akibat damage mechanism (mis. HTHA, SCC, fatigue). Acceptance untuk cacat fabrikasi/weld baru biasanya mengacu balik ke construction code, sedangkan kelayakan operasi cacat lama dinilai via fitness-for-service."},{"heading":"Jembatan ke API 579-1/ASME FFS-1","body":"Ketika cacat ditemukan pada equipment in-service melebihi kriteria sederhana, API 579-1/ASME FFS-1 (Fitness-For-Service) digunakan untuk menilai apakah equipment tetap aman beroperasi tanpa repair segera. FFS membutuhkan data UT presisi: minimum measured thickness, dimensi local thin area, atau height/length crack-like flaw. Level II menyediakan data kuantitatif ini; engineer melakukan assessment Level 1/2/3 FFS. Memahami bahwa output sizing UT menjadi input keputusan FFS membuat Level II menyadari pentingnya akurasi & dokumentasi pengukuran, bukan sekadar accept/reject biner."}]}', 480, NULL),
  (5, 'reading', 'Code Change Tracking & Penerapan yang Benar', '{"slides":[{"heading":"Edisi, addenda, dan tanggal berlaku","body":"Code direvisi berkala: ASME BPVC kini terbit per edisi 2-tahunan (mis. 2019, 2021, 2023) menggantikan sistem addenda tahunan lama; AWS D1.1 terbit tiap beberapa tahun; API code punya edisi + addenda. Setiap kontrak MENGUNCI edisi/addenda yang berlaku (governing edition). Pasal, nomor tabel, dan bahkan nilai batas bisa berubah antar edisi — itulah sebabnya prosedur & laporan harus menyebut edisi spesifik. Mengutip ''Table 6.2 AWS D1.1'' tanpa menyebut tahun bisa salah karena penomoran tabel telah bergeser antar edisi."},{"heading":"Mengapa nomor pasal bergeser","body":"Contoh nyata: acceptance UT AWS D1.1 pernah berada di Tabel 6.x pada edisi tertentu lalu dipetakan ulang ke Tabel 8.x (Clause 8) pada edisi berikutnya; ASME Section VIII Div.1 menata ulang appendix dan memindahkan sebagian persyaratan UT antar edisi. Level II tidak boleh menghafal nomor pasal sebagai kebenaran tetap — yang harus dikuasai adalah KONSEP acceptance (amplitude vs flaw-based, rating system, workmanship vs ECA) lalu memverifikasi nomor pasal pada edisi yang governing. Selalu rujuk salinan code edisi yang benar saat menulis laporan."},{"heading":"Disposisi konflik & interpretasi resmi","body":"Bila terjadi ambiguitas, ASME/AWS/API menerbitkan Code Interpretations / Code Cases resmi. Interpretation menjelaskan maksud pasal yang ada; Code Case memberi aturan alternatif/sementara. Keduanya hanya berlaku bila diadopsi jurisdiksi/kontrak. Inspektor TIDAK boleh membuat interpretasi pribadi atas pasal yang ambigu untuk meng-accept cacat — eskalasi ke Level III/engineering, dan dokumentasikan dasar keputusan. Penyimpangan dari code (concession/deviation) harus melalui proses formal dan disetujui pihak berwenang, bukan keputusan sepihak di lapangan."},{"heading":"Checklist code interpretation Level II","body":"Sebelum men-sign report: (1) identifikasi technique code + construction/in-service code yang governing beserta EDISI; (2) konfirmasi acceptance criteria yang benar (amplitude/flaw/rating/workmanship) dan pasal eksaknya pada edisi itu; (3) periksa apakah spesifikasi proyek lebih ketat dari code; (4) verifikasi prosedur qualified untuk kriteria & sizing yang dipakai; (5) cantumkan reference level, recording/evaluation level, dan metode sizing; (6) dokumentasikan Code Case/Interpretation yang dipakai. Disiplin ini membuat keputusan accept/reject dapat dipertahankan saat audit atau tinjauan klien."}]}', 440, NULL),
  (6, 'quiz', 'Mini-quiz — Code Interpretation (ASME/AWS/API)', '{"description":"Konfirmasi pemahaman peta code (technique vs construction vs in-service), acceptance amplitude-based vs flaw-based ASME, sistem indication rating AWS D1.1 (rumus & konvensi tanda), jalur workmanship vs ECA API 1104, code in-service API 510/570/653, dan disiplin code change tracking/edisi.","questionCount":8,"passingScore":75}', 720, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 9
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 9 mini-quiz (8 questions, step 6)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 6 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Dalam kerangka code UT, peran ASME BPVC Section V Article 4 yang benar adalah...',
   '["Menetapkan acceptance criteria accept/reject untuk semua weld pressure equipment","Mengatur TEKNIK pemeriksaan UT (kalibrasi, scanning, sizing), sedangkan acceptance ditetapkan oleh referencing/construction code","Menggantikan AWS D1.1 untuk struktur baja","Menetapkan interval inspeksi in-service untuk vessel"]', 1,
   'Section V (Article 4) hanya mengatur teknik UT — kalibrasi, scanning, recording, sizing — dan secara eksplisit menyatakan acceptance ditetapkan oleh referencing code (mis. ASME VIII Div.1 Mandatory Appendix). Acceptance bukan domain Section V.', 'Code Framework', 'easy'),
  ('Apa perbedaan mendasar antara acceptance AMPLITUDE-BASED dan FLAW-BASED pada ASME?',
   '["Amplitude-based hanya untuk PAUT; flaw-based hanya untuk UT konvensional","Keduanya identik, hanya berbeda nama antar edisi","Amplitude-based mengevaluasi indikasi terhadap reference (DAC) & length; flaw-based meng-size cacat (height & length) lalu membandingkan terhadap allowable flaw size dari fracture mechanics","Flaw-based selalu menolak semua indikasi yang melebihi recording level"]', 2,
   'Amplitude-based (workmanship) membandingkan respons terhadap reference (DAC) dan batas length. Flaw-based (fracture-mechanics) men-size cacat lalu membandingkannya dengan allowable flaw size, sehingga cacat tertentu boleh tinggal selama lebih kecil dari batas tersebut.', 'ASME Acceptance', 'medium'),
  ('Pada sistem indication rating AWS D1.1, rating d dihitung dengan rumus...',
   '["d = a + b + c (jumlah semua level dB)","d = a − b − c, dengan a = indication level, b = reference level, c = attenuation factor","d = (a × b) / c","d = b − a (reference dikurangi indikasi saja, tanpa atenuasi)"]', 1,
   'AWS D1.1 menghitung indication rating d = a − b − c, di mana a = indication level (dB), b = reference level (dB dari SDH 1,5 mm pada IIW block), dan c = attenuation factor. Hasil d dibandingkan dengan tabel acceptance untuk menentukan accept/reject.', 'AWS D1.1', 'medium'),
  ('Pada AWS D1.1, sebuah indikasi menghasilkan rating d = −2 dB sementara indikasi lain menghasilkan d = +6 dB. Interpretasi yang BENAR adalah...',
   '["d = −2 dB menandakan reflektor relatif BESAR (cenderung rejectable); d = +6 dB menandakan reflektor relatif KECIL/lemah (cenderung acceptable)","d = +6 dB selalu lebih berbahaya karena angkanya lebih besar","Kedua nilai identik signifikansinya; tanda hanya formalitas","d = −2 dB berarti tidak ada indikasi karena nilainya negatif"]', 0,
   'Karena d = a − b − c dan reflektor besar butuh gain a yang lebih rendah untuk mencapai reference height, reflektor besar menghasilkan d yang lebih kecil/negatif (mis. −2 dB) dan cenderung rejectable. Reflektor kecil/lemah butuh gain tinggi sehingga d positif besar (mis. +6 dB) dan cenderung acceptable. Tanda dan besar d menentukan severity class terhadap tabel acceptance.', 'AWS D1.1', 'hard'),
  ('Attenuation factor (c) pada perhitungan rating AWS D1.1 kira-kira sebesar...',
   '["2 dB per inch sound path yang melebihi 25,4 mm (≈0,08 dB/mm)","6 dB untuk setiap penurunan amplitudo setengah","20 dB per inch tanpa memandang sound path","0 dB karena atenuasi diabaikan pada baja"]', 0,
   'c = (sound path − 25,4 mm) × ~0,08 dB/mm, ekuivalen 2 dB per inch untuk sound path di atas 25,4 mm (1 inch). c mengoreksi rugi atenuasi sepanjang jalur suara agar indikasi pada kedalaman berbeda dapat dibandingkan secara adil terhadap reference, bukan untuk menguntungkan indikasi yang lebih dalam.', 'AWS D1.1', 'hard'),
  ('API 1104 menyediakan dua jalur acceptance untuk weld pipeline. Jalur Annex A (alternative acceptance standards) didasarkan pada...',
   '["Penilaian visual ketinggian reinforcement saja","Engineering Critical Assessment (ECA) berbasis fracture mechanics — cacat dibanding allowable flaw size dari toughness, tegangan, dan beban operasi","Jumlah total indikasi tanpa memandang ukuran","Warna grayscale pada D-scan TOFD"]', 1,
   'API 1104 Annex A memberi acceptance berbasis ECA/fracture mechanics: cacat diterima/ditolak terhadap allowable flaw size yang diturunkan dari fracture toughness, tegangan, dan beban operasi — mengizinkan cacat lebih besar tinggal selama terbukti aman, berbeda dari jalur workmanship di badan code yang berbasis dimensi cacat sederhana.', 'API 1104', 'medium'),
  ('Pasangan code mana yang TEPAT untuk inspeksi in-service (equipment yang sudah beroperasi)?',
   '["ASME VIII Div.1 untuk fabrikasi vessel baru","AWS D1.1 untuk struktur baja baru","API 510 untuk pressure vessel, API 570 untuk process piping, API 653 untuk aboveground storage tank","ASME B31.3 untuk process piping baru"]', 2,
   'API 510 (vessel), API 570 (piping), dan API 653 (tank) adalah in-service inspection codes yang menetapkan interval, scope, perhitungan remaining life, dan repair/rerate. ASME VIII Div.1, AWS D1.1, dan B31.3 adalah construction code untuk fabrikasi baru.', 'In-Service Codes', 'easy'),
  ('Saat sebuah pasal code tampak ambigu sehingga memengaruhi keputusan accept/reject, tindakan yang benar bagi Level II adalah...',
   '["Membuat interpretasi pribadi yang paling menguntungkan agar proyek lanjut","Mengabaikan indikasi karena pasalnya tidak jelas","Eskalasi ke Level III/engineering dan, bila perlu, merujuk Code Interpretation/Code Case resmi yang diadopsi jurisdiksi; dokumentasikan dasar keputusan","Menaikkan reference level hingga indikasi lolos"]', 2,
   'Inspektor tidak boleh membuat interpretasi pribadi atas pasal ambigu. ASME/AWS/API menerbitkan Code Interpretations dan Code Cases resmi yang hanya berlaku bila diadopsi jurisdiksi/kontrak. Ambiguitas dieskalasi ke Level III/engineering dan keputusan didokumentasikan; concession/deviation harus melalui proses formal.', 'Code Interpretation', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 6 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 10 — Reporting & Defect Sizing (6 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Prinsip Defect Sizing — kenapa dan keterbatasannya', '{"slides":[{"heading":"Detection vs Sizing vs Characterization","body":"Level I cukup mendeteksi (ada sinyal di atas reference level). Level II harus melangkah lebih jauh: menentukan POSISI (depth dan posisi lateral terhadap datum), DIMENSI (length dan through-wall height), serta KARAKTER cacat (planar vs volumetric, embedded vs surface-breaking). Acceptance criteria berbasis fracture mechanics / fitness-for-service (mis. API 579-1/ASME FFS-1, BS 7910) menuntut cacat dikuantifikasi sebagai through-wall extent (a untuk surface flaw, 2a untuk embedded) dan length (2c atau l), bukan sekadar amplitudo. Tanpa sizing yang benar, evaluasi fitness-for-service tidak mungkin dilakukan."},{"heading":"Amplitudo tidak sama dengan ukuran","body":"Kesalahan umum: menganggap amplitudo tinggi pasti berarti cacat besar. Amplitudo dipengaruhi oleh orientasi reflektor terhadap beam, kekasaran dan sifat permukaan reflektor (tip vs face), serta posisi cacat dalam beam profile. Sebuah crack planar yang nyaris sejajar arah beam bisa memberi amplitudo rendah meskipun besar (poor orientation/skewed), sementara reflektor planar kecil yang tegak lurus beam (favorably oriented) dapat memberi sinyal tinggi. Karena itu sizing amplitude-based (mis. 6 dB drop) hanya valid bila reflektor lebih kecil dari beam pada satu sumbu dan lebih besar pada sumbu lain — asumsi yang harus selalu disadari operator."},{"heading":"Sumber error sizing dan ketidakpastian","body":"Setiap teknik sizing punya error budget. Length sizing dengan 6 dB drop cenderung over-size reflektor kecil (akibat beam width dan beam spread) dan under-size reflektor besar yang menerus. Height sizing amplitude-based bisa meleset orde 2-5 mm; teknik tip-diffraction (TOFD atau crack-tip echo) jauh lebih akurat (tipikal di sekitar +/-1 mm) karena mengukur waktu tempuh ke ujung cacat, bukan amplitudo. Selalu laporkan teknik yang dipakai beserta ketidakpastiannya — angka sizing tanpa metode adalah angka tanpa makna."},{"heading":"Kalibrasi sebagai fondasi sizing yang valid","body":"Sizing hanya sevalid kalibrasinya. Range/sweep harus dikalibrasi pada blok IIW (V1)/V2 atau step wedge sehingga posisi (sound path, depth, surface distance) akurat. Untuk amplitude sizing diperlukan kurva referensi (DAC atau TCG/DGS) agar drop dB konsisten terhadap jarak. Verifikasi exit point (BIP) dan refracted angle pada blok kalibrasi sebelum sizing; angle yang meleset 2-3 derajat menggeser depth-plotting dan menyebabkan salah lokasi cacat pada through-wall."}]}', 460, NULL),
  (2, 'reading', 'Length Sizing — teknik 6 dB drop dan alternatifnya', '{"slides":[{"heading":"Metode 6 dB drop (half-amplitude)","body":"Teknik length sizing yang paling umum. Maksimalkan sinyal dari cacat, set ke level referensi (mis. 80% FSH), lalu geser probe sepanjang cacat sampai amplitudo turun 6 dB (separuh tinggi layar, mis. 80% menjadi 40% FSH) di tiap ujung. Tandai posisi probe pada kedua titik; jarak antar kedua titik = length cacat. Dasar fisikanya: titik 6 dB drop kira-kira berada di tepi beam (50% intensitas) terhadap reflektor. Valid bila reflektor lebih besar dari beam width pada arah scan; untuk reflektor kecil hasilnya menjadi pengukuran beam width, bukan ukuran cacat (over-sizing)."},{"heading":"20 dB drop dan beam spread","body":"Teknik 20 dB drop menandai titik di mana amplitudo turun ke 10% dari referensi (20 dB) untuk memetakan tepi cacat. Lebih sering dipakai untuk memetakan profil cacat besar/extended bila tepi beam yang relevan didefinisikan pada 20 dB (mis. beam plotting/profiling). Karena melibatkan tepi beam yang lebih lebar, koreksi beam spread harus diperhitungkan agar tidak over-size. Pilihan 6 dB vs 20 dB ditentukan oleh prosedur tertulis dan code; jangan dicampur dalam satu pengukuran."},{"heading":"Maximum amplitude technique","body":"Untuk cacat yang terdiri dari banyak facet (mis. crack bercabang, atau slag/inclusion yang terputus-putus), metode max-amp menggeser probe dan mencatat setiap posisi yang memberi peak lokal maksimum. Length diukur antara posisi peak pertama dan peak terakhir. Lebih cocok daripada 6 dB drop untuk reflektor multi-faceted karena tiap facet memberi peaknya sendiri. Cenderung memberi length yang lebih besar dibanding 6 dB drop pada cacat yang sama, sehingga lebih konservatif untuk evaluasi."},{"heading":"Koreksi dan pelaporan length","body":"Selalu catat: teknik (6 dB / 20 dB / max-amp), level referensi, dan apakah koreksi beam-width/transfer diterapkan. Untuk cacat dekat permukaan, perhatikan dead zone dan near-field. Bila length cacat sudah jelas melebihi batas yang relevan dengan code, cacat dapat langsung diklasifikasikan reject tanpa perlu mengukur tepat. Length harus diproyeksikan ke arah las (along weld axis), bukan sepanjang sound path; gunakan trigonometri probe-to-flaw untuk konversi bila perlu."}]}', 480, NULL),
  (3, 'reading', 'Height (Through-Wall) Sizing — teknik diffraction', '{"slides":[{"heading":"Kenapa height paling penting untuk integritas","body":"Dalam fracture mechanics, through-wall height (kedalaman a untuk surface flaw, 2a untuk embedded) adalah parameter dominan dalam menghitung stress intensity factor K dan crack driving force; untuk surface crack, K = Y*sigma*akar(pi*a). Length tetap penting, tetapi height-lah yang menentukan apakah cacat akan tumbuh tembus dinding. Karena itu height sizing yang akurat bernilai sangat tinggi — dan justru paling sulit dilakukan dengan UT konvensional amplitude-based."},{"heading":"Tip-diffraction (crack tip) technique","body":"Teknik akurat berbasis waktu tempuh: gelombang yang mengenai ujung (tip) cacat planar menghasilkan difraksi yang lemah namun terdeteksi. Dengan memetakan sound path/depth ke tip atas dan tip bawah, height = selisih kedalaman kedua tip. Untuk surface-breaking crack, satu ''tip'' adalah ujung internal (diffracted) dan satu lagi pada permukaan (corner). Tip-diffraction mengukur posisi/waktu, bukan amplitudo, sehingga jauh kurang sensitif terhadap orientasi — akurasi tipikal sekitar +/-1 mm. Membutuhkan operator terlatih karena sinyal tip lemah (sering 20-30 dB di bawah corner/face echo)."},{"heading":"TOFD untuk height sizing","body":"Time-of-Flight Diffraction adalah penerapan sistematis prinsip tip-diffraction dengan sepasang probe (transmitter-receiver) pada PCS (Probe Centre Spacing) tetap. Display D-scan menampilkan lateral wave, backwall echo, dan sinyal difraksi dari tip cacat. Height dihitung dari beda waktu tempuh antar tip (atau tip terhadap lateral wave/backwall). TOFD unggul untuk sizing embedded flaw dan vertical extent, sering dengan akurasi mendekati +/-1 mm, namun punya dead zone di dekat permukaan (di bawah lateral wave) dan di dekat backwall. Sering dipadukan dengan PAUT/pulse-echo untuk menutup zona mati tersebut."},{"heading":"Batas teknik amplitude untuk height","body":"6 dB / 20 dB drop dapat memberi estimasi height untuk reflektor besar, tetapi dengan error besar (orde 2-5 mm) dan cenderung tidak andal untuk crack kecil atau tertutup (tight/closed). Untuk evaluasi FFS yang serius, height sebaiknya diperoleh dengan teknik diffraction (tip echo / TOFD) atau PAUT dengan kalibrasi sizing yang divalidasi. Selalu nyatakan teknik height-sizing di dalam report karena hasil acceptance/FFS sangat sensitif terhadap nilai height."}]}', 500, NULL),
  (4, 'reading', 'Fitness-for-Service — dari sizing ke keputusan', '{"slides":[{"heading":"Workmanship vs Fitness-for-Service","body":"Ada dua filosofi acceptance. Workmanship/quality-based (mis. ASME VIII Div 1, AWS D1.1) menolak cacat yang melebihi ambang tetap tanpa menilai apakah cacat sebenarnya berbahaya — sederhana dan konservatif. Fitness-for-service / engineering critical assessment (API 579-1/ASME FFS-1, BS 7910) menilai apakah cacat dengan dimensi tertentu dapat diterima untuk kondisi operasi aktual (tegangan, suhu, material toughness, fatigue). FFS dapat menerima cacat yang gagal kriteria workmanship bila terbukti aman secara engineering."},{"heading":"Flaw recharacterization untuk FFS","body":"Sebelum analisis, indikasi di-recharacterize menjadi bentuk ideal: surface flaw (a x 2c) atau embedded/subsurface flaw (2a x 2c), dengan cacat dimodelkan sebagai semi-elips/persegi yang membungkusnya. Cacat yang berdekatan harus dievaluasi untuk INTERAKSI — jika spasi antar cacat lebih kecil dari kriteria proximity (aturan spesifik di BS 7910 / API 579 bergantung ukuran dan jenis cacat), keduanya digabung menjadi satu cacat efektif yang lebih besar. Re-karakterisasi ini langsung memakai length dan height hasil sizing UT."},{"heading":"Assessment level dan parameter","body":"API 579 / BS 7910 memakai pendekatan bertingkat (Level 1 konservatif/screening, Level 2 lebih detail dengan FAD, Level 3 analisis lanjut). Input utama: dimensi cacat (a, 2c), tegangan primer + sekunder/residual, fracture toughness (KIC/CTOD/J), yield/tensile strength, dan untuk fatigue: rentang tegangan + jumlah siklus untuk crack growth (mis. Paris law). Output: apakah cacat acceptable, dan jika ya, sisa umur atau interval re-inspeksi. UT menyediakan dimensi; engineer FFS melakukan analisis — Level II UT harus sadar bahwa akurasi sizing-nya menentukan validitas hasil."},{"heading":"Tanggung jawab dan margin","body":"Karena FFS sangat sensitif terhadap height, error sizing harus dilaporkan dan biasanya ditambahkan sebagai margin konservatif (mis. menambahkan ketidakpastian pengukuran ke dimensi cacat). Surface-breaking flaw umumnya jauh lebih kritis daripada embedded flaw dengan dimensi sama karena K-nya lebih tinggi. Operator UT Level II tidak melakukan kalkulasi FFS sendiri kecuali bersertifikat untuk itu, tetapi WAJIB menyediakan data sizing yang akurat, mencantumkan teknik, dan tidak under-size — under-sizing dalam konteks FFS dapat berakibat fatal."}]}', 480, NULL),
  (5, 'reading', 'Menyusun Inspection Report Level II', '{"slides":[{"heading":"Elemen wajib sebuah UT report","body":"Report yang ditandatangani Level II harus traceable dan reproducible. Minimal mencantumkan: identifikasi komponen/weld + datum/titik referensi nol, prosedur & nomor revisi, code/acceptance criteria yang dipakai, peralatan (flaw detector model + S/N, probe freq/size/angle, couplant), blok kalibrasi & reference reflector, kalibrasi range + sensitivity (DAC/TCG/DGS), surface condition & temperatur, scanning coverage, hasil indikasi (lokasi, length, height, depth, teknik sizing), evaluasi accept/reject beserta klausa acuan, serta tanda tangan + level sertifikasi personel + tanggal."},{"heading":"Mencatat indikasi dengan benar","body":"Setiap indikasi yang dilaporkan mencakup: posisi sepanjang weld (diukur dari datum), posisi melintang/depth (through-wall), maximum amplitude relatif terhadap referensi (mis. % DAC atau dB), length + metode (6 dB / max-amp), height + metode (tip / TOFD bila ada), dan klasifikasi (planar/volumetric, surface/embedded). Indikasi geometric (root, counterbore, mismatch) harus dibedakan dari indikasi cacat dan diberi keterangan. Jangan pernah melaporkan accept/reject tanpa menyebut klausa acceptance yang dipakai."},{"heading":"Integritas, etika, dan tanda tangan","body":"Tanda tangan Level II adalah pernyataan profesional bahwa inspeksi dilakukan sesuai prosedur dan hasilnya benar. Jangan menandatangani report untuk pekerjaan yang tidak Anda saksikan/lakukan, jangan mengubah data mentah, dan jangan menyesuaikan sensitivity setelah fakta agar sebuah cacat ''hilang''. Pertahankan data mentah (A-scan capture, encoded data PAUT/TOFD) sesuai masa retensi yang diwajibkan. Diskrepansi dan keterbatasan akses (mis. coverage tidak penuh karena geometri atau akses terbatas) harus dinyatakan eksplisit di report, bukan disembunyikan."}]}', 440, NULL),
  (6, 'quiz', 'Mini-quiz — Reporting & Defect Sizing', '{"description":"Uji pemahaman length sizing (6 dB / 20 dB / max-amp), height sizing dengan teknik diffraction/TOFD, implikasi fitness-for-service (API 579 / BS 7910), dan elemen report Level II.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 10
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 10 mini-quiz (8 questions, step 6)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 6 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Dalam teknik length sizing 6 dB drop, ujung cacat ditandai pada posisi di mana amplitudo turun menjadi berapa dari level referensi?',
   '["Nol (sinyal hilang sepenuhnya)","Separuh tinggi layar (50%, yaitu 6 dB di bawah referensi)","10% tinggi layar (20 dB di bawah referensi)","Dua kali tinggi referensi"]', 1,
   '6 dB drop berarti amplitudo turun separuh (half-amplitude), mis. dari 80% ke 40% FSH; penurunan 6 dB setara faktor 2 dalam amplitudo. Titik ini diasumsikan berada di tepi beam (50% intensitas) terhadap reflektor. Turun ke 10% adalah 20 dB drop, bukan 6 dB.', 'Length Sizing', 'easy'),
  ('Mengapa teknik 6 dB drop cenderung OVER-size cacat yang sangat kecil (lebih kecil dari beam width pada arah scan)?',
   '["Karena cacat kecil selalu memberi amplitudo lebih tinggi dari cacat besar","Karena yang terukur sebenarnya adalah lebar beam, bukan ukuran cacat","Karena couplant menambah panjang sinyal","Karena frekuensi probe terlalu tinggi untuk cacat kecil"]', 1,
   'Bila reflektor lebih kecil dari beam pada arah scan, pergeseran probe yang menyebabkan 6 dB drop mencerminkan profil beam, bukan dimensi cacat. Hasilnya pada dasarnya adalah pengukuran beam width sehingga cacat ter-over-size. Teknik 6 dB drop valid hanya bila reflektor lebih besar dari beam pada arah scan.', 'Length Sizing', 'medium'),
  ('Untuk height (through-wall) sizing yang akurat pada crack planar, teknik mana yang paling tepat dan apa alasannya?',
   '["6 dB drop, karena paling cepat dilakukan","Maximum amplitude, karena selalu mengukur peak tertinggi","Tip-diffraction / TOFD, karena mengukur waktu tempuh ke ujung cacat dan relatif tidak sensitif terhadap orientasi","Backwall echo monitoring, karena memantau total ketebalan dinding"]', 2,
   'Tip-diffraction (termasuk TOFD) mengukur posisi/kedalaman ujung (tip) cacat dari waktu tempuh sinyal difraksi, bukan amplitudo. Karena berbasis waktu, ia jauh kurang sensitif terhadap orientasi reflektor dan memberi akurasi height tipikal sekitar +/-1 mm, jauh lebih baik dari teknik amplitude-based.', 'Height Sizing', 'medium'),
  ('Dalam analisis fitness-for-service (API 579 / BS 7910), parameter dimensi cacat mana yang umumnya paling dominan dalam menentukan crack driving force / stress intensity factor (K)?',
   '["Amplitudo maksimum indikasi dalam % DAC","Sound path total dari exit point ke cacat","Through-wall height/depth (a untuk surface, 2a untuk embedded)","Surface distance probe ke datum"]', 2,
   'Through-wall height (kedalaman a untuk surface flaw, 2a untuk embedded) adalah parameter dominan dalam menghitung stress intensity factor; untuk surface crack K = Y*sigma*akar(pi*a). Inilah sebabnya height sizing yang akurat sangat kritis untuk FFS dan kenapa under-sizing height sangat berbahaya. Amplitudo dan sound path bukan input dimensi FFS.', 'Fitness-for-Service', 'medium'),
  ('Dua cacat berdekatan ditemukan di sepanjang las. Dalam recharacterization untuk FFS, apa yang harus dilakukan bila spasi antar keduanya lebih kecil dari kriteria proximity/interaksi?',
   '["Laporkan hanya cacat yang amplitudonya lebih tinggi","Gabungkan keduanya menjadi satu cacat efektif yang lebih besar","Abaikan keduanya karena medan tegangannya saling membatalkan","Kurangi ukuran masing-masing sebesar spasi di antaranya"]', 1,
   'Aturan proximity/interaksi (BS 7910, API 579) mensyaratkan cacat yang terlalu dekat diperlakukan sebagai satu cacat gabungan yang lebih besar, karena medan tegangan keduanya berinteraksi. Pendekatan ini konservatif dan langsung memakai length + height hasil sizing UT.', 'Fitness-for-Service', 'hard'),
  ('Manakah elemen yang WAJIB ada agar sebuah laporan UT Level II dapat ditelusuri (traceable) dan dipertanggungjawabkan?',
   '["Hanya kesimpulan accept/reject dan tanda tangan","Hanya foto komponen dan tanggal","Hanya nilai amplitudo tertinggi yang ditemukan","Prosedur+revisi, code/acceptance criteria, detail peralatan & kalibrasi (DAC/TCG), teknik sizing, dan tanda tangan + level personel"]', 3,
   'Report yang ditandatangani Level II harus reproducible: prosedur & revisi, acceptance criteria, peralatan (model/S/N, probe, couplant), blok & reference reflector, kalibrasi range + sensitivity, hasil sizing beserta teknik, evaluasi, serta tanda tangan + level sertifikasi dan tanggal. Tanpa elemen ini, hasil tidak dapat diverifikasi ulang.', 'Reporting', 'easy'),
  ('Mengapa amplitudo tinggi TIDAK boleh diasumsikan langsung sebagai cacat besar saat sizing?',
   '["Karena amplitudo selalu dikalibrasi otomatis menjadi ukuran","Karena amplitudo dipengaruhi orientasi reflektor, sifat permukaan, dan posisi dalam beam — bukan hanya ukuran","Karena flaw detector membatasi amplitudo pada 80% FSH","Karena amplitudo hanya bergantung pada frekuensi probe"]', 1,
   'Amplitudo bergantung pada orientasi reflektor terhadap beam, kekasaran/sifat permukaan cacat (tip vs face), dan posisi dalam beam profile — bukan sekadar ukuran. Crack planar yang nyaris sejajar beam bisa memberi sinyal rendah meski besar (poor orientation), sehingga sizing harus berbasis metode (drop dB, tip-diffraction), bukan asumsi amplitudo-ukuran.', 'Sizing Principles', 'medium'),
  ('Untuk cacat multi-faceted (mis. crack bercabang atau slag terputus-putus), teknik length sizing mana yang umumnya paling sesuai?',
   '["6 dB drop tunggal pada peak utama","Backwall drop technique","Maximum amplitude technique (mencatat setiap peak lokal dari tepi ke tepi)","Lateral wave timing pada TOFD"]', 2,
   'Maximum amplitude technique menggeser probe dan mencatat setiap posisi yang memberi peak lokal maksimum; length diukur dari peak pertama ke terakhir. Cocok untuk reflektor multi-faceted karena tiap facet memberi peaknya sendiri, dan cenderung lebih konservatif (length lebih besar) dibanding 6 dB drop. Lateral wave timing adalah fitur TOFD untuk referensi waktu, bukan length sizing facet.', 'Length Sizing', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 6 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 11 — Field Inspection Case Studies (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Case Study 1 — Set-on Nozzle to Shell Weld (ASME VIII / Section V Art. 4)', '{"slides":[{"heading":"Situasi","body":"Pressure vessel SA-516 Gr.70, shell wall 38 mm, nozzle NPS 8 set-on (full penetration) ke shell. Service: hydrocarbon, design temp 200 C. Klien minta UT volumetric per ASME Section VIII Div.1 dengan acceptance ASME Section VIII Div.1 Mandatory Appendix 12 (teknik UT mengikuti Section V Article 4). Geometri nozzle melengkung — counterbore di-grind, tapi sisa root reinforcement bikin akses scan dari sisi nozzle terbatas. Probe shear 45 dan 60 derajat, 2.25 MHz, dipakai untuk cover akar las dan zona fusi dari sisi shell."},{"heading":"Setup & Kalibrasi","body":"DAC dibangun pada basic calibration block per ASME V Article 4. Tebal blok dipilih per T-434.1.4 (block thickness mewakili komponen, umumnya dalam toleransi yang ditetapkan tabel terhadap nominal 38 mm). Reflektor referensi adalah side-drilled hole (SDH). PENTING: per Tabel T-434.2.1, untuk weld thickness >1 in s.d. 2 in (38 mm ~ 1.5 in) diameter SDH yang benar adalah 3.0 mm (1/8 in) — bukan 1.5 mm. Karena permukaan nozzle curved (OD < 500 mm), transfer correction dan curvature correction dievaluasi; gain dinaikkan 4 dB untuk kompensasi attenuasi/coupling pada permukaan lengkung. Reference level (DAC) = 80 persen FSH; recording level 20 persen DAC; evaluation level 50 persen DAC (sesuai prosedur tertulis)."},{"heading":"Temuan A-scan & Sizing","body":"Pada beam 60 derajat dari sisi shell muncul indikasi pada sound path 41 mm, amplitudo 110 persen DAC (di atas reference). Posisi terproyeksi: zona akar pada crotch corner nozzle — area konsentrasi tegangan tinggi. Length sizing dengan teknik 6 dB drop: probe digeser sampai amplitudo turun separuh (drop 6 dB) di kedua ujung; jarak antar titik = 14 mm. Karakter sinyal tajam dengan respon tinggi pada multiple angle menandakan reflektor planar — indikasi lack of fusion / crack pada crotch, bukan slag membulat."},{"heading":"Keputusan Accept/Reject","body":"ASME Section VIII Div.1 Mandatory Appendix 12 (12-3(a)) mereject SEMUA indikasi crack, lack of fusion, atau incomplete penetration tanpa memandang panjang. Selain itu 12-3(b) mereject indikasi yang amplitudonya melebihi reference level DAN panjangnya melebihi: 6 mm untuk t s.d. 19 mm; t/3 untuk t antara 19 mm dan 57 mm; 19 mm untuk t di atas 57 mm. Untuk t=38 mm, batas panjang = t/3 = sekitar 12.7 mm. Di sini amplitudo 110 persen DAC dan panjang 14 mm (>12.7 mm) — reject ganda (planar DAN amplitudo+panjang). Keputusan: REJECT. Tindak lanjut: mark lokasi, dokumentasikan sound path & proyeksi, terbitkan NCR, repair (gouge + re-weld) lalu re-UT 100 persen zona repair plus overlap minimal sesuai prosedur."}]}', 480, NULL),
  (2, 'reading', 'Case Study 2 — T-Joint / Tubular Connection (AWS D1.1)', '{"slides":[{"heading":"Situasi","body":"Sambungan T (web-to-flange) CJP groove weld pada struktur baja A36, tebal flange 25 mm, dynamic / cyclically loaded (jembatan). Kode acuan AWS D1.1 Clause 8 (UT) — pada edisi AWS D1.1:2020 ketentuan UT pindah ke Clause 8 (edisi lama Clause 6). Geometri T-joint menyulitkan akses: scanning dari permukaan flange dan dari web. Probe 70 derajat dipakai untuk tebal tipis-menengah; second leg dipertimbangkan karena akses scan langsung terbatas oleh fillet/reinforcement."},{"heading":"Setup per AWS D1.1","body":"AWS D1.1 memakai sistem rating dB, bukan DAC. Reference level diperoleh dari reflektor standar (SDH) pada IIW/standard block: probe di-peak ke SDH lalu gain diatur sehingga respon = 50 persen FSH; nilai gain itu = reference level (b). Indication level (a) dibaca saat indikasi di-peak ke 50 persen FSH. Attenuation factor (c) = (sound path dalam inci minus 1) x 2, dibulatkan ke dB terdekat. Indication Rating d = a minus b minus c. Tabel 8.2 (cyclically/dynamically loaded) menentukan acceptance berdasar d (dB) versus tebal weld dan posisi indikasi."},{"heading":"Temuan A-scan & Sizing","body":"Probe 70 derajat dari flange menemukan indikasi pada leg pertama, sound path 1.8 inci. Pembacaan: a = 38 dB, b = 45 dB, c = (1.8 minus 1) x 2 = 1.6 dibulatkan 2 dB. Indication Rating d = 38 minus 45 minus 2 = minus 9 dB. Nilai d negatif (indikasi lebih lemah dari reference). Length indikasi dengan 6 dB drop = 8 mm. Posisi indikasi di tengah ketebalan — bukan zona permukaan kritis."},{"heading":"Keputusan Accept/Reject","body":"Untuk weld tebal 25 mm pada beban tarik dinamis, Tabel 8.2 (cyclically loaded) memberi rentang Acceptable untuk indikasi dengan d lebih positif (lebih lemah) dari ambang reject; nilai minus 9 dB jauh di bawah reject threshold zona tersebut dan panjang 8 mm dalam batas izin. Keputusan: ACCEPT. Catatan: AWS membedakan tegas statically vs cyclically loaded — pada beban dinamis ambang lebih ketat (sekitar 4 dB lebih ketat dibanding statik), jadi selalu pakai tabel yang benar sesuai jenis pembebanan; salah tabel bisa meloloskan cacat yang seharusnya ditolak."}]}', 480, NULL),
  (3, 'reading', 'Case Study 3 — Clad Weld & Austenitic / Dissimilar Metal (ASME V Art. 4)', '{"slides":[{"heading":"Situasi","body":"Vessel carbon steel SA-516 di-clad internal dengan stainless 308L (overlay 4 mm) di atas base 32 mm; ada nozzle dissimilar metal weld (DMW) carbon steel ke stainless. Tantangan utama: las/clad austenitic bersifat coarse-grained dan anisotropic sehingga menimbulkan ATENUASI tinggi, hamburan (grain noise) tinggi, dan beam skewing / kecepatan tidak seragam — A-scan konvensional shear wave sulit diinterpretasi pada zona weld austenitic."},{"heading":"Pemilihan Teknik","body":"Untuk material austenitic dipakai probe frekuensi lebih rendah (1 sampai 2 MHz) untuk menurunkan scatter, dan dual-element / TRL (transmit-receive longitudinal) angle beam yang lebih tahan terhadap grain noise dibanding single-crystal shear. PAUT dengan TRL array atau TOFD sering dipilih untuk DMW karena dapat fokus dan mengompensasi beam skew. Verifikasi velocity pada material aktual wajib — jangan asumsikan velocity carbon steel untuk zona stainless karena akan menggeser posisi proyeksi cacat."},{"heading":"Temuan A-scan & Sizing","body":"Pada interface clad-to-base muncul indikasi kontinu beramplitudo sedang sepanjang jalur scan. Pertanyaan kunci: apakah ini disbond (lack of bond clad) atau geometri normal? Interface clad yang baik (well-bonded) memberi reflektor halus dan konsisten; disbond memberi respon planar tajam yang naik saat beam tegak lurus interface. Indikasi di sini naik > 6 dB di atas baseline interface dan menunjukkan length 22 mm via 6 dB drop, disertai loss of back-wall echo lokal — ciri khas lack of bond pada clad overlay."},{"heading":"Keputusan Accept/Reject","body":"Bonding clad dievaluasi terhadap SA-578 / spec pengadaan (acceptance level mendefinisikan ukuran disbond maksimum yang diizinkan, mis. area atau dimensi linear tertentu). Disbond 22 mm dengan back-wall drop melebihi kriteria umum. Untuk DMW butt weld, gunakan teknik Section V Art. 4 + acceptance kode konstruksi (VIII Div.1 App. 12): cacat planar = reject. Keputusan: REJECT disbond clad di lokasi tersebut; spesifikasikan grind-out overlay dan re-clad lokal, lalu re-UT. SME note: SELALU dokumentasikan teknik & velocity kalibrasi untuk material austenitic karena interpretasi sangat bergantung pada asumsi velocity."}]}', 500, NULL),
  (4, 'reading', 'Decision Discipline — Geometry vs Defect, Documentation & FFS Handoff', '{"slides":[{"heading":"Geometri vs Cacat","body":"Banyak indikasi di nozzle, T-joint, dan clad sebenarnya geometric reflector (root reinforcement, counterbore, mismatch/hi-lo, fillet, clad interface). Bedakan dengan: (1) plot sound path & posisi proyeksi pada sketsa weld, (2) cek apakah indikasi bergerak konsisten dengan permukaan saat probe digeser (geometri biasanya stabil dan dapat diprediksi), (3) bandingkan respon pada multiple angle. Indikasi geometri umumnya tidak punya respon tajam tinggi di banyak sudut; cacat planar punya."},{"heading":"Sizing — pilih metode yang tepat","body":"Length sizing standar = 6 dB drop (titik di mana amplitudo turun separuh/6 dB dari peak). Untuk reflektor lebih kecil dari beam width, 6 dB drop dapat overestimate panjang; gunakan teknik maximum amplitude untuk reflektor multi-faceted/kecil. Height / through-wall sizing yang akurat butuh tip diffraction (TOFD) atau PAUT, bukan sekadar amplitude drop. Catat metode sizing di report karena angka panjang/tinggi langsung memengaruhi keputusan code dan input Fitness-for-Service."},{"heading":"Dokumentasi Report Level II","body":"Report minimum: identifikasi prosedur & revisi, equipment & serial, probe (frekuensi/angle/size), couplant, calibration block & reflektor, DAC/TCG atau sistem dB, reference & scanning gain, surface/temperature, sketsa indikasi (lokasi, sound path, proyeksi, panjang, amplitudo persen DAC atau dB rating), interpretasi, kode acceptance + clause, dan keputusan accept/reject. Level II yang sign report bertanggung jawab penuh atas interpretasi."},{"heading":"Handoff ke Fitness-for-Service","body":"Bila cacat tidak lulus acceptance konstruksi tetapi reject dianggap mahal, jalur FFS (API 579-1 / ASME FFS-1) dapat menilai apakah komponen tetap aman beroperasi. FFS butuh dimensi cacat akurat (panjang DAN tinggi through-wall), bukan sekadar amplitudo. Peran Level II: menyediakan data sizing yang dapat dipertahankan; keputusan run/repair/replace FFS dibuat engineer, bukan inspector. Jangan pernah ubah keputusan code reject menjadi accept tanpa disposisi FFS resmi yang terdokumentasi."}]}', 440, NULL),
  (5, 'quiz', 'Practice Exam — Field Inspection Case Studies', '{"description":"Ujian latihan studi kasus: nozzle, T-joint, clad/DMW. Terapkan setup, sizing, dan keputusan accept/reject sesuai ASME V Art.4, ASME VIII Div.1 App.12, dan AWS D1.1 Clause 8.","questionCount":8,"passingScore":75}', 700, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 11
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 11 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada Case Study 1 (set-on nozzle SA-516, shell 38 mm), indikasi di crotch corner memberi amplitudo 110 persen DAC, panjang 14 mm via 6 dB drop, dan respon planar tajam di multiple angle. Per ASME Section VIII Div.1 Mandatory Appendix 12, keputusan yang benar adalah:',
   '["Accept, karena panjang 14 mm masih di bawah t/3","Reject, karena karakter planar mengindikasikan crack/lack of fusion yang ditolak tanpa memandang panjang (12-3(a))","Accept, karena amplitudo di bawah 120 persen DAC","Tunda keputusan sampai dilakukan RT konfirmasi"]', 1,
   'App. 12 paragraf 12-3(a) menolak semua indikasi crack, lack of fusion, dan incomplete penetration tanpa memandang panjang. Respon planar tajam pada multiple angle di crotch corner mengindikasikan cacat planar. Tambahan: per 12-3(b), untuk t=38 mm batas panjang = t/3 = sekitar 12.7 mm, dan 14 mm melebihinya dengan amplitudo > reference, jadi reject ganda. Keputusan: REJECT.', 'Code Interpretation', 'medium'),
  ('Untuk basic calibration block ASME V Article 4 pada weld thickness 38 mm (sekitar 1.5 in), diameter side-drilled hole (SDH) referensi yang benar per Tabel T-434.2.1 adalah:',
   '["1.5 mm (1/16 in)","2.0 mm","3.0 mm (1/8 in)","5.0 mm (3/16 in)"]', 2,
   'Tabel T-434.2.1 mengaitkan diameter SDH dengan rentang weld thickness. Untuk thickness >1 in s.d. 2 in (38 mm masuk band ini) SDH = 1/8 in (3.0 mm). Memakai SDH 1.5 mm akan memberi reference level yang salah dan dapat membuat indikasi tampak lebih besar dari semestinya.', 'Calibration & Sizing', 'hard'),
  ('Dalam sistem rating AWS D1.1 Clause 8 (Case Study 2), Indication Rating (d) dihitung dengan rumus:',
   '["d = a + b + c (indication + reference + attenuation)","d = a - b - c (indication level minus reference level minus attenuation factor)","d = b - a - c (reference minus indication minus attenuation)","d = (a - b) x c"]', 1,
   'AWS D1.1 memakai d = a - b - c, dengan a = indication level (dB), b = reference level (dB), dan c = attenuation factor = (sound path inci - 1) x 2. Nilai d dibandingkan terhadap Tabel 8.2 (cyclic) atau 8.3 (statik) sesuai jenis pembebanan.', 'Calibration & Sizing', 'medium'),
  ('Pada Case Study 2, pembacaan a = 38 dB, b = 45 dB, sound path 1.8 inci. Berapa attenuation factor (c) dan Indication Rating (d)?',
   '["c = 2 dB; d = -9 dB","c = 1.6 dB; d = -8 dB","c = 3 dB; d = -10 dB","c = 2 dB; d = +9 dB"]', 0,
   'c = (1.8 - 1) x 2 = 1.6, dibulatkan ke 2 dB. d = a - b - c = 38 - 45 - 2 = -9 dB. Nilai d negatif berarti indikasi lebih lemah dari reference, umumnya acceptable pada zona ini.', 'Calibration & Sizing', 'hard'),
  ('Mengapa AWS D1.1 mensyaratkan tabel acceptance yang berbeda untuk sambungan statically loaded versus cyclically loaded?',
   '["Beban dinamis (cyclic) lebih rentan fatigue, sehingga ambang reject diperketat (sekitar 4 dB lebih ketat) dibanding beban statik","Beban statik memerlukan probe sudut yang berbeda dari beban dinamis","Hanya beban dinamis yang boleh diperiksa dengan UT; statik harus RT","Tidak ada perbedaan nyata; keduanya memakai threshold yang sama"]', 0,
   'Komponen yang dibebani siklik rentan terhadap fatigue crack growth, jadi AWS D1.1 memberi acceptance threshold yang lebih ketat (mengurangi nilai reject sekitar 4 dB) dibanding beban statik. Memilih tabel yang salah dapat meloloskan cacat yang seharusnya ditolak.', 'Code Interpretation', 'medium'),
  ('Mengapa inspeksi UT pada las/clad austenitic (Case Study 3) jauh lebih sulit dibanding carbon steel?',
   '["Austenitic memiliki velocity yang persis sama dengan carbon steel sehingga tidak perlu rekalibrasi","Struktur coarse-grained dan anisotropic menyebabkan atenuasi tinggi, grain noise tinggi, dan beam skewing/velocity tidak seragam","Austenitic tidak memantulkan gelombang ultrasonik sama sekali","Material austenitic hanya bisa diperiksa dengan gelombang permukaan (surface wave)"]', 1,
   'Las austenitic bersifat coarse-grained dan anisotropic, menimbulkan atenuasi tinggi, hamburan butir (grain noise), serta beam skew dan velocity tidak seragam. Ini menyulitkan interpretasi shear wave konvensional dan menuntut teknik khusus.', 'Material & Technique', 'medium'),
  ('Teknik probe mana yang paling tepat untuk mengurangi grain noise pada inspeksi weld austenitic / dissimilar metal weld?',
   '["Single-crystal shear wave frekuensi tinggi 5 MHz","Probe frekuensi rendah (1-2 MHz) dual-element / TRL (transmit-receive longitudinal)","Normal beam 0 derajat compression wave saja","Probe surface wave (Rayleigh) frekuensi 10 MHz"]', 1,
   'Frekuensi rendah menurunkan scatter pada butir kasar, dan probe TRL dual-element (longitudinal angle beam) lebih tahan terhadap grain noise dibanding single-crystal shear. PAUT TRL atau TOFD juga umum dipakai untuk DMW.', 'Material & Technique', 'hard'),
  ('Seorang Level II menemukan cacat planar yang gagal acceptance konstruksi, tetapi pemilik ingin menghindari repair mahal. Tindakan yang BENAR adalah:',
   '["Mengubah keputusan menjadi accept karena amplitudo hanya sedikit di atas batas","Melakukan penilaian Fitness-for-Service (API 579-1/ASME FFS-1) oleh engineer dengan data sizing panjang DAN tinggi through-wall yang akurat; inspector menyediakan data, engineer membuat keputusan run/repair","Mengurangi reference gain agar indikasi turun di bawah recording level","Mengabaikan cacat karena berada di tengah ketebalan"]', 1,
   'Cacat yang gagal acceptance konstruksi dapat dinilai lewat jalur FFS (API 579-1/ASME FFS-1) yang butuh dimensi akurat termasuk tinggi through-wall. Keputusan run/repair/replace dibuat engineer; Level II menyediakan data sizing yang dapat dipertahankan dan TIDAK boleh mengubah reject menjadi accept tanpa disposisi FFS resmi.', 'Reporting & FFS', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 12 — Operator & Apprentice Training (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Peran Level II sebagai Mentor', '{"slides":[{"heading":"Otoritas mengarahkan Level I","body":"Per SNT-TC-1A, Level I qualified untuk melakukan setup peralatan tertentu, kalibrasi spesifik, scan, dan record indikasi, TETAPI harus bekerja di bawah arahan tertulis (instruksi/prosedur tertulis) dari Level II atau Level III. Sebagai Level II UT Anda menjadi penanggung jawab teknis langsung: menetapkan teknik scan, menyetujui setup kalibrasi yang dipakai trainee, dan memverifikasi semua data sebelum interpretasi final. Level I tidak melakukan evaluasi hasil terhadap acceptance criteria maupun menandatangani report final."},{"heading":"Batas wewenang yang harus dijaga","body":"Garis pemisah yang tegas: Level I boleh mengoperasikan instrument dan mencatat amplitudo/posisi indikasi; Level II yang melakukan evaluasi accept/reject terhadap kode (misal ASME Section V Article 4 untuk teknik + acceptance standard pada kode konstruksi seperti ASME Section VIII Div. 1 Mandatory Appendix 12, atau AWS D1.1) dan menandatangani report. Catatan penting: kode konstruksi-lah yang memuat acceptance criteria; ASME Section V hanya memuat metode/teknik, bukan kriteria terima/tolak. Jika seorang apprentice ''membantu'' menilai indikasi, itu pelanggaran scope. Mentor wajib mendokumentasikan bahwa interpretasi akhir dilakukan oleh personel certified yang berwenang."},{"heading":"Tanggung jawab profesional & etika","body":"Mentor bertanggung jawab atas kualitas data yang dihasilkan trainee dan atas keselamatan kerja. Ini termasuk memastikan trainee tidak men-scan area di luar prosedur, tidak memalsukan data (data falsification adalah pelanggaran serius terhadap kode etik dan Written Practice; per SNT-TC-1A dan CP-189 hal ini dapat membatalkan/menghentikan sertifikasi), dan memahami bahwa setiap report yang ditandatangani Level II adalah pernyataan profesional yang dapat dipertanggungjawabkan secara hukum dan dalam audit klien."}]}', 460, NULL),
  (2, 'reading', 'Struktur Program Training Sesuai SNT-TC-1A', '{"slides":[{"heading":"Training hours formal","body":"SNT-TC-1A merekomendasikan minimum jam training terstruktur (organized training) per method/level. Untuk UT dengan latar high school (tanpa pengalaman college), Level I umumnya butuh 40 jam dan Level II 40 jam tambahan training formal, sehingga total kumulatif menuju Level II adalah 80 jam. Angka ini adalah recommended minimum; employer dapat menetapkan lebih tinggi dalam Written Practice mereka. Mentor harus tahu bahwa Written Practice perusahaan, bukan ingatan, yang menjadi acuan resmi."},{"heading":"Experience hours (OJT)","body":"Selain training, dibutuhkan experience hours pada method tersebut. SNT-TC-1A (Tabel 6.3.1A) merekomendasikan untuk UT: Level I minimum 210 jam dan Level II minimum 630 jam KUMULATIF pada method (artinya 420 jam tambahan setelah Level I), masing-masing dengan minimum kalender beberapa bulan. PENTING: angka 630 jam adalah total kumulatif ke Level II, bukan tambahan di atas 840 jam — verifikasi tepat pada edisi/tabel yang diadopsi. Experience harus diperoleh di bawah supervisi personel certified dan didokumentasikan (tanggal, method, jam, supervisor). Mentor sering bertugas memvalidasi log OJT ini sebelum diserahkan ke Level III untuk certification."},{"heading":"Body of knowledge & outline pelatihan","body":"Training harus mengikuti topical outline. ASNT CP-105 menyediakan topical outline/body of knowledge yang menjadi basis materi: untuk UT mencakup physical principles, equipment, calibration, evaluation/interpretation, dan code/spec/procedure. Sebagai mentor, susun silabus OJT yang memetakan setiap topik CP-105 ke aktivitas praktek nyata (mis. ''DAC construction'' dipetakan ke sesi pada block dengan side-drilled holes)."},{"heading":"Vision & examination requirements","body":"Sebelum certification, trainee harus lulus near-vision (Jaeger No. 1 pada jarak tidak kurang dari 12 inci atau setara, dengan/tanpa koreksi) dan color contrast/shade-of-gray differentiation; near-vision di-test tahunan. Selain itu butuh lulus General, Specific, dan Practical examination dengan minimum 70% tiap bagian dan composite (rata-rata terbobot dari ketiganya) minimum 80% per SNT-TC-1A. Mentor membantu menyiapkan trainee untuk Practical, yang menguji setup riil dan deteksi/sizing pada spesimen."}]}', 500, NULL),
  (3, 'reading', 'On-the-Job Training & Teknik Mentoring', '{"slides":[{"heading":"Progresi ''I do, we do, you do''","body":"Mentoring UT efektif mengikuti progresi bertahap: mentor mendemonstrasikan (mis. membuat DAC pada block dengan side-drilled hole), lalu mentor dan trainee mengerjakan bersama, lalu trainee mandiri sementara mentor mengobservasi. Mulai dari fundamental yang sering jadi sumber error: couplant consistency, probe pressure stabil, dan zero/velocity calibration pada block IIW (V1) sebelum maju ke angle beam dan flaw sizing."},{"heading":"Kesalahan umum yang harus dikoreksi","body":"Mentor harus aktif menangkap error klasik trainee: salah set reference level sehingga DAC/kalibrasi tidak valid, lupa transfer correction antara block dan part (perbedaan kekasaran/curvature/attenuation), salah baca beam index point (BIP) atau actual refracted angle pada V1 sehingga depth/soundpath salah, dan mengabaikan kemungkinan mode conversion atau geometric reflector pada geometri tebal. Setiap koreksi sebaiknya dijelaskan ''mengapa'', bukan hanya ''perbaiki'', agar trainee membangun model mental."},{"heading":"Mengajarkan sizing dengan disiplin","body":"Length sizing 6 dB drop dan height estimation rawan inkonsistensi antar operator. Mentor menstandarkan teknik: definisikan reference echo (amplitudo maksimum indikasi), jaga gain konstan, gerakkan probe sampai echo turun 6 dB (setengah/50% amplitudo) untuk menandai tiap ujung indikasi. Tekankan keterbatasannya: 6 dB drop andal untuk reflektor yang lebih besar dari lebar beam; untuk reflektor kecil hasilnya bisa overestimate. Latih trainee mengulang pengukuran untuk repeatability dan bandingkan hasil mereka dengan pengukuran mentor sebagai kalibrasi ''human factor''."},{"heading":"Supervisi terdokumentasi vs hands-off","body":"Selama OJT, Level I bekerja di bawah supervisi; mentor menetapkan tingkat supervisi sesuai kompleksitas (direct supervision untuk task kritikal, periodic untuk task rutin yang sudah dikuasai). Yang penting: jam OJT hanya valid sebagai experience jika diperoleh saat trainee benar-benar mengerjakan NDT pada method tersebut di bawah personel certified, dan tercatat — bukan sekadar ''menemani'' atau menonton."}]}', 480, NULL),
  (4, 'reading', 'Dokumentasi Training & Qualification Records', '{"slides":[{"heading":"Record yang wajib dipelihara","body":"SNT-TC-1A mensyaratkan employer memelihara record kualifikasi tiap personel: bukti training (course, jam, tanggal, instruktur), log experience/OJT, hasil ujian (General/Specific/Practical + composite score), hasil vision test tahunan, dan sertifikat yang ditandatangani oleh Level III (atau pejabat yang ditunjuk sesuai Written Practice). Record harus dapat di-audit klien atau badan akreditasi kapan saja; ketidaklengkapan dapat menyebabkan personel dianggap tidak certified."},{"heading":"OJT log yang benar","body":"Log OJT yang baik mencatat per entri: tanggal, method (UT), jenis pekerjaan/part, jam aktual, nama dan tanda tangan supervisor certified, serta level supervisi. Hindari ''jam bulat tanpa rincian''. Sebagai mentor Anda menandatangani validasi ini, sehingga akurasinya menjadi tanggung jawab profesional Anda — jangan tanda tangani jam yang tidak Anda saksikan."},{"heading":"Written Practice sebagai dokumen induk","body":"Written Practice adalah dokumen tertulis employer yang menetapkan kontrol detail untuk training, examination, dan certification personel, dan harus konsisten dengan SNT-TC-1A (yang bersifat recommended practice — menjadi mengikat hanya bila diadopsi melalui kontrak/Written Practice). Mentor harus selalu merujuk Written Practice perusahaan untuk angka jam, syarat ujian, dan interval recertification — bukan asumsi pribadi."},{"heading":"Recertification & continuing competency","body":"Sertifikasi tidak permanen: per SNT-TC-1A recertification umumnya tiap 5 tahun untuk Level I/II (interval ditetapkan dalam Written Practice), berdasarkan bukti continued satisfactory performance dan/atau re-examination, ditambah vision test tahunan. Mentor membantu menjaga trainee tetap current: mencatat continuing experience, memastikan tidak ada interruption signifikan (gap praktek method yang panjang dapat memicu re-evaluation sesuai Written Practice), dan menyiapkan dokumentasi untuk siklus recert berikutnya."}]}', 470, NULL),
  (5, 'quiz', 'Mini-quiz — Operator & Apprentice Training', '{"description":"Konfirmasi pemahaman peran mentor Level II, persyaratan training/experience SNT-TC-1A, supervisi OJT, dan dokumentasi qualification records.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 12
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 12 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 12 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Menurut SNT-TC-1A, apa batas wewenang seorang Level I UT ketika bekerja di bawah mentor Level II?',
   '["Boleh melakukan setup, kalibrasi spesifik, scan, dan record indikasi di bawah arahan tertulis, tetapi tidak melakukan evaluasi accept/reject terhadap kode maupun menandatangani report final","Boleh melakukan seluruh proses termasuk evaluasi accept/reject selama disaksikan Level II","Hanya boleh mengamati dan tidak boleh menyentuh instrument sama sekali","Boleh menandatangani report final selama Level II melakukan counter-sign"]', 0,
   'Level I qualified untuk setup, kalibrasi spesifik, scan, dan record indikasi di bawah arahan tertulis Level II/III, namun evaluasi accept/reject terhadap acceptance criteria dan penandatanganan report final adalah wewenang Level II/III. Trainee yang menilai indikasi atau menandatangani report final adalah pelanggaran scope.', 'Mentoring & Scope', 'easy'),
  ('Untuk kandidat UT dengan latar high school tanpa pengalaman college, berapa total jam training formal kumulatif yang direkomendasikan SNT-TC-1A untuk mencapai Level II?',
   '["40 jam total (20 jam Level I + 20 jam Level II)","80 jam total (40 jam Level I + 40 jam Level II tambahan)","210 jam total","120 jam total (60 + 60)"]', 1,
   'SNT-TC-1A merekomendasikan UT Level I 40 jam dan Level II 40 jam tambahan organized training, sehingga total kumulatif 80 jam. Ini recommended minimum; Written Practice employer dapat menetapkan lebih tinggi dan menjadi acuan resmi.', 'Training Requirements', 'medium'),
  ('Sebuah entri OJT log mencatat ''8 jam UT'' tanpa detail lain. Sebagai mentor Level II yang diminta menandatangani validasi, sikap yang benar adalah:',
   '["Menandatangani karena total jam sudah benar","Menandatangani tetapi memberi catatan agar diperbaiki nanti","Menolak/menahan tanda tangan sampai entri mencantumkan tanggal, jenis part/pekerjaan, jam aktual, dan level supervisi yang benar-benar Anda saksikan","Meminta Level I sendiri yang menandatangani validasi tersebut"]', 2,
   'Validasi OJT adalah pernyataan profesional. Log harus mencatat tanggal, method, jenis pekerjaan, jam aktual, dan supervisi. Mentor tidak boleh menandatangani jam yang tidak disaksikan; jam tanpa rincian tidak valid sebagai experience yang dapat diaudit.', 'Training Documentation', 'medium'),
  ('Berapa minimum experience hours pada method UT yang direkomendasikan SNT-TC-1A (Tabel 6.3.1A) sebagai total KUMULATIF untuk mencapai Level II?',
   '["210 jam","420 jam","630 jam","840 jam"]', 2,
   'SNT-TC-1A merekomendasikan UT Level I minimum 210 jam experience, dan Level II minimum 630 jam KUMULATIF pada method (artinya 420 jam tambahan di atas Level I). Angka 630 adalah total kumulatif, bukan tambahan yang menghasilkan 840. Experience harus diperoleh di bawah supervisi personel certified dan terdokumentasi.', 'Training Requirements', 'hard'),
  ('Saat mengajarkan length sizing dengan teknik 6 dB drop kepada apprentice, instruksi mana yang benar?',
   '["Naikkan gain sebesar 6 dB lalu tandai ujung indikasi di posisi probe baru","Jaga gain konstan, gerakkan probe dari posisi amplitudo maksimum (referensi) sampai echo turun menjadi setengah amplitudo (turun 6 dB) untuk menandai tiap ujung indikasi","Tandai ujung indikasi saat echo hilang total dari layar","Turunkan reference level sampai indikasi tepat menyentuh FSH"]', 1,
   'Teknik 6 dB drop: pada gain konstan, ujung indikasi ditandai saat echo turun 6 dB (50% / setengah amplitudo) dari nilai maksimum referensi. Mengubah gain saat pengukuran akan merusak metode dan menghasilkan length yang salah. Teknik ini paling andal untuk reflektor yang lebih besar dari lebar beam.', 'Mentoring & Sizing', 'medium'),
  ('Manakah dokumen yang menjadi acuan RESMI bagi mentor untuk angka jam training, syarat ujian, dan interval recertification di sebuah perusahaan?',
   '["SNT-TC-1A langsung, karena bersifat mandatory standard","Written Practice employer, yang dibuat konsisten dengan SNT-TC-1A (recommended practice)","Sertifikat pribadi Level III mentor","ASTM E709 sebagai standar wajib certification UT"]', 1,
   'SNT-TC-1A adalah recommended practice, bukan standar wajib kecuali diadopsi melalui kontrak/Written Practice. Setiap employer membuat Written Practice tertulis (konsisten dengan SNT-TC-1A) yang menjadi dokumen induk untuk kontrol training, examination, dan certification personel. (Catatan: ASTM E709 adalah panduan MT, bukan UT.)', 'Training Documentation', 'medium'),
  ('Untuk lulus kualifikasi tertulis Level II per SNT-TC-1A, skor minimum yang benar adalah:',
   '["Minimum 70% pada tiap bagian (General/Specific/Practical) dan composite minimum 80%","Minimum 80% pada tiap bagian tanpa composite","Minimum 60% composite saja","Minimum 90% pada Practical dan 50% pada General"]', 0,
   'SNT-TC-1A merekomendasikan minimum 70% pada masing-masing examination (General, Specific, Practical) dengan composite grade (rata-rata terbobot) minimum 80%. Ditambah syarat lulus near-vision (Jaeger No.1 / setara, tidak kurang dari 12 in) dan color/shade-of-gray contrast yang di-test tahunan.', 'Training Requirements', 'hard'),
  ('Seorang apprentice di lapangan mulai menilai indikasi sebagai ''reject'' dan mengisi kolom evaluasi di report. Tindakan mentor yang paling tepat adalah:',
   '["Membiarkannya sebagai latihan dan mengoreksi nanti di kantor","Menghentikan praktik tersebut, menjelaskan bahwa evaluasi accept/reject dan pengisian report final adalah wewenang Level II/III, dan memastikan interpretasi final dilakukan/ditandatangani personel certified yang berwenang","Meminta apprentice menandatangani report karena dia yang melakukan scan","Menerima evaluasi apprentice jika kebetulan sesuai pendapat mentor"]', 1,
   'Evaluasi terhadap acceptance criteria dan penandatanganan report final adalah wewenang Level II/III. Membiarkan Level I melakukan evaluasi adalah pelanggaran scope dan berisiko data falsification. Mentor wajib menghentikannya dan memastikan interpretasi final oleh personel berwenang.', 'Mentoring & Scope', 'easy')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 12 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 13 (4 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Recap A — Fisika, Teknik Lanjut & Karakterisasi (Modul 1-5)', '{"slides":[{"heading":"Scope Level II & dasar fisika gelombang","body":"Level II authorized untuk kalibrasi, evaluasi, sizing, dan men-sign report (Level I hanya setup-scan-record di bawah supervisi). Fondasi fisika yang harus melekat: empat mode gelombang — longitudinal (Vl ~5900 m/s di baja), shear (Vs ~3230 m/s, ~0.55 Vl), Rayleigh/surface (~0.9 Vs, penetrasi efektif ~1 wavelength), dan Lamb/guided (dispersif, bergantung produk f-d). Shear hanya merambat di solid karena butuh shear modulus > 0 — dasar immersion (di air hanya longitudinal). Wavelength lambda = V/f: pada f sama, shear berwavelength lebih pendek (~0.55x) sehingga resolusi/sensitivitas terhadap reflektor kecil lebih baik untuk inspeksi weld."},{"heading":"Mode conversion & critical angle","body":"Snell''s Law: sin(theta1)/V1 = sin(theta2)/V2. Satu gelombang datang miring bisa menghasilkan refracted longitudinal dan shear sekaligus. First critical angle = refracted longitudinal mencapai 90 derajat (hanya shear tersisa di benda uji); second critical angle = refracted shear mencapai 90 derajat dan membangkitkan surface wave. Probe angle-beam shear standar (45/60/70) sengaja bekerja di ANTARA kedua critical angle agar hanya shear murni masuk. Untuk antarmuka air-baja (immersion): first critical ~14.5 derajat (sin = 1480/5900), second ~27 derajat (sin = 1480/3230). Mode conversion juga menciptakan echo palsu (corner trap, mode-converted) yang harus dikenali Level II."},{"heading":"Teknik lanjut: PAUT & TOFD","body":"PAUT memakai array element yang di-fire dengan delay terkontrol untuk steer/focus beam secara elektronik; sectorial (S-)scan menampilkan multi-angle dalam satu sweep. Tiap angle = focal law berbeda, butuh ACG (angle-corrected gain) agar sensitivitas rata. TOFD memakai dua probe pitch-catch (longitudinal, PCS tetap, perpotongan beam ~2/3 ketebalan) dan mengukur energi DIFFRAKSI dari TIP cacat, bukan amplitudo pantulan — relatif tak sensitif orientasi, height sizing akurat (orde ~+/-1 mm) karena berbasis WAKTU tempuh. A-scan TOFD: lateral wave (pertama), tip signals, backwall (terakhir); upper & lower tip berlawanan fase (180 derajat). Kelemahan TOFD: dead zone lateral wave di near-surface, sehingga dipadu PAUT/pulse-echo."},{"heading":"Karakterisasi & length sizing 6 dB drop","body":"Karakterisasi membedakan planar (crack/LOF/IP — memantul specular, sangat sensitif sudut, crack-like dan kritis) dari volumetric (porosity/slag — menyebar, amplitudo relatif stabil dari berbagai arah). Echo dynamics (perubahan envelope saat probe digeser) adalah alat diskriminasi utama. Length sizing 6 dB drop: 20*log10(0.5) = -6 dB = amplitudo turun separuh; geser probe ke kedua arah sampai turun 6 dB dari puncak, jarak antar penanda = panjang cacat. Valid hanya bila reflektor LEBIH BESAR dari beam width; reflektor kecil di-overestimate (gunakan 20 dB drop atau maximum amplitude). Crack umumnya rejectable tanpa memandang panjang pada banyak code kritis."}]}', 500, NULL),
  (2, 'reading', 'Recap B — Kalibrasi, Immersion, Prosedur & Plotting (Modul 6-8)', '{"slides":[{"heading":"Koreksi amplitude: DAC, TCG, DGS","body":"Reflektor identik pada kedalaman berbeda memberi amplitudo berbeda karena atenuasi + beam spread. Laju penurunan far-field bergantung bentuk reflektor: back-wall planar besar ~1/jarak, FBH disc kecil ~1/jarak^2, SDH silindris ~1/jarak^1.5. Near field N = D^2/(4*lambda) intensitasnya berfluktuasi (maxima/minima) sehingga titik kalibrasi diambil di far field. DAC = gain tetap, kurva acuan menurun mengikuti puncak echo; TCG = swept gain sehingga reflektor identik tampil sama tinggi (kurva datar) — praktis wajib untuk PAUT/automated tapi menaikkan noise di jarak jauh. DGS/AVG = kurva ternormalisasi per probe, cukup satu reflektor referensi, hasil dinyatakan sebagai ERS (Equivalent Reflector Size). Transfer correction mengoreksi beda surface/atenuasi block vs part (>2 dB umumnya wajib dikoreksi)."},{"heading":"Verifikasi kalibrasi & 100% DAC","body":"100% DAC = reference level, BUKAN otomatis reject. ASME V Art. 4 (teknik amplitude lama, mis. Appendix yang berbasis DAC): indikasi di atas recording level dievaluasi, reject mengikuti referencing/construction code (mis. ASME VIII). AWS D1.1 memakai Indication Rating d = a - b - c (dB). Calibration check tipikal: awal & akhir pemeriksaan, ganti operator/equipment, tiap maksimum ~4 jam, dan saat parameter berubah. Jika sensitivitas turun >20% (~2 dB), recalibrate dan scan ulang seluruh area sejak kalibrasi valid terakhir. Jika titik sweep/range bergeser >10% sweep division, recalibrate dan re-record indikasi terdampak."},{"heading":"Immersion testing","body":"Probe & part direndam; air = couplant kontinu tanpa kontak fisik (hilangkan wear & variasi tekanan kopling). Water path = delay sebelum front surface echo (FSE), diatur agar gema-ulang water path tidak tumpang-tindih dengan echo material; gate flaw diset SETELAH FSE (sering pakai interface triggering). Normal incidence (0 derajat) -> longitudinal (laminasi/tebal); miring di atas first critical air-baja (~14.5 derajat) -> hanya shear (weld/flaw). Air harus di-degass (gelembung = dropout sinyal/false call). Kalibrasi immersion straight-beam umumnya pakai FBH block (ASTM E127/E428, area-amplitude & distance-amplitude); keluaran khas = C-scan ter-encode. Spesifikasi aerospace mis. AMS-STD-2154."},{"heading":"Procedure development & plotting","body":"Written procedure menetapkan RANGE parameter yang diizinkan; technique sheet/scan plan memilih nilai spesifik dalam range itu dan tak boleh keluar batas. ASME V Art. 4 Table T-421 memisah essential vs nonessential variable: perubahan essential (frekuensi, sudut, thickness range, probe/search unit, calibration block, metode kalibrasi) di luar range mewajibkan requalification; nonessential cukup dicatat. Level II menyusun/review procedure; approval/qualification akhir = Level III. Plotting angle-beam (sudut diukur dari normal): depth 1st leg = S*cos(theta), surface distance = S*sin(theta); pada 2nd leg depth = 2t - S*cos(theta). Indikasi berdekatan digabung sesuai aturan kombinasi (proximity) code sebelum dievaluasi."}]}', 500, NULL),
  (3, 'reading', 'Recap C — Code, Sizing/Reporting, Studi Kasus & Mentoring (Modul 9-12) + strategi ujian', '{"slides":[{"heading":"Code interpretation — ASME, AWS, API","body":"ASME V = BAGAIMANA memeriksa (Article 4 untuk UT weld, plus Mandatory Appendix III untuk TOFD, Appendix lain untuk PAUT/encoded). Acceptance ada di referencing/construction code: ASME VIII Div.1/Div.2 untuk bejana tekan (Div.2 mengizinkan acceptance berbasis flaw sizing/fracture mechanics). AWS D1.1 untuk struktur baja las (acceptance UT berbasis Indication Rating, kriteria berbeda untuk statically vs cyclically loaded). API 1104 untuk pipeline (Annex A opsional: acceptance berbasis Engineering Critical Assessment/ECA). API 510 (vessel), 570 (piping), 653 (tank) untuk in-service inspection. Level II wajib memakai EDISI code yang benar — nomor tabel/pasal acceptance dapat berubah antar edisi."},{"heading":"Defect sizing & reporting","body":"Length sizing: 6 dB drop (reflektor besar specular) atau maximum amplitude (cluster/reflektor kecil). Height/through-wall sizing: TOFD (orde ~+/-1 mm) atau tip-diffraction/teknik amplitude-drop — input kunci untuk fitness-for-service (FFS) per API 579-1/ASME FFS-1 dan ECA (BS 7910). Report valid wajib memuat: prosedur & code/edisi, equipment & probe (frekuensi, sudut, S/N), calibration block & reference level (mis. SDH / DAC), metode sizing yang dipakai, data tiap indikasi (lokasi, panjang, kedalaman/depth, amplitudo, klasifikasi), keputusan accept/reject vs criteria, dan tanda tangan inspector bersertifikat. Tanpa metode sizing & reference level, hasil tak dapat diaudit/direproduksi."},{"heading":"Studi kasus lapangan & mentoring","body":"Geometri kompleks butuh teknik khusus: nozzle/set-on weld (akses & kurvatur ganda), T-joint/corner (mode conversion & corner trap), clad/dissimilar metal weld (atenuasi & scatter tinggi pada austenitic/clad sehingga sering butuh frekuensi lebih rendah, probe dual-element/TRL, atau PAUT dengan focal law dioptimasi). Selalu verifikasi indikasi geometri vs cacat dengan multi-angle, leg berbeda, dan pencocokan ke weld map/profil. Mentoring: Level II dapat mengarahkan & memverifikasi pekerjaan Level I dan mendokumentasikan on-the-job training (OJT), tetapi sertifikasi & tanggung jawab kualifikasi personel mengikuti written practice (SNT-TC-1A) atau ISO 9712."},{"heading":"Strategi practice exam","body":"Practice exam 30 soal ini menarik dari SELURUH silabus UT-L2: fisika & mode conversion, PAUT, TOFD, karakterisasi & 6 dB drop, kalibrasi (DAC/TCG/DGS) & verifikasi, immersion, procedure development & essential variables, plotting trigonometri, code (ASME/AWS/API) & acceptance, sizing/reporting, dan studi kasus. Tips: baca pertanyaan numerik (plotting, near field, critical angle, dB) dengan teliti — sudut diukur dari normal; -6 dB = setengah amplitudo (-20 dB = 10%); cek SATUAN. Untuk soal code, perhatikan kata kunci ''reference vs reject'' dan ''essential variable''. Pass minimal 75%; setelah selesai tinjau setiap explanation sebelum lanjut ke Final Assessment (Modul 14)."}]}', 460, NULL),
  (4, 'quiz', 'Practice Exam — UT Level II (30 soal komprehensif)', '{"description":"Practice exam komprehensif 30 soal yang menarik dari seluruh silabus UT-L2 (Modul 1-12): fisika & mode conversion, PAUT, TOFD, karakterisasi & sizing, kalibrasi DAC/TCG/DGS, immersion, procedure development, plotting, code interpretation (ASME/AWS/API), reporting, dan studi kasus. Pemanasan menuju Final Assessment.","questionCount":30,"passingScore":75}', 720, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 13
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 13 mini-quiz (30 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 13 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Wewenang utama yang dimiliki UT Level II tetapi TIDAK dimiliki Level I adalah...',
   '["Mengoleskan couplant ke permukaan","Mengevaluasi indikasi, melakukan sizing, dan menandatangani (sign) report inspeksi","Memindahkan probe selama scanning","Membersihkan permukaan sebelum inspeksi"]', 1,
   'Level I melakukan setup, scan, dan record di bawah supervisi. Level II authorized untuk kalibrasi, evaluasi indikasi, sizing, dan sign-off report final. Tugas mekanis (couplant, gerak probe, pembersihan) dapat dilakukan kedua level.', 'Scope Level II', 'easy'),
  ('Pada baja karbon, rasio kecepatan gelombang shear terhadap longitudinal (Vs/Vl) kira-kira sebesar...',
   '["0.25","0.55","0.90","1.80"]', 1,
   'Vs ~3230 m/s dan Vl ~5900 m/s di baja, sehingga Vs/Vl ~ 0.55. Nilai ~0.9 adalah rasio Rayleigh terhadap shear, bukan shear terhadap longitudinal.', 'Wave Physics', 'easy'),
  ('First critical angle didefinisikan sebagai sudut datang di mana...',
   '["Refracted shear wave mencapai 90 derajat dan menjadi surface wave","Refracted longitudinal wave mencapai 90 derajat sehingga hanya shear tersisa di benda uji","Seluruh energi dipantulkan total kembali ke wedge","Surface wave berubah menjadi bulk longitudinal wave"]', 1,
   'Pada first critical angle refracted longitudinal mencapai 90 derajat dan hilang, menyisakan hanya shear di benda uji. Refracted shear mencapai 90 derajat (membangkitkan surface wave) pada second critical angle.', 'Mode Conversion', 'medium'),
  ('Mengapa gelombang shear tidak dapat merambat di dalam air pada immersion testing?',
   '["Karena air menyerap seluruh energi shear menjadi panas","Karena frekuensi shear terlalu tinggi untuk air","Karena air (fluida) tidak mendukung gaya geser — shear modulus = 0","Karena wavelength shear menjadi nol di dalam air"]', 2,
   'Gelombang shear membutuhkan medium dengan shear modulus > 0. Cairan dan gas tidak memilikinya, sehingga hanya longitudinal yang merambat di air. Inilah dasar mode conversion saat beam masuk ke benda uji solid.', 'Wave Modes', 'medium'),
  ('Karakteristik utama Lamb (guided) wave yang membuat setup-nya kompleks adalah...',
   '["Bersifat dispersif — kecepatan tiap mode bergantung pada produk frekuensi x ketebalan (f-d)","Hanya dapat dibangkitkan pada material yang sangat tebal","Tidak pernah mengalami atenuasi","Selalu menjalar tegak lurus terhadap permukaan pelat"]', 0,
   'Lamb wave bersifat dispersif: kecepatan fase/grup mode S0/A0 dst bergantung pada f-d product, sehingga butuh dispersion curve untuk memilih titik kerja stabil dan mode tunggal. Lamb justru dipakai pada material TIPIS (pelat/tube), bukan tebal.', 'Lamb Waves', 'medium'),
  ('Pada PAUT, satu set parameter (angle, focal depth, subset element + delay) yang menentukan satu beam pattern disebut...',
   '["Gate","Focal law","Couplant index","Backwall echo"]', 1,
   'Focal law adalah set delay/parameter yang menghasilkan satu beam pattern tertentu. Setiap angle pada sectorial scan = focal law berbeda, masing-masing dapat butuh koreksi gain (ACG) sendiri.', 'PAUT', 'easy'),
  ('Pada PAUT sectorial (S-)scan, mengapa diperlukan Angle-Corrected Gain (ACG)?',
   '["Untuk menaikkan PRF agar scan lebih cepat","Karena tiap angle/focal law menempuh metal-path & beam spread berbeda sehingga sensitivitasnya berbeda — respons referensi perlu diratakan di seluruh sweep","Untuk mengubah frekuensi probe secara otomatis","Karena couplant berbeda untuk tiap angle"]', 1,
   'Tiap angle pada S-scan punya metal-path dan sensitivitas berbeda. ACG mengkalibrasi sensitivitas pada beberapa angle terhadap SDH referensi agar respons rata di seluruh rentang sweep; tanpa ACG, angle ekstrem under-/over-amplified dan sizing keliru.', 'PAUT', 'hard'),
  ('Dasar deteksi cacat pada teknik TOFD adalah...',
   '["Amplitudo pantulan specular dari permukaan cacat","Energi yang ter-diffraksi dari ujung (tip) cacat","Perubahan medan magnet di sekitar cacat","Atenuasi total beam yang melewati material"]', 1,
   'TOFD mengandalkan energi diffraksi dari TIP cacat (tip bertindak sebagai sumber titik Huygens), bukan amplitudo pantulan permukaan. Inilah yang membuatnya relatif tidak sensitif orientasi cacat dan akurat untuk height/through-wall sizing.', 'TOFD', 'easy'),
  ('Pada A-scan TOFD, urutan kedatangan sinyal dari paling awal ke paling akhir yang benar adalah...',
   '["Backwall echo, lalu tip cacat, lalu lateral wave","Tip cacat, lalu lateral wave, lalu backwall echo","Lateral wave, lalu sinyal tip cacat, lalu backwall echo","Lateral wave, lalu backwall echo, lalu tip cacat"]', 2,
   'Lateral wave tiba pertama (merambat tepat di bawah permukaan scan, jalur terpendek), sinyal diffraksi tip cacat di antaranya, dan backwall echo terakhir (jalur terpanjang). Posisi sinyal cacat menentukan kedalamannya.', 'TOFD', 'medium'),
  ('Untuk single-zone TOFD, PCS (Probe Centre Spacing) biasanya diatur agar perpotongan sumbu kedua beam berada pada kedalaman sekitar...',
   '["0% ketebalan (tepat di permukaan scan)","1/3 ketebalan","2/3 ketebalan","100% ketebalan (tepat di backwall)"]', 2,
   'PCS diset agar intersection beam berada di sekitar 2/3 ketebalan (two-thirds depth), titik dengan coverage dan sensitivitas paling merata. PCS terlalu kecil memperbesar dead zone permukaan; terlalu lebar melemahkan sinyal bagian dalam.', 'TOFD', 'medium'),
  ('Keterbatasan utama TOFD yang membuatnya sering dipadu dengan pulse-echo atau PAUT adalah...',
   '["Tidak dapat mengukur length cacat sama sekali","Dead zone dekat permukaan scan akibat lebar pulse lateral wave","Hanya bekerja pada material non-logam","Tidak bisa mendeteksi cacat planar"]', 1,
   'Lateral wave yang lebar menciptakan dead zone near-surface yang dapat menyembunyikan cacat dangkal. Karena itu TOFD dipadu pulse-echo/PAUT untuk near-surface coverage, atau dipakai frekuensi lebih tinggi/pulse lebih pendek. TOFD justru sangat baik untuk planar/height.', 'TOFD', 'medium'),
  ('Pada teknik 6 dB drop, batas panjang cacat ditandai ketika amplitudo turun menjadi berapa persen dari nilai maksimum?',
   '["10%","25%","50%","70%"]', 2,
   '20*log10(0.5) = -6.02 dB, yaitu amplitudo turun menjadi setengah (50%) dari puncak. Probe digeser ke kedua arah sampai turun 6 dB; jarak antar penanda = panjang cacat. Nilai 10% berhubungan dengan 20 dB drop.', 'Defect Sizing', 'easy'),
  ('Teknik 6 dB drop memberikan hasil length sizing paling akurat untuk...',
   '["Reflektor besar dan specular yang lebih besar dari beam width","Reflektor titik (point reflector) seperti SDH kecil","Cluster porosity yang tersebar acak","Reflektor yang jauh lebih kecil dari beam width"]', 0,
   '6 dB drop akurat bila reflektor lebih besar dari beam width dan memantul specular (mis. LOF memanjang/crack besar). Untuk reflektor lebih kecil dari beam width hasilnya overestimate (mendekati beam width); cluster porosity memakai maximum amplitude technique.', 'Defect Sizing', 'medium'),
  ('Ciri echo dynamics yang paling mengindikasikan cacat PLANAR (crack/lack of fusion) adalah...',
   '["Amplitudo konstan tanpa perubahan dari segala sudut probe","Banyak puncak kecil yang stabil dari semua arah","Amplitudo tinggi dan tajam yang sangat sensitif terhadap sudut beam","Sinyal lemah merata tanpa puncak dominan"]', 2,
   'Cacat planar memantul specular sehingga amplitudonya tinggi-tajam dan turun drastis bila beam tidak tegak lurus bidang cacat (sangat sensitif sudut). Banyak puncak stabil dari segala arah justru mencirikan volumetric (porosity/slag).', 'Defect Characterization', 'medium'),
  ('Sebuah indikasi ditemukan pada sound path 40 mm dengan probe sudut 60 derajat pada 1st leg. Berapa kira-kira depth (kedalaman) cacat?',
   '["20 mm","35 mm","40 mm","69 mm"]', 0,
   'Sudut diukur dari normal, maka depth 1st leg = S*cos(theta) = 40*cos(60) = 40*0.5 = 20 mm. Nilai ~35 mm adalah surface distance (S*sin 60 ~ 34.6 mm), bukan kedalaman.', 'Plotting', 'hard'),
  ('Di far field, laju penurunan amplitude terhadap jarak untuk back-wall planar besar, FBH (disc) kecil, dan SDH (silindris) berturut-turut kira-kira...',
   '["Ketiganya sama, ~1/jarak","1/jarak, 1/jarak^2, dan 1/jarak^1.5","1/jarak^2, 1/jarak, dan 1/jarak^3","Ketiganya ~1/jarak^2"]', 1,
   'Bentuk reflektor menentukan laju penurunan far-field: back-wall planar besar ~1/jarak, FBH disc kecil ~1/jarak^2, dan SDH silindris di antaranya ~1/jarak^1.5. Karena itu DAC/DGS dibangun spesifik per tipe reflektor referensi.', 'Amplitude Correction', 'hard'),
  ('Perbedaan presentasi utama antara kurva DAC dan TCG (saat reflektor referensi identik dimaksimalkan pada berbagai jarak) adalah...',
   '["DAC menaikkan frekuensi, TCG menaikkan voltase pulser","DAC hanya untuk straight beam, TCG hanya untuk angle beam","Pada DAC puncak echo menurun mengikuti kurva (gain tetap); pada TCG semua echo tampil sama tinggi (swept gain) sehingga kurva menjadi datar","DAC mengubah velocity layar, TCG mengubah range layar"]', 2,
   'DAC memakai gain tetap dengan kurva acuan menurun; TCG menerapkan swept gain sehingga reflektor identik tampil sama tinggi di seluruh jarak (kurva datar). Secara prinsip ekuivalen, berbeda pada presentasi; TCG menaikkan noise di jarak jauh.', 'Calibration', 'medium'),
  ('Pernyataan yang BENAR mengenai indikasi yang puncaknya tepat menyentuh kurva DAC (100% DAC) adalah...',
   '["Selalu otomatis reject pada semua code","Itu adalah reference level, bukan otomatis kriteria reject; penolakan mengikuti referencing/acceptance code","Berarti probe rusak","Menandakan transfer correction belum diterapkan"]', 1,
   '100% DAC = reference level. Reject ditentukan oleh referencing/acceptance code (mis. ASME VIII, AWS D1.1), bukan sekadar menyentuh DAC. Banyak code menetapkan recording/evaluation level relatif terhadap DAC (mis. 20% atau 50% DAC).', 'Calibration', 'medium'),
  ('Fungsi transfer correction (transfer loss) dalam kalibrasi adalah...',
   '["Mentransfer kurva DAC dari satu instrumen ke instrumen lain","Mengoreksi perbedaan atenuasi/kekasaran/kelengkungan permukaan antara calibration block dan komponen uji aktual","Mengubah satuan dari dB ke persen FSH","Mengompensasi keausan crystal probe seiring waktu"]', 1,
   'Block referensi dan part nyata sering berbeda surface dan atenuasi. Transfer correction mengukur selisih (mis. metode dua-probe atau perbandingan back-wall) dan menambahkan dB agar evaluasi adil; selisih > 2 dB umumnya wajib dikoreksi dan didokumentasikan.', 'Calibration', 'medium'),
  ('Saat calibration check periodik (tipikal ASME V Art. 4) sensitivitas turun lebih dari 20% (sekitar 2 dB) dari kalibrasi awal. Tindakan yang benar adalah...',
   '["Lanjutkan scanning karena penurunan kecil dapat diabaikan","Naikkan gain 2 dB lalu teruskan tanpa tindakan lain","Catat sebagai temuan dan lapor di akhir shift saja","Recalibrate, lalu scan ulang seluruh area yang diperiksa sejak kalibrasi valid terakhir"]', 3,
   'Jika sensitivitas turun >20% / 2 dB, kalibrasi dianggap tidak valid; instrumen dikalibrasi ulang dan SEMUA area yang diperiksa sejak kalibrasi valid terakhir di-scan ulang agar indikasi yang ter-under-amplified tidak terlewat.', 'Calibration', 'medium'),
  ('Mengapa DAC sebaiknya dibangun dari titik-titik referensi yang berada di FAR FIELD, bukan near field?',
   '["Karena far field memiliki frekuensi yang lebih tinggi","Karena di near field intensitas berfluktuasi (maxima/minima) sehingga amplitude tidak monoton dan kurva tidak andal","Karena near field tidak ada pada probe angle beam","Karena far field menghilangkan kebutuhan couplant"]', 1,
   'Near field (panjang N = D^2/(4*lambda)) memiliki medan yang berfluktuasi dengan maxima/minima, sehingga amplitudo tidak teratur. Titik DAC sebaiknya diambil di far field agar penurunannya monoton dan kurva andal.', 'Calibration', 'hard'),
  ('Pada immersion testing, untuk memasukkan HANYA gelombang shear ke dalam part baja, probe harus dimiringkan sehingga sudut datang berada...',
   '["Tepat pada 0 derajat (normal incidence)","Di atas first critical angle antarmuka air-baja (~14.5 derajat) tetapi di bawah second critical (~27 derajat)","Tepat pada 45 derajat sebagai syarat mutlak","Di atas second critical angle antarmuka air-baja (~27 derajat)"]', 1,
   'Di atas first critical angle (~14.5 derajat untuk antarmuka air-baja) komponen longitudinal ter-refleksi total sehingga hanya shear yang menembus part. Harus tetap di bawah second critical (~27 derajat); di atas itu shear pun tidak lagi menembus. Pada 0 derajat hanya longitudinal yang masuk.', 'Immersion Testing', 'medium'),
  ('Mengapa degassing air sangat penting pada immersion tank?',
   '["Untuk menaikkan kecepatan suara air mendekati baja","Agar suhu air tidak pernah berubah","Karena gelembung udara pada permukaan probe/part menyebabkan dropout sinyal dan indikasi palsu","Untuk menghilangkan kebutuhan kalibrasi FBH"]', 2,
   'Gelembung udara menghamburkan/menghalangi gelombang sehingga menyebabkan dropout sinyal dan false indication. Degassing menghilangkan gas terlarut. Degassing tidak mengubah kecepatan suara air secara berarti.', 'Immersion Testing', 'easy'),
  ('Reflektor referensi yang umum dipakai untuk membangun kalibrasi sensitivitas pada immersion straight-beam (mis. ASTM E127) adalah...',
   '["Side-Drilled Hole (SDH)","Flat-Bottom Hole (FBH)","Surface notch","Threaded plug"]', 1,
   'Immersion straight-beam umumnya memakai Flat-Bottom Hole (FBH) yang mensimulasikan reflektor disc planar berukuran terkalibrasi (penomoran dalam 1/64 inci, mis. #3 FBH = 3/64 inci), per area-amplitude/distance-amplitude block (ASTM E127/E428). SDH/notch lebih lazim untuk angle-beam weld.', 'Immersion Testing', 'medium'),
  ('Hubungan yang benar antara written procedure dan technique sheet (scan plan) adalah...',
   '["Technique sheet menggantikan procedure untuk komponen kompleks","Procedure menetapkan range parameter yang diizinkan; technique sheet memilih nilai spesifik dalam range itu untuk satu komponen","Keduanya identik dan hanya berbeda nama","Technique sheet menetapkan range; procedure memilih nilai aktual"]', 1,
   'Procedure adalah dokumen umbrella yang menetapkan range parameter yang diizinkan (mis. 2-5 MHz, 45-70 derajat). Technique sheet mengaplikasikannya ke satu komponen dengan memilih nilai aktual dalam range itu, dan tidak boleh keluar batas tersebut.', 'Procedure Development', 'medium'),
  ('Procedure UT qualified untuk thickness range 8-40 mm. Datang komponen 64 mm. Tindakan yang benar bagi Level II adalah...',
   '["Langsung inspeksi karena 64 mm hanya sedikit di atas 40 mm","Naikkan gain +6 dB untuk mengompensasi thickness lalu inspeksi","Requalify procedure (block mewakili thickness baru, demonstrasi coverage) dan terbitkan revisi yang disetujui sebelum inspeksi","Buat technique sheet 64 mm tanpa mengubah procedure"]', 2,
   'Thickness range adalah essential variable. 64 mm di luar range 8-40 mm membuat procedure invalid untuk thickness itu. Harus disiapkan qualification block yang mewakili, di-demonstrasi, dan diterbitkan revisi (approval Level III) sebelum inspeksi sah. Tidak boleh diekstrapolasi atau dikompensasi gain.', 'Procedure Development', 'hard'),
  ('Dokumen ASME yang mengatur BAGAIMANA UT examination dilakukan (termasuk Article 4 untuk UT weld) adalah...',
   '["ASME Section V","ASME Section VIII Division 1","ASME Section IX","ASME B31.3"]', 0,
   'ASME Section V (Nondestructive Examination), Article 4, mengatur metode/teknik UT. Acceptance criteria berada di referencing/construction code seperti ASME Section VIII (bejana tekan). Section IX mengatur kualifikasi welding, B31.3 mengatur process piping.', 'Code Interpretation', 'easy'),
  ('Pada pipeline girth weld dengan Automated UT (TOFD + PAUT zonal), keputusan accept/reject cacat umumnya didasarkan pada...',
   '["Kriteria workmanship sederhana (ada indikasi = reject)","Warna grayscale indikasi pada D-scan","Allowable flaw size hasil Engineering Critical Assessment (ECA), mis. API 1104 Annex A","Jumlah total indikasi tanpa memandang ukuran"]', 2,
   'AUT pipeline mengikuti acceptance berbasis ECA (API 1104 Annex A / DNV-ST-F101): flaw diterima/ditolak berdasar height & length terhadap allowable flaw size dari fracture mechanics, bukan kriteria workmanship. Sizing TOFD/PAUT yang akurat menjadi penentu keputusan.', 'Code Interpretation', 'hard'),
  ('Inspeksi clad weld atau weld austenitik stainless sering lebih sulit dengan UT konvensional terutama karena...',
   '["Material terlalu lunak untuk merambatkan gelombang","Atenuasi & scatter tinggi serta beam skewing akibat struktur butir kasar/anisotropi, sehingga sering butuh frekuensi lebih rendah, probe dual/TRL, atau PAUT","Gelombang ultrasonik tidak bisa masuk ke stainless steel sama sekali","Clad weld selalu bebas cacat sehingga tidak perlu diinspeksi"]', 1,
   'Weld austenitik/clad memiliki butir kasar dan anisotropi yang menyebabkan atenuasi tinggi, scatter (grain noise), dan beam skewing/redireksi. Mitigasinya: frekuensi lebih rendah, probe dual-element/TRL untuk near-surface, atau PAUT dengan focal law yang dioptimasi.', 'Field Case Studies', 'hard'),
  ('Informasi yang WAJIB dinyatakan dalam report UT Level II agar hasil sizing dapat diaudit dan direproduksi adalah...',
   '["Hanya keputusan accept/reject akhir","Nama pelanggan dan tanggal saja","Merek couplant yang dipakai saja","Metode sizing yang digunakan (mis. 6 dB drop atau maximum amplitude) beserta reference level"]', 3,
   'Tanpa metode sizing yang dinyatakan dan reference level (mis. DAC/SDH), angka panjang/tinggi cacat tidak dapat direproduksi atau diaudit. Report valid juga mencantumkan prosedur/edisi, equipment, calibration block, data tiap indikasi, keputusan vs criteria, dan tanda tangan inspector.', 'Reporting', 'easy')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 13 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


