-- UT-L2 Module 14 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'quiz', 'FINAL ASSESSMENT — UT Level II', '{"description":"Ujian sertifikasi UT Level II — 60 soal · 120 menit · minimal 80% lulus.","questionCount":60,"passingScore":80}', 7200, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 14
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 14 mini-quiz (60 questions, step 1)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 14 AND ls."orderIndex" = 1 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada baja karbon, perkiraan rasio kecepatan gelombang shear terhadap longitudinal (Vs/Vl) adalah sekitar...',
   '["0.25","0.55","0.90","1.80"]', 1,
   'Vs (~3230 m/s) dibagi Vl (~5900 m/s) menghasilkan rasio sekitar 0.55. Rayleigh wave sekitar 0.9 Vs (bukan 0.9 Vl), dan tidak ada mode yang lebih cepat dari longitudinal pada baja.', 'Advanced Wave Physics', 'easy'),
  ('Pada frekuensi 4 MHz di baja, berapa kira-kira wavelength gelombang shear (Vs ~3230 m/s)?',
   '["0.4 mm","0.6 mm","0.8 mm","1.5 mm"]', 2,
   'lambda = V/f = 3230 / 4.000.000 ≈ 0.0008 m = 0.8 mm. Wavelength shear lebih pendek dibanding longitudinal (~1.5 mm) sehingga memberi resolusi lebih baik untuk inspeksi weld.', 'Advanced Wave Physics', 'medium'),
  ('Untuk wedge acrylic/Perspex (V ~2730 m/s) ke baja, first critical angle (refracted longitudinal mencapai 90 derajat) kira-kira sebesar...',
   '["14.5 derajat","45 derajat","57 derajat","27.5 derajat"]', 3,
   'sin(theta) = Vwedge/Vl_steel = 2730/5900 ≈ 0.463, sehingga first critical ≈ 27.5 derajat. Nilai 14.5 derajat adalah first critical untuk antarmuka air-baja, dan ~57 derajat adalah second critical acrylic-baja.', 'Mode Conversion', 'hard'),
  ('Sebuah gelombang shear 45 derajat mengenai corner (sudut pertemuan backwall dan cacat planar tegak lurus). Fenomena yang sering menghasilkan echo kuat pada posisi tak terduga adalah...',
   '["Corner trap (corner reflector effect)","Dispersi Lamb wave","Resonansi ketebalan","Atenuasi Rayleigh"]', 0,
   'Pada corner antara backwall dan cacat tegak lurus, beam dipantulkan dua kali (corner reflector) dan kembali ke probe dengan amplitudo tinggi — corner trap. Level II harus mengenalinya agar tidak salah size atau salah lokasi cacat.', 'Mode Conversion', 'medium'),
  ('Surface (Rayleigh) wave paling tepat dipakai untuk mendeteksi...',
   '["Inklusi volumetrik jauh di dalam coran tebal","Surface-breaking crack pada komponen bergeometri kompleks seperti fillet shaft atau turbine blade","Laminasi pada pelat baja tebal 50 mm","Porositas tersebar di tengah ketebalan weld"]', 1,
   'Energi Rayleigh wave terkonsentrasi di lapisan permukaan (penetrasi efektif ~1 wavelength) dan dapat mengikuti kontur melengkung, sehingga ideal untuk surface crack pada geometri kompleks. Cacat dalam/volumetrik adalah ranah bulk wave.', 'Advanced Wave Physics', 'easy'),
  ('Mengapa setiap mode Lamb wave (S0, A0, dst.) memerlukan dispersion curve untuk pemilihan titik kerja?',
   '["Karena Lamb wave hanya merambat pada material tebal","Karena Lamb wave selalu monokromatik dan non-dispersif","Karena Lamb wave tidak dapat dibangkitkan dengan wedge","Karena kecepatan tiap mode bergantung pada produk frekuensi x ketebalan (f-d), sehingga pulse dapat melebar bila titik kerja dispersif"]', 3,
   'Lamb wave bersifat dispersif: kecepatan fase/grup tiap mode bergantung pada f-d product. Dispersion curve dipakai memilih titik kerja yang relatif flat agar mode tunggal stabil dan pulse tidak melebar (pulse spreading).', 'Advanced Wave Physics', 'medium'),
  ('Dalam PAUT, apa fungsi focal law (delay law)?',
   '["Mengatur frekuensi nominal tiap elemen array","Mengubah jenis couplant yang dipakai","Menetapkan pola delay waktu firing tiap elemen untuk men-steer dan/atau memfokuskan beam secara elektronik","Menghitung atenuasi material secara otomatis"]', 2,
   'Focal law adalah set delay waktu yang diterapkan ke tiap elemen aktif array; pengaturan delay inilah yang men-steer sudut beam dan memfokuskannya pada kedalaman tertentu tanpa menggerakkan probe.', 'PAUT', 'easy'),
  ('Sebuah sectorial scan (S-scan) PAUT menyapu sudut dari 40 sampai 70 derajat. Mengapa diperlukan ACG (Angle-Corrected Gain) atau TCG per focal law?',
   '["Karena setiap sudut memakai frekuensi berbeda","Karena sensitivitas berbeda untuk tiap sudut/focal law akibat perbedaan beam path dan transmission, sehingga gain perlu dinormalkan agar reflektor referensi memberi amplitudo sama di seluruh sudut","Karena ACG menggantikan kebutuhan couplant","Karena S-scan tidak dapat menampilkan A-scan"]', 1,
   'Tiap sudut/focal law punya sensitivitas berbeda akibat perbedaan beam path, sudut refraksi, dan transmisi melalui wedge. ACG/TCG menormalkan respons reflektor referensi sehingga evaluasi amplitudo konsisten lintas seluruh rentang sudut.', 'PAUT', 'hard'),
  ('Pada PAUT, beam steering elektronik dilakukan dengan cara...',
   '["Menerapkan gradien delay waktu firing antar elemen sehingga muka gelombang gabungan miring pada sudut yang diinginkan","Memutar wedge secara mekanis selama scan","Mengubah ukuran kristal tiap elemen secara real-time","Menaikkan voltase pulser hingga beam membelok"]', 0,
   'Dengan menerapkan delay bertahap antar elemen, kontribusi tiap elemen ber-interferensi konstruktif pada arah tertentu, sehingga muka gelombang gabungan miring (steered) ke sudut yang diinginkan secara elektronik.', 'PAUT', 'medium'),
  ('Keunggulan utama PAUT encoded dibanding UT konvensional manual untuk inspeksi weld adalah...',
   '["Tidak memerlukan kalibrasi sensitivitas","Tidak terpengaruh orientasi cacat sama sekali","Menghasilkan rekaman data ter-encode (S-scan/C-scan) yang permanen, auditable, dan dapat di-re-evaluasi tanpa re-scan","Tidak memerlukan operator bersertifikat"]', 2,
   'PAUT encoded merekam data terkait posisi sehingga menghasilkan imaging permanen (S-scan, C-scan, merged) yang auditable dan dapat dievaluasi ulang. Kalibrasi tetap wajib dan operator tetap harus bersertifikat.', 'PAUT', 'easy'),
  ('Pada TOFD, sinyal mana yang tiba PALING AWAL pada A-scan?',
   '["Backwall echo","Lateral wave","Diffraksi dari lower tip cacat","Mode-converted shear signal"]', 1,
   'Lateral wave merambat tepat di bawah permukaan scan dari transmitter ke receiver melalui jarak terpendek, sehingga tiba lebih dulu dari sinyal tip cacat maupun backwall echo.', 'TOFD', 'easy'),
  ('Sebuah crack embedded pada TOFD memberi sinyal upper tip pada kedalaman 12 mm dan lower tip pada 19 mm. Berapa through-wall height crack tersebut?',
   '["12 mm","19 mm","7 mm","31 mm"]', 2,
   'Height = depth lower tip − depth upper tip = 19 − 12 = 7 mm. Inilah keunggulan TOFD: height dihitung dari selisih waktu tempuh ke kedua tip dengan akurasi tipikal ~+/-1 mm.', 'TOFD', 'medium'),
  ('Pada single-zone TOFD, perpotongan (intersection) sumbu kedua beam idealnya diatur pada kedalaman sekitar...',
   '["0% ketebalan (di permukaan scan)","1/2 ketebalan","2/3 ketebalan","Tepat di backwall (100%)"]', 2,
   'PCS diatur agar intersection beam berada sekitar 2/3 ketebalan, titik di mana coverage dan sensitivitas paling merata. PCS terlalu kecil memperbesar dead zone permukaan; terlalu lebar melemahkan sinyal bagian dalam.', 'TOFD', 'medium'),
  ('Keterbatasan TOFD yang membuatnya sering dipadukan dengan pulse-echo atau PAUT untuk coverage menyeluruh adalah...',
   '["Tidak dapat dipakai pada baja karbon","Dead zone di bawah lateral wave (near-surface) dan dead zone tipis di dekat backwall","Hanya dapat mengukur length, tidak height","Memerlukan radiografi pendamping wajib"]', 1,
   'Lebar pulse lateral wave menciptakan dead zone near-surface, dan backwall echo dapat menutupi cacat tepat di dekat dinding belakang. Karena itu TOFD dipadu PAUT/pulse-echo untuk menutup zona mati tersebut.', 'TOFD', 'medium'),
  ('Pada A-scan RF (unrectified) TOFD, ciri yang mengonfirmasi bahwa dua sinyal berasal dari upper tip dan lower tip crack yang sama adalah...',
   '["Keduanya berfase berlawanan (phase inversion) satu sama lain","Keduanya beramplitudo identik dan saturasi penuh","Keduanya berimpit tepat dengan lateral wave","Keduanya muncul setelah backwall echo"]', 0,
   'Diffraksi dari upper tip dan lower tip suatu crack berfase berlawanan (phase inversion). Analyst membaca polaritas RF untuk memvalidasi tip asli versus noise/geometri sebelum melakukan height sizing.', 'TOFD', 'hard'),
  ('Teknik 6 dB drop (half-amplitude) untuk length sizing menandai ujung reflektor pada posisi probe ketika amplitudo turun menjadi...',
   '["10% dari puncak","25% dari puncak","50% (separuh) dari puncak","70% dari puncak"]', 2,
   'Penurunan 6 dB setara 20·log10(0,5) ≈ −6 dB, yaitu amplitudo turun menjadi separuh (50%) dari puncak. Turun ke 10% berhubungan dengan 20 dB drop, bukan 6 dB.', 'Complex Defect Analysis', 'easy'),
  ('Teknik 6 dB drop memberikan length sizing yang OVERESTIMATE bila...',
   '["Reflektor lebih besar dari beam width dan specular","Gain dijaga konstan selama pengukuran","Couplant diaplikasikan merata","Reflektor lebih kecil dari beam width, sehingga yang terukur sebenarnya lebar beam, bukan ukuran cacat"]', 3,
   'Bila reflektor lebih kecil dari beam width pada arah scan, pergeseran probe yang memberi 6 dB drop mencerminkan profil beam, bukan dimensi cacat — hasilnya over-size. Untuk reflektor kecil dipakai 20 dB drop atau maximum amplitude.', 'Complex Defect Analysis', 'medium'),
  ('Ciri echo dynamics yang paling mengindikasikan cacat VOLUMETRIK (porositas/slag) dibanding planar adalah...',
   '["Amplitudo tinggi tajam yang sangat sensitif terhadap sudut beam","Banyak puncak kecil yang relatif stabil dari berbagai sudut probe karena beam tersebar (scattered)","Satu envelope tunggal yang tajam dan hilang drastis bila sudut diubah","Sinyal sepenuhnya hilang pada semua sudut"]', 1,
   'Reflektor volumetrik menyebarkan beam ke segala arah sehingga memberi banyak puncak kecil yang amplitudonya relatif stabil saat sudut/posisi probe diubah. Respons tajam sensitif-sudut justru ciri cacat planar.', 'Complex Defect Analysis', 'medium'),
  ('Sebuah indikasi ditemukan pada sound path 50 mm dengan probe sudut 60 derajat (1st leg). Berapa kira-kira surface distance dari beam index point?',
   '["25 mm","43 mm","50 mm","87 mm"]', 1,
   'Surface distance = S·sin(theta) = 50 × sin 60° = 50 × 0,866 ≈ 43 mm. (Depth = S·cos 60° = 25 mm.) Sudut diukur dari garis normal.', 'Complex Defect Analysis', 'medium'),
  ('Pada plotting 2nd leg dengan probe sudut 60 derajat, sound path 70 mm, dan ketebalan benda 25 mm, berapa depth indikasi dihitung dari permukaan scan?',
   '["15 mm","35 mm","25 mm","50 mm"]', 0,
   'Depth pada 2nd leg = 2t − S·cos(theta) = (2×25) − (70 × cos 60°) = 50 − 35 = 15 mm. Nilai 35 mm adalah depth bila keliru diperlakukan sebagai 1st leg (S·cos θ), dan 50 mm = 2t.', 'Complex Defect Analysis', 'hard'),
  ('Untuk mengukur extent sebuah CLUSTER porositas yang tersebar (multi reflektor kecil), teknik sizing yang paling tepat adalah...',
   '["6 dB drop tunggal pada puncak tertinggi","Mengukur satu pori terbesar saja","Backwall drop technique","Maximum amplitude technique (catat tiap peak lokal dari ujung ke ujung)"]', 3,
   'Cluster porositas tidak memantul specular, sehingga 6 dB drop tidak sesuai. Maximum amplitude technique mencatat tiap peak lokal sehingga extent kumpulan reflektor kecil dapat didefinisikan dari peak pertama ke terakhir.', 'Complex Defect Analysis', 'medium'),
  ('Dua reflektor SDH identik pada kedalaman 15 mm dan 70 mm memberi amplitudo berbeda tanpa koreksi. Apa yang dikompensasi DAC/TCG?',
   '["Perbedaan frekuensi probe pada tiap kedalaman","Penurunan amplitudo akibat atenuasi material dan beam spread dengan bertambahnya metal-path","Perubahan kecepatan suara terhadap kedalaman","Perbedaan ukuran fisik kedua SDH"]', 1,
   'Reflektornya identik; penurunan amplitudo murni karena efek jarak — atenuasi (absorpsi + scattering) dan beam divergence di far field. DAC/TCG/DGS dibangun untuk mengompensasi efek jarak ini.', 'Advanced Calibration', 'easy'),
  ('Perbedaan presentasi utama antara DAC dan TCG saat reflektor referensi identik dimaksimalkan pada berbagai jarak adalah...',
   '["DAC menaikkan voltase pulser; TCG menaikkan frekuensi","Pada DAC puncak echo menurun mengikuti kurva (gain tetap); pada TCG diterapkan swept gain sehingga semua echo tampil sama tinggi (kurva menjadi datar)","DAC hanya untuk angle beam; TCG hanya untuk straight beam","DAC mengubah range layar; TCG mengubah velocity"]', 1,
   'DAC memakai gain tetap dengan kurva menurun sebagai acuan; TCG menerapkan swept (time-corrected) gain sehingga reflektor identik tampil sama tinggi di seluruh jarak. Secara prinsip ekuivalen, berbeda pada presentasi.', 'Advanced Calibration', 'medium'),
  ('Keuntungan utama metode DGS/AVG dibanding membangun DAC dari banyak SDH adalah...',
   '["DGS tidak memerlukan koreksi atenuasi material","DGS tidak terpengaruh parameter probe sama sekali","DGS cukup satu reflektor referensi (mis. back-wall) untuk menyetel kurva teoritis, lalu cacat dibaca sebagai Equivalent Reflector Size (ERS)","DGS otomatis menaikkan PRF sesuai jarak"]', 2,
   'DGS/AVG memakai kurva ternormalisasi untuk probe tertentu sehingga cukup satu reflektor referensi untuk kalibrasi, lalu cacat dibaca sebagai ERS. Kelemahannya: sangat sensitif terhadap akurasi parameter probe dan atenuasi material.', 'Advanced Calibration', 'medium'),
  ('Fungsi transfer correction (transfer loss) dalam kalibrasi adalah...',
   '["Mengoreksi perbedaan atenuasi/kekasaran/kurvatur antara calibration block dan komponen uji aktual","Mengubah satuan dB menjadi persen FSH","Mentransfer kurva DAC antar instrumen berbeda","Mengompensasi keausan kristal probe"]', 0,
   'Block referensi dan part nyata sering berbeda surface dan atenuasi. Transfer correction mengukur selisih dan menambahkan dB agar evaluasi adil; selisih > 2 dB umumnya wajib dikoreksi dan didokumentasikan.', 'Advanced Calibration', 'medium'),
  ('Mengapa titik-titik kalibrasi DAC sebaiknya diambil di far field, bukan di dalam near field?',
   '["Karena di near field velocity berubah","Karena di dalam near field intensitas berfluktuasi (maxima/minima) sehingga amplitudo tidak monoton dan kurva tidak valid","Karena far field tidak terpengaruh atenuasi","Karena near field hanya ada pada angle beam"]', 1,
   'Di dalam near field (N = D^2/(4·lambda)) medan ber-interferensi sehingga intensitas naik-turun dengan maxima/minima. Amplitudo tidak monoton membuat kurva DAC tidak valid; titik kalibrasi diambil di far field.', 'Advanced Calibration', 'hard'),
  ('Untuk inspeksi pipeline girth weld dengan AUT zonal, ECA (Engineering Critical Assessment) berbasis apa?',
   '["Jumlah total indikasi tanpa memandang ukuran","Warna grayscale pada D-scan","Fracture mechanics — cacat dibandingkan allowable flaw size yang diturunkan dari toughness, tegangan, dan beban operasi (mis. API 1104 Annex A / DNV-ST-F101)","Penilaian visual tinggi reinforcement weld"]', 2,
   'ECA menilai accept/reject berdasarkan height & length terhadap allowable flaw size dari fracture mechanics (API 1104 Annex A / DNV-ST-F101), bukan kriteria workmanship. Sizing AUT yang akurat menjadi penentu keputusan.', 'Advanced Calibration', 'medium'),
  ('Saat calibration check periodik menemukan sensitivitas turun lebih dari 20% (~2 dB) dari kalibrasi awal, tindakan yang benar adalah...',
   '["Lanjutkan scanning karena penurunan kecil dapat diabaikan","Naikkan gain 2 dB lalu teruskan tanpa tindakan lain","Recalibrate, lalu scan ulang seluruh area yang diperiksa sejak kalibrasi valid terakhir","Catat dan laporkan saja di akhir shift"]', 2,
   'Jika sensitivitas turun > 20% / 2 dB, kalibrasi dianggap tidak valid; instrumen di-recalibrate dan semua area sejak kalibrasi valid terakhir di-scan ulang agar indikasi yang ter-under-amplified tidak terlewat.', 'Advanced Calibration', 'medium'),
  ('Pada immersion testing, mengapa water path muncul sebagai delay panjang di awal A-scan sebelum front surface echo?',
   '["Karena air mempercepat sinyal sehingga tertunda","Karena kecepatan suara di air (~1480 m/s) jauh lebih lambat daripada baja (~5900 m/s), sehingga waktu tempuh melintasi water path relatif panjang","Karena probe immersion berfrekuensi sangat rendah","Karena air menyerap seluruh energi longitudinal"]', 1,
   'Vair (~1480 m/s) jauh lebih lambat dari Vbaja, jadi gelombang butuh waktu relatif lama melintasi water path, muncul sebagai delay sebelum front surface echo (FSE). Water path diatur agar gema-ulangnya tidak tumpang tindih dengan echo material.', 'Immersion Testing', 'medium'),
  ('Untuk memasukkan HANYA gelombang shear ke part baja pada immersion, sudut datang harus di atas first critical angle antarmuka air-baja, yaitu sekitar...',
   '["0 derajat","14.5 derajat","27 derajat","45 derajat"]', 1,
   'First critical air-baja: sin(theta) = Vair/Vl_baja = 1480/5900 ≈ 0,251 → ~14.5 derajat. Di atas sudut ini longitudinal ter-refleksi total dan hanya shear ter-mode-convert masuk ke part. Di atas second critical (~27 derajat) muncul surface wave.', 'Immersion Testing', 'medium'),
  ('Mengapa degassing air sangat penting pada immersion tank?',
   '["Untuk menaikkan kecepatan suara air mendekati baja","Karena gelembung udara di permukaan probe atau part menyebabkan dropout sinyal dan indikasi palsu","Untuk menghilangkan kebutuhan kalibrasi DAC","Agar suhu air tidak pernah berubah"]', 1,
   'Gelembung udara menghamburkan/menghalangi gelombang, menyebabkan kehilangan sinyal (dropout) dan false call. Degassing menghilangkan gas terlarut. Degassing tidak mengubah kecepatan suara air secara berarti.', 'Immersion Testing', 'easy'),
  ('Saat menormalkan probe immersion agar tegak lurus permukaan part flat, operator harus...',
   '["Memaksimalkan amplitudo front surface echo (FSE) dengan menyetel gimbal","Meminimalkan back surface echo","Memanjangkan water path hingga FSE hilang","Mengatur gimbal tepat pada 14.5 derajat"]', 0,
   'Saat beam benar-benar normal, energi yang dipantulkan kembali ke probe maksimum, sehingga FSE mencapai amplitudo tertinggi. Operator menyetel gimbal sampai FSE maksimum. 14.5 derajat justru untuk angle-beam (shear).', 'Immersion Testing', 'medium'),
  ('Pada automated immersion UT, sebuah C-scan menunjukkan cluster amplitudo tinggi di satu area. Langkah Level II SEBELUM menyatakannya flaw adalah...',
   '["Langsung reject berdasarkan warna C-scan","Memverifikasi dengan A-scan pada titik tersebut untuk membedakan flaw nyata dari artefak (edge effect, gelembung, surface roughness)","Menaikkan gain 6 dB lalu re-scan seluruh part","Mengganti probe focused dengan flat probe"]', 1,
   'Indikasi C-scan harus dikorelasikan dengan A-scan di titik tersebut untuk memastikan flaw nyata, bukan artefak seperti edge effect, gelembung, atau kekasaran permukaan. Interpretasi imaging tanpa verifikasi A-scan berisiko reject palsu.', 'Immersion Testing', 'medium'),
  ('Pada kalibrasi sensitivitas immersion straight-beam (mis. ASTM E127/E428), reflektor referensi standar yang dipakai untuk kurva distance-amplitude adalah...',
   '["Notch persegi di tepi blok","Side-drilled hole tunggal","Serangkaian flat-bottom hole (FBH), mis. #3 FBH (3/64 inci)","Lubang ulir besar di tengah blok"]', 2,
   'DAC/TCG immersion straight-beam dibangun dari serangkaian FBH pada kedalaman berbeda. FBH mensimulasikan reflektor planar berukuran terkalibrasi (mis. #3 FBH = 3/64 inci). SDH/notch lebih lazim untuk teknik angle-beam.', 'Immersion Testing', 'hard'),
  ('Apa perbedaan mendasar antara written procedure dan technique sheet (scan plan)?',
   '["Keduanya identik, hanya berbeda nama","Procedure menetapkan RANGE parameter yang diizinkan; technique sheet memilih nilai spesifik dalam range itu untuk satu komponen dan tidak boleh keluar batas","Technique sheet menggantikan procedure untuk komponen kompleks","Procedure hanya untuk PAUT; technique sheet untuk UT konvensional"]', 1,
   'Procedure adalah dokumen umbrella yang menetapkan range parameter (mis. 2-5 MHz, 45-70 derajat). Technique sheet mengaplikasikan procedure ke satu komponen spesifik dengan memilih nilai aktual dalam range itu, tanpa melampaui batas.', 'Procedure Development', 'easy'),
  ('Menurut ASME V Article 4 (T-421), apa yang membedakan essential variable dari nonessential variable?',
   '["Essential hanya berlaku untuk PAUT","Perubahan essential variable di luar range mewajibkan requalification procedure; perubahan nonessential tidak (namun tetap dicatat)","Nonessential variable harus ditetapkan Level III; essential oleh operator","Essential variable boleh diabaikan dalam report"]', 1,
   'Essential variable (mis. frekuensi, sudut, thickness range, calibration block) jika diubah di luar range yang ditetapkan/di-demonstrate mewajibkan requalification. Nonessential boleh diubah dalam batas tanpa requalify, tetapi tetap dicatat.', 'Procedure Development', 'medium'),
  ('Procedure qualified untuk butt weld carbon steel thickness 8-40 mm. Datang komponen 64 mm. Tindakan benar Level II adalah...',
   '["Langsung inspeksi karena 64 mm hanya sedikit di atas 40 mm","Naikkan gain +6 dB untuk mengompensasi thickness lalu inspeksi","Requalify procedure (block mewakili thickness baru, demonstrasi coverage) dan terbitkan revisi yang disetujui sebelum inspeksi","Buat technique sheet 64 mm tanpa mengubah procedure"]', 2,
   'Thickness range adalah essential variable; 64 mm di luar range 8-40 mm membuat procedure invalid untuk thickness itu. Harus disiapkan qualification block yang mewakili, demonstrasi coverage, dan revisi disetujui Level III sebelum inspeksi sah.', 'Procedure Development', 'medium'),
  ('Mengapa demonstrasi (procedure qualification) pada qualification block diperlukan ketika Table T-421 menandainya untuk suatu essential variable?',
   '["Untuk melatih operator Level I","Untuk membuktikan procedure mampu mendeteksi reflektor referensi di seluruh volume yang dipersyaratkan, termasuk zona ekstrem dan dekat permukaan","Hanya formalitas administratif","Untuk mengkalibrasi flaw detector sebelum dijual"]', 1,
   'Demonstrasi membuktikan procedure (dengan essential variable yang ditetapkan) benar-benar dapat mendeteksi reflektor referensi seperti SDH di seluruh volume yang dipersyaratkan, termasuk kedalaman ekstrem dan near-surface — bukti kemampuan deteksi.', 'Procedure Development', 'medium'),
  ('Saat menyusun written procedure, siapa yang umumnya berwenang menyetujui/men-sign procedure sesuai SNT-TC-1A?',
   '["Level I yang melakukan scan","Level II yang menyusunnya","Level III sesuai written practice employer","Authorized Inspector (AI) saja"]', 2,
   'Level II umumnya authorized menyusun dan me-review procedure, tetapi approval/penandatanganan procedure adalah tanggung jawab Level III sesuai written practice employer (SNT-TC-1A) atau ISO 9712.', 'Procedure Development', 'easy'),
  ('Dalam kerangka code UT, peran ASME BPVC Section V Article 4 adalah...',
   '["Menetapkan acceptance criteria untuk semua weld pressure equipment","Mengatur TEKNIK pemeriksaan UT (kalibrasi, scanning, sizing), sedangkan acceptance ditetapkan referencing/construction code","Menggantikan AWS D1.1 untuk struktur baja","Menetapkan interval inspeksi in-service"]', 1,
   'Section V (Article 4) mengatur teknik UT — kalibrasi, scanning, recording, sizing — dan menyatakan acceptance ditetapkan oleh referencing code (mis. ASME VIII Mandatory Appendix). Acceptance bukan domain Section V.', 'Code Interpretation', 'easy'),
  ('Pada ASME Section VIII Div.1 Mandatory Appendix 12, bagaimana indikasi yang teridentifikasi sebagai crack, lack of fusion, atau incomplete penetration diperlakukan?',
   '["Diterima selama panjangnya di bawah t/3","Ditolak (rejectable) tanpa memandang panjang karena bersifat planar/crack-like","Diterima selama amplitudonya di bawah 100% DAC","Selalu memerlukan RT konfirmasi sebelum keputusan"]', 1,
   'App.12 (12-3(a)) menolak semua indikasi crack, lack of fusion, dan incomplete penetration tanpa memandang panjang karena bersifat planar/crack-like. Batas length (12-3(b)) berlaku untuk indikasi lain di atas reference.', 'Code Interpretation', 'medium'),
  ('Pada sistem indication rating AWS D1.1, rating d dihitung dengan rumus...',
   '["d = a + b + c","d = b − a (reference dikurangi indikasi)","d = (a × b) / c","d = a − b − c (indication level − reference level − attenuation factor)"]', 3,
   'AWS D1.1 menghitung d = a − b − c, dengan a = indication level (dB), b = reference level (dB dari SDH pada IIW block), dan c = attenuation factor. d dibandingkan dengan tabel acceptance sesuai jenis pembebanan.', 'Code Interpretation', 'medium'),
  ('Pada AWS D1.1, indikasi A memberi d = −3 dB dan indikasi B memberi d = +7 dB. Interpretasi yang benar adalah...',
   '["d = −3 dB menandakan reflektor relatif BESAR (cenderung rejectable); d = +7 dB menandakan reflektor relatif KECIL/lemah (cenderung acceptable)","d = +7 dB lebih berbahaya karena angkanya lebih besar","Tanda hanya formalitas; keduanya setara signifikansinya","d = −3 dB berarti tidak ada indikasi"]', 0,
   'Karena d = a − b − c dan reflektor besar butuh gain a lebih rendah untuk mencapai reference height, reflektor besar menghasilkan d lebih kecil/negatif (cenderung rejectable). Reflektor lemah butuh gain tinggi sehingga d positif besar (cenderung acceptable).', 'Code Interpretation', 'hard'),
  ('Pasangan code mana yang TEPAT untuk inspeksi in-service equipment yang sudah beroperasi?',
   '["ASME VIII Div.1 untuk vessel baru","AWS D1.1 untuk struktur baja baru","API 510 (pressure vessel), API 570 (process piping), API 653 (aboveground storage tank)","ASME B31.3 untuk process piping baru"]', 2,
   'API 510 (vessel), 570 (piping), dan 653 (tank) adalah in-service inspection codes yang menetapkan interval, scope, remaining life, dan repair/rerate. ASME VIII Div.1, AWS D1.1, dan B31.3 adalah construction code untuk fabrikasi baru.', 'Code Interpretation', 'easy'),
  ('Saat sebuah pasal code tampak ambigu sehingga memengaruhi keputusan accept/reject, tindakan yang benar Level II adalah...',
   '["Membuat interpretasi pribadi yang paling menguntungkan agar proyek lanjut","Mengabaikan indikasi karena pasalnya tidak jelas","Eskalasi ke Level III/engineering dan, bila perlu, merujuk Code Interpretation/Code Case resmi yang diadopsi jurisdiksi; dokumentasikan dasar keputusan","Menaikkan reference level hingga indikasi lolos"]', 2,
   'Inspektor tidak boleh membuat interpretasi pribadi atas pasal ambigu. ASME/AWS/API menerbitkan Code Interpretations dan Code Cases resmi yang berlaku bila diadopsi jurisdiksi/kontrak. Ambiguitas dieskalasi dan keputusan didokumentasikan.', 'Code Interpretation', 'hard'),
  ('Mengapa nomor pasal/tabel acceptance dapat bergeser antar edisi code, sehingga procedure & report harus menyebut EDISI spesifik?',
   '["Karena penomoran tabel dan struktur appendix dapat berubah antar edisi (mis. UT AWS D1.1 pindah dari Clause 6 ke Clause 8), bahkan nilai batas dapat berubah","Karena edisi lama tidak pernah berlaku lagi sama sekali","Karena hanya satu edisi yang pernah diterbitkan","Karena edisi tidak memengaruhi acceptance"]', 0,
   'Code direvisi berkala dan penomoran tabel/pasal dapat bergeser (UT AWS D1.1 pindah Clause 6 → 8), bahkan nilai batas dapat berubah. Karena itu prosedur & laporan wajib menyebut edisi/addenda yang governing.', 'Code Interpretation', 'medium'),
  ('Dalam fitness-for-service (API 579-1 / BS 7910), parameter dimensi cacat mana yang umumnya paling dominan menentukan stress intensity factor (K) untuk surface crack?',
   '["Amplitudo maksimum dalam % DAC","Sound path total dari exit point ke cacat","Through-wall height/depth (a), karena K = Y·sigma·akar(pi·a)","Surface distance probe ke datum"]', 2,
   'Through-wall height (a untuk surface flaw) adalah parameter dominan; K = Y·sigma·akar(pi·a). Inilah mengapa height sizing yang akurat sangat kritis untuk FFS dan kenapa under-sizing height sangat berbahaya.', 'Reporting & Sizing', 'medium'),
  ('Untuk height (through-wall) sizing yang akurat pada crack planar, teknik mana yang paling tepat dan mengapa?',
   '["6 dB drop, karena paling cepat","Maximum amplitude, karena selalu mengukur peak tertinggi","Tip-diffraction / TOFD, karena mengukur waktu tempuh ke ujung cacat dan relatif tidak sensitif orientasi (akurasi ~+/-1 mm)","Backwall echo monitoring, karena memantau total ketebalan"]', 2,
   'Tip-diffraction (termasuk TOFD) mengukur posisi/kedalaman tip cacat dari waktu tempuh sinyal difraksi, bukan amplitudo. Karena berbasis waktu, jauh kurang sensitif terhadap orientasi dan memberi akurasi height tipikal ~+/-1 mm.', 'Reporting & Sizing', 'medium'),
  ('Dua cacat berdekatan ditemukan sepanjang weld. Dalam recharacterization untuk FFS, bila spasi antar keduanya lebih kecil dari kriteria proximity/interaksi, apa yang dilakukan?',
   '["Laporkan hanya cacat dengan amplitudo lebih tinggi","Gabungkan keduanya menjadi satu cacat efektif yang lebih besar","Abaikan keduanya karena medan tegangannya saling membatalkan","Kurangi ukuran masing-masing sebesar spasi di antaranya"]', 1,
   'Aturan proximity/interaksi (BS 7910, API 579) mensyaratkan cacat yang terlalu dekat diperlakukan sebagai satu cacat gabungan yang lebih besar, karena medan tegangan keduanya berinteraksi. Pendekatan ini konservatif dan langsung memakai length + height hasil sizing.', 'Reporting & Sizing', 'hard'),
  ('Manakah elemen yang WAJIB ada agar laporan UT Level II dapat ditelusuri (traceable) dan dipertanggungjawabkan?',
   '["Hanya kesimpulan accept/reject dan tanda tangan","Hanya foto komponen dan tanggal","Prosedur+revisi, code/acceptance criteria, detail peralatan & kalibrasi (DAC/TCG), teknik sizing, dan tanda tangan + level personel","Hanya nilai amplitudo tertinggi yang ditemukan"]', 2,
   'Report yang ditandatangani Level II harus reproducible: prosedur & revisi, acceptance criteria, peralatan (model/S/N, probe, couplant), blok & reference reflector, kalibrasi range + sensitivity, hasil sizing beserta teknik, evaluasi, dan tanda tangan + level sertifikasi.', 'Reporting & Sizing', 'easy'),
  ('Mengapa amplitudo tinggi TIDAK boleh diasumsikan langsung sebagai cacat besar saat sizing?',
   '["Karena amplitudo selalu dikalibrasi otomatis menjadi ukuran","Karena amplitudo dipengaruhi orientasi reflektor, sifat permukaan (tip vs face), dan posisi dalam beam profile — bukan hanya ukuran","Karena flaw detector membatasi amplitudo pada 80% FSH","Karena amplitudo hanya bergantung pada frekuensi probe"]', 1,
   'Amplitudo bergantung pada orientasi reflektor, kekasaran/sifat permukaan, dan posisi dalam beam — bukan sekadar ukuran. Crack planar nyaris sejajar beam bisa memberi sinyal rendah meski besar; karena itu sizing harus berbasis metode, bukan asumsi amplitudo-ukuran.', 'Reporting & Sizing', 'medium'),
  ('Sebuah cacat planar gagal acceptance konstruksi, tetapi pemilik ingin menghindari repair mahal. Tindakan yang BENAR adalah...',
   '["Mengubah keputusan menjadi accept karena amplitudo hanya sedikit di atas batas","Mengurangi reference gain agar indikasi turun di bawah recording level","Mengabaikan cacat karena berada di tengah ketebalan","Melakukan penilaian FFS (API 579-1/ASME FFS-1) oleh engineer dengan data sizing length DAN height akurat; inspector menyediakan data, engineer memutuskan run/repair"]', 3,
   'Cacat yang gagal acceptance konstruksi dapat dinilai lewat jalur FFS yang butuh dimensi akurat termasuk height through-wall. Keputusan run/repair/replace dibuat engineer; Level II menyediakan data sizing yang dapat dipertahankan dan TIDAK boleh mengubah reject menjadi accept tanpa disposisi FFS resmi.', 'Reporting & Sizing', 'hard'),
  ('Pada inspeksi nozzle set-on ke shell (geometri melengkung), kompensasi apa yang lazim ditambahkan akibat permukaan curved dan perbedaan block vs part?',
   '["Curvature correction dan transfer correction (tambahan dB) sesuai prosedur","Penurunan frekuensi otomatis menjadi 1 MHz","Penghapusan DAC karena tidak relevan pada kurva","Penggunaan surface wave wajib"]', 0,
   'Permukaan lengkung dan perbedaan kekasaran/atenuasi antara calibration block dan part nyata memerlukan curvature correction dan transfer correction, biasanya berupa penambahan dB pada gain yang didokumentasikan dalam prosedur.', 'Field Case Studies', 'medium'),
  ('Mengapa inspeksi UT pada las/clad austenitic jauh lebih sulit dibanding carbon steel?',
   '["Austenitic memiliki velocity persis sama dengan carbon steel","Struktur coarse-grained dan anisotropic menyebabkan atenuasi tinggi, grain noise tinggi, serta beam skewing/velocity tidak seragam","Austenitic tidak memantulkan gelombang ultrasonik","Hanya bisa diperiksa dengan surface wave"]', 1,
   'Las austenitic bersifat coarse-grained dan anisotropic, menimbulkan atenuasi tinggi, hamburan butir (grain noise), serta beam skew dan velocity tidak seragam — menyulitkan interpretasi shear wave konvensional dan menuntut teknik khusus.', 'Field Case Studies', 'medium'),
  ('Teknik probe mana yang paling tepat untuk mengurangi grain noise pada inspeksi weld austenitic / dissimilar metal weld?',
   '["Single-crystal shear wave 5 MHz","Probe frekuensi rendah (1-2 MHz) dual-element / TRL (transmit-receive longitudinal)","Normal beam 0 derajat compression saja","Surface wave (Rayleigh) 10 MHz"]', 1,
   'Frekuensi rendah menurunkan scatter pada butir kasar, dan probe TRL dual-element (longitudinal angle beam) lebih tahan terhadap grain noise dibanding single-crystal shear. PAUT TRL atau TOFD juga umum dipakai untuk DMW.', 'Field Case Studies', 'hard'),
  ('Sebuah indikasi mengikuti kontur root bead secara konsisten, posisinya cocok dengan root reinforcement pada weld map, dan responnya tidak tajam pada berbagai sudut. Interpretasi paling mungkin adalah...',
   '["Crack planar kritis di root","Lack of fusion yang dalam","Indikasi geometri (root bead), bukan cacat","Porositas tersebar"]', 2,
   'Indikasi yang mengikuti kontur root secara konsisten, cocok dengan fitur geometri pada weld map, dan tidak memberi respons tajam sensitif-sudut, biasanya adalah geometric reflector (root bead) — bukan cacat planar.', 'Field Case Studies', 'medium'),
  ('Pada AWS D1.1, mengapa tabel acceptance berbeda untuk sambungan statically loaded versus cyclically loaded?',
   '["Beban dinamis (cyclic) lebih rentan fatigue, sehingga ambang reject diperketat (sekitar 4 dB lebih ketat) dibanding statik","Beban statik memerlukan probe sudut berbeda","Hanya beban dinamis yang boleh diperiksa UT","Tidak ada perbedaan nyata; threshold sama"]', 0,
   'Komponen siklik rentan fatigue crack growth, sehingga AWS D1.1 memberi acceptance threshold lebih ketat (~4 dB) dibanding statik. Memilih tabel salah dapat meloloskan cacat yang seharusnya ditolak.', 'Field Case Studies', 'medium'),
  ('Pada Level II UT, garis pemisah scope dengan Level I adalah...',
   '["Level I boleh evaluasi accept/reject selama disaksikan Level II","Level I boleh menandatangani report bila Level II counter-sign","Level I tidak boleh menyentuh instrument","Level I melakukan setup/kalibrasi spesifik/scan/record di bawah arahan tertulis, tetapi evaluasi accept/reject dan penandatanganan report final adalah wewenang Level II/III"]', 3,
   'Per SNT-TC-1A, Level I qualified untuk setup, kalibrasi spesifik, scan, dan record di bawah arahan tertulis, namun evaluasi terhadap acceptance criteria dan penandatanganan report final adalah wewenang Level II/III.', 'Operator Training', 'easy'),
  ('Sebuah entri OJT log mencatat hanya ''8 jam UT'' tanpa detail lain. Sebagai mentor Level II yang diminta menandatangani validasi, sikap yang benar adalah...',
   '["Menandatangani karena total jam sudah benar","Menandatangani tetapi memberi catatan untuk diperbaiki nanti","Menahan tanda tangan sampai entri mencantumkan tanggal, jenis part/pekerjaan, jam aktual, dan level supervisi yang benar-benar disaksikan","Meminta Level I sendiri yang menandatangani validasi"]', 2,
   'Validasi OJT adalah pernyataan profesional. Log harus mencatat tanggal, method, jenis pekerjaan, jam aktual, dan supervisi. Mentor tidak boleh menandatangani jam yang tidak disaksikan; jam tanpa rincian tidak valid sebagai experience yang auditable.', 'Operator Training', 'medium'),
  ('Untuk lulus kualifikasi tertulis Level II per SNT-TC-1A, skor minimum yang benar adalah...',
   '["Minimum 70% pada tiap bagian (General/Specific/Practical) dan composite minimum 80%","Minimum 80% pada tiap bagian tanpa composite","Minimum 60% composite saja","Minimum 90% pada Practical dan 50% pada General"]', 0,
   'SNT-TC-1A merekomendasikan minimum 70% pada masing-masing examination (General, Specific, Practical) dengan composite grade minimum 80%. Ditambah syarat lulus near-vision (Jaeger No.1 / setara) dan color/shade-of-gray contrast yang di-test tahunan.', 'Operator Training', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 14 AND ls."orderIndex" = 1 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 1 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (4, 'quiz', 'Mini-quiz — Pengantar UT-L2', '{"description":"Konfirmasi pemahaman scope, kewenangan, dan persyaratan sertifikasi Level II.","questionCount":5,"passingScore":75}', 600, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 1
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 1 mini-quiz (5 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Apa perbedaan utama kewenangan (authority) antara teknisi UT Level I dan Level II menurut SNT-TC-1A?',
   '["Level I dapat melakukan kalibrasi spesifik dan merekam hasil di bawah arahan, sedangkan Level II berwenang menetapkan teknik, menginterpretasi, dan mengevaluasi hasil terhadap kode/spesifikasi","Level I dan Level II memiliki kewenangan yang identik, hanya berbeda lama pengalaman","Level I berwenang menyetujui prosedur tertulis, sedangkan Level II hanya menjalankan instruksi","Hanya Level I yang boleh mengoperasikan instrumen UT, sedangkan Level II hanya bekerja di kantor"]', 0,
   'Menurut SNT-TC-1A, Level I melakukan kalibrasi/pemeriksaan spesifik dan merekam hasil di bawah arahan, sedangkan Level II berwenang memilih teknik, menyetel/memverifikasi peralatan, menginterpretasi, dan mengevaluasi hasil terhadap kode, standar, atau spesifikasi.', 'Scope & Authority', 'easy'),
  ('Apa perbedaan mendasar model sertifikasi antara SNT-TC-1A dan ISO 9712 yang relevan bagi seorang Level II?',
   '["SNT-TC-1A adalah sertifikasi pihak ketiga independen, sedangkan ISO 9712 berbasis employer","Keduanya identik; ISO 9712 hanya terjemahan SNT-TC-1A ke bahasa internasional","SNT-TC-1A adalah recommended practice berbasis employer (perusahaan menerbitkan Written Practice dan mengsertifikasi sendiri), sedangkan ISO 9712 adalah skema sertifikasi terpusat oleh badan independen pihak ketiga","SNT-TC-1A hanya berlaku untuk PAUT, sedangkan ISO 9712 hanya untuk UT konvensional"]', 2,
   'SNT-TC-1A adalah recommended practice di mana employer menyusun Written Practice dan mengsertifikasi personel sendiri, sedangkan ISO 9712 adalah sertifikasi terpusat oleh badan/certification body pihak ketiga yang independen dari employer.', 'Certification Schemes', 'medium'),
  ('Selain tugas konvensional, kompetensi lanjutan apa yang umumnya diharapkan dari teknisi UT Level II pada pekerjaan modern?',
   '["Hanya mampu mengoperasikan pulse-echo straight beam","Mampu menerapkan teknik lanjutan seperti PAUT (beam steering/focal law) dan TOFD (tip diffraction) untuk deteksi dan sizing","Tidak diizinkan menggunakan teknik selain DAC manual","Hanya melakukan visual testing menggantikan UT"]', 1,
   'UT Level II diharapkan menguasai teknik lanjutan seperti Phased Array (PAUT) dengan beam steering dan focal law, serta TOFD yang mengandalkan tip diffraction, untuk deteksi dan sizing yang lebih akurat dibanding teknik konvensional.', 'Advanced Techniques', 'medium'),
  ('Siapa yang berwenang menyetujui (approve) prosedur NDT tertulis menurut struktur kualifikasi SNT-TC-1A?',
   '["Teknisi Level I setelah menyelesaikan pelatihan dasar","Teknisi Level II untuk semua metode tanpa pengecualian","Operator apprentice di bawah pengawasan","Teknisi Level III, sedangkan Level II umumnya menyusun/menerapkan instruksi tertulis berdasarkan prosedur yang disetujui"]', 3,
   'Persetujuan prosedur NDT adalah kewenangan Level III; Level II umumnya menyusun dan menerapkan instruksi kerja tertulis dari prosedur yang sudah disetujui Level III, sekaligus dapat memberikan pelatihan/pengarahan ke Level I dan trainee.', 'Procedure Development', 'hard'),
  ('Manakah pernyataan yang benar mengenai persyaratan kualifikasi UT Level II menurut SNT-TC-1A/CP-105?',
   '["Tidak memerlukan jam pelatihan formal maupun pengalaman, cukup ujian tertulis","Memerlukan jam pelatihan terdokumentasi, pengalaman kerja terkualifikasi, serta lulus ujian general, specific, dan practical untuk metode UT","Hanya memerlukan ujian visual mata tanpa ujian teknis","Sertifikasi diberikan otomatis setelah seseorang menjadi Level I selama satu tahun tanpa ujian"]', 1,
   'Kualifikasi Level II menuntut jam pelatihan terdokumentasi dan pengalaman terkualifikasi pada metode tersebut, serta lulus ujian general, specific, dan practical (hands-on), ditambah pemeriksaan ketajaman penglihatan—sesuai rekomendasi SNT-TC-1A dan ASNT CP-105.', 'Certification Requirements', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- UT-L2 Module 3 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (6, 'quiz', 'Mini-quiz — PAUT Introduction', '{"description":"Konfirmasi pemahaman PAUT principles, focal law, dan code requirements.","questionCount":7,"passingScore":75}', 720, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 3
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- UT-L2 Module 3 mini-quiz (7 questions, step 6)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'UT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 6 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'UT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada probe phased array, beam ultrasonik diarahkan (steered) dan difokuskan secara elektronik dengan cara:',
   '["Memberikan time delay (penundaan waktu) terprogram pada pulsa eksitasi tiap elemen","Memutar probe secara mekanis pada wedge bersudut tetap","Mengubah frekuensi pulsa pada setiap pulse repetition","Mengganti crystal dengan sudut refraksi berbeda untuk tiap pengukuran"]', 0,
   'PAUT menggunakan banyak elemen kecil yang dieksitasi dengan time delay terprogram; pengaturan urutan delay inilah yang men-steer dan memfokuskan beam tanpa gerakan mekanis.', 'paut', 'easy'),
  ('Pola time delay yang dihitung untuk setiap elemen guna menghasilkan sudut, fokus, dan exit point beam tertentu disebut:',
   '["DAC curve","Pulse repetition table","Focal law","Snell envelope"]', 2,
   'Focal law adalah kumpulan time delay (transmit dan receive) per elemen yang mendefinisikan sudut, kedalaman fokus, dan exit point sebuah beam PAUT.', 'paut', 'easy'),
  ('Sectorial scan (S-scan) pada PAUT menampilkan:',
   '["Satu beam pada satu sudut tetap yang disapu secara mekanis","Tampilan top-down amplitudo seperti C-scan immersion","Profil ketebalan dinding sepanjang sumbu pipa","Rentang sudut beam (misal 40°–70°) dari satu posisi probe dalam satu citra kipas"]', 3,
   'Pada S-scan, focal law menyapu serangkaian sudut dari satu aperture sehingga menghasilkan citra kipas (sektor) yang mencakup banyak sudut sekaligus tanpa memindahkan probe.', 'paut', 'medium'),
  ('Kalibrasi sensitivitas PAUT (mis. encoded/ECA dengan TCG atau ACG) yang benar harus diverifikasi pada:',
   '["Hanya pada sudut tengah karena sudut lain mengikuti otomatis","Setiap sudut/beam dalam focal law karena sensitivitas berbeda di tiap sudut","Hanya pada beam dengan amplitudo tertinggi","Sudut 90° saja sebagai referensi back-wall"]', 1,
   'Setiap focal law/sudut memiliki respons sensitivitas yang berbeda akibat variasi aperture dan atenuasi wedge, sehingga kalibrasi (TCG/ACG) harus dinormalisasi per beam, bukan hanya satu sudut.', 'calibration', 'medium'),
  ('Keunggulan utama PAUT dibandingkan conventional UT angle beam tunggal adalah:',
   '["Tidak memerlukan couplant pada permukaan benda uji","Menghilangkan kebutuhan kalibrasi dan reference block","Cakupan multi-sudut dari satu posisi probe dengan kecepatan dan imaging lebih baik","Mengukur kecepatan suara material secara otomatis tanpa input operator"]', 2,
   'PAUT memindai banyak sudut dari satu posisi probe (S-scan) sehingga memberi cakupan lebih luas, inspeksi lebih cepat, dan imaging (S/B-scan) yang lebih mudah diinterpretasi; couplant dan kalibrasi tetap diperlukan.', 'paut', 'medium'),
  ('Salah satu trade-off atau keterbatasan PAUT dibanding conventional UT adalah:',
   '["Tidak bisa mendeteksi cacat planar sama sekali","Tidak mampu menghasilkan A-scan untuk analisis sinyal","Hanya bisa digunakan pada material non-logam","Kompleksitas setup focal law, kebutuhan kualifikasi, dan biaya peralatan lebih tinggi"]', 3,
   'PAUT memerlukan pengaturan focal law yang kompleks, perangkat dan probe lebih mahal, serta operator dan prosedur yang harus diqualifikasi; A-scan tiap beam tetap tersedia untuk evaluasi.', 'paut', 'medium'),
  ('Penerimaan UT (termasuk PAUT/encoded UT) sebagai pengganti radiografi pada las pressure vessel di bawah ASME, sebelum diadopsi penuh ke Section V Article 4 (mandatory appendix), pertama kali diizinkan melalui:',
   '["Code Case 2235","ASME B31.3 chapter VI","API 1104 Annex A","AWS D1.1 Annex S"]', 0,
   'ASME Code Case 2235 adalah mekanisme yang mengizinkan UT (termasuk PAUT/encoded UT) menggantikan RT pada las pressure vessel dengan kriteria penerimaan berbasis flaw, mendahului appendix mandatory di Section V Article 4.', 'code', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'UT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 6 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;
